fn scene_pack_route_plan_for_task(start_room_id: &str, task_id: &str) -> NativeBevySceneRoutePlan {
    let scene_pack = native_bevy_scene_pack_fixture();
    let Some(task) = scene_pack_task(task_id) else {
        return NativeBevySceneRoutePlan {
            contract_version: TRILLIONNIUM_WORLD_BEVY_SCENE_PACK_ROUTE_DIRECTOR_CONTRACT
                .to_string(),
            task_id: task_id.to_string(),
            task_title: "unknown".to_string(),
            start_room_id: start_room_id.to_string(),
            target_room_id: "unknown".to_string(),
            target_room_name: "unknown".to_string(),
            unlock_rule: "missing_task".to_string(),
            path_room_ids: Vec::new(),
            steps: Vec::new(),
            generated_button_actions: Vec::new(),
            blocked_reason: Some(format!("task_missing:{task_id}")),
        };
    };
    let target_room_id = task
        .room_ids
        .last()
        .cloned()
        .unwrap_or_else(|| start_room_id.to_string());
    let target_room_name = scene_pack
        .rooms
        .iter()
        .find(|room| room.room_id == target_room_id)
        .map(|room| room.label.clone())
        .unwrap_or_else(|| target_room_id.clone());
    let route_waypoint_room_ids = task
        .room_ids
        .iter()
        .position(|room_id| room_id == start_room_id)
        .map(|start_index| task.room_ids[start_index..].to_vec())
        .unwrap_or_else(|| task.room_ids.clone());
    let route = ordered_scene_pack_task_path(&scene_pack, start_room_id, &route_waypoint_room_ids);
    let blocked_reason = if route.is_some() {
        None
    } else {
        Some(format!("route_missing:{start_room_id}->{target_room_id}"))
    };
    let path_room_ids = route.unwrap_or_default();
    let steps = path_room_ids
        .windows(2)
        .map(|pair| NativeBevySceneRouteStep {
            from_room_id: pair[0].clone(),
            to_room_id: pair[1].clone(),
            action_label: native_control_action_label(&NativeControlAction::EnterRoom {
                room_id: pair[1].clone(),
            }),
        })
        .collect::<Vec<_>>();
    let generated_button_actions = steps
        .iter()
        .map(|step| step.action_label.clone())
        .collect::<Vec<_>>();
    NativeBevySceneRoutePlan {
        contract_version: TRILLIONNIUM_WORLD_BEVY_SCENE_PACK_ROUTE_DIRECTOR_CONTRACT.to_string(),
        task_id: task.task_id,
        task_title: task.title,
        start_room_id: start_room_id.to_string(),
        target_room_id,
        target_room_name,
        unlock_rule: task.unlock_rule,
        path_room_ids,
        steps,
        generated_button_actions,
        blocked_reason,
    }
}

fn shortest_scene_pack_room_path(
    scene_pack: &NativeBevyScenePack,
    start_room_id: &str,
    target_room_id: &str,
) -> Option<Vec<String>> {
    if start_room_id == target_room_id {
        return Some(vec![start_room_id.to_string()]);
    }
    let rooms = scene_pack
        .rooms
        .iter()
        .map(|room| (room.room_id.as_str(), room))
        .collect::<HashMap<_, _>>();
    if !rooms.contains_key(start_room_id) || !rooms.contains_key(target_room_id) {
        return None;
    }
    let mut queue = VecDeque::from([start_room_id.to_string()]);
    let mut previous: HashMap<String, String> = HashMap::new();
    previous.insert(start_room_id.to_string(), String::new());
    while let Some(room_id) = queue.pop_front() {
        let Some(room) = rooms.get(room_id.as_str()) else {
            continue;
        };
        for next_room_id in &room.exits {
            if !rooms.contains_key(next_room_id.as_str()) || previous.contains_key(next_room_id) {
                continue;
            }
            previous.insert(next_room_id.clone(), room_id.clone());
            if next_room_id == target_room_id {
                let mut path = vec![target_room_id.to_string()];
                let mut cursor = target_room_id.to_string();
                while let Some(parent) = previous.get(&cursor) {
                    if parent.is_empty() {
                        break;
                    }
                    path.push(parent.clone());
                    cursor = parent.clone();
                }
                path.reverse();
                return Some(path);
            }
            queue.push_back(next_room_id.clone());
        }
    }
    None
}

fn ordered_scene_pack_task_path(
    scene_pack: &NativeBevyScenePack,
    start_room_id: &str,
    waypoint_room_ids: &[String],
) -> Option<Vec<String>> {
    let mut full_path = vec![start_room_id.to_string()];
    let mut cursor = start_room_id.to_string();
    for waypoint_room_id in waypoint_room_ids {
        if &cursor == waypoint_room_id {
            continue;
        }
        let segment = shortest_scene_pack_room_path(scene_pack, &cursor, waypoint_room_id)?;
        full_path.extend(segment.into_iter().skip(1));
        cursor = waypoint_room_id.clone();
    }
    Some(full_path)
}

fn scene_pack_route_actions(plan: &NativeBevySceneRoutePlan) -> Vec<NativeControlAction> {
    plan.steps
        .iter()
        .map(|step| NativeControlAction::EnterRoom {
            room_id: step.to_room_id.clone(),
        })
        .collect()
}

fn scene_pack_path_is_valid(plan: &NativeBevySceneRoutePlan) -> bool {
    if plan.blocked_reason.is_some() || plan.path_room_ids.is_empty() {
        return false;
    }
    plan.path_room_ids.windows(2).all(|pair| {
        scene_pack_room(&pair[0])
            .map(|room| room.exits.iter().any(|exit| exit == &pair[1]))
            .unwrap_or(false)
    })
}

