fn push_contextual_action(
    runtime: &NativeFirstPlayableRuntime,
    entries: &mut Vec<NativeBevyContextualAction>,
    action: NativeControlAction,
    action_kind: &str,
    source: &str,
) {
    let label = native_control_action_label(&action);
    if entries.iter().any(|entry| entry.label == label) {
        return;
    }
    let (enabled, reason) = native_live_action_availability(runtime, &action);
    entries.push(NativeBevyContextualAction {
        label,
        action_kind: action_kind.to_string(),
        source: source.to_string(),
        enabled,
        reason,
        primary: false,
    });
}

fn contextual_primary_action_label(entries: &[NativeBevyContextualAction]) -> Option<String> {
    for label in ["TALK", "TRAIN"] {
        if entries
            .iter()
            .any(|entry| entry.enabled && entry.label == label)
        {
            return Some(label.to_string());
        }
    }
    for kind in ["combat", "task", "loot", "equipment", "npc", "room_exit"] {
        if let Some(entry) = entries
            .iter()
            .find(|entry| entry.enabled && entry.action_kind == kind)
        {
            return Some(entry.label.clone());
        }
    }
    entries
        .iter()
        .find(|entry| entry.enabled)
        .map(|entry| entry.label.clone())
}

fn refresh_contextual_action_runtime(runtime: &mut NativeFirstPlayableRuntime) {
    let deck = native_contextual_action_deck(runtime);
    runtime.contextual_action_labels = deck
        .actions
        .iter()
        .filter(|entry| entry.enabled)
        .map(|entry| entry.label.clone())
        .collect();
    runtime.contextual_primary_action_label = deck.primary_action_label.clone();
    push_history(
        &mut runtime.contextual_action_history,
        &format!(
            "contextual_deck:{}:{}",
            runtime.current_room_id,
            deck.primary_action_label
                .clone()
                .unwrap_or_else(|| "none".to_string())
        ),
    );
}

