fn build_branch_title_recommended_task_id_for_runtime_stat(
    runtime: &NativeFirstPlayableRuntime,
    stat_id: &str,
) -> Option<&'static str> {
    let followup_task_id = build_branch_followup_task_id_for_stat(stat_id)?;
    if !runtime
        .completed_task_ids
        .iter()
        .any(|task_id| task_id == followup_task_id)
    {
        return Some(followup_task_id);
    }
    let mastery_challenge_task_id = build_branch_mastery_challenge_task_id_for_stat(stat_id)?;
    if !runtime
        .completed_task_ids
        .iter()
        .any(|task_id| task_id == mastery_challenge_task_id)
    {
        return Some(mastery_challenge_task_id);
    }
    None
}

