fn active_build_title_route_recommendation_parts(
    runtime: &NativeFirstPlayableRuntime,
) -> Option<(&str, &'static str, &str, &'static str)> {
    let (title_id, stat_id, effect_id) = active_build_title_parts(runtime)?;
    let task_id = build_branch_title_recommended_task_id_for_runtime_stat(runtime, stat_id)?;
    Some((title_id, stat_id, effect_id, task_id))
}

fn build_branch_title_route_recommendation_text(runtime: &NativeFirstPlayableRuntime) -> String {
    if let Some((_, stat_id, effect_id, task_id)) =
        active_build_title_route_recommendation_parts(runtime)
    {
        let label = build_branch_mastery_title_label(stat_id);
        let next = runtime
            .route_director_next_room_id
            .clone()
            .unwrap_or_else(|| "arrived".to_string());
        format!(
                "TITLE ROUTE | active {label} recommends {stat_id}:{task_id} via {effect_id} | director {} next {next}",
                runtime.route_director_task_id
            )
    } else if let Some((_, stat_id, effect_id)) = active_build_title_parts(runtime) {
        let label = build_branch_mastery_title_label(stat_id);
        let next = runtime
            .route_director_next_room_id
            .clone()
            .unwrap_or_else(|| "arrived".to_string());
        format!(
            "TITLE ROUTE | active {label} complete {stat_id} via {effect_id} | director {} next {next}",
            runtime.route_director_task_id
        )
    } else {
        "TITLE ROUTE | active none recommends none".to_string()
    }
}

fn build_branch_title_loadout_status(
    runtime: &NativeFirstPlayableRuntime,
    stat_id: &str,
) -> String {
    if build_branch_mastery_title_id_for_stat(stat_id)
        .is_some_and(|title_id| runtime.active_build_title_id.as_deref() == Some(title_id))
    {
        "active".to_string()
    } else if build_branch_mastery_title_id_for_stat(stat_id)
        .is_some_and(|title_id| runtime_has_build_title_id(runtime, title_id))
    {
        "equippable".to_string()
    } else {
        format!("locked_requires_{stat_id}_mastery_challenge")
    }
}

fn build_branch_title_loadout_text(runtime: &NativeFirstPlayableRuntime) -> String {
    let active_title = active_build_title_label_text(runtime);
    let rows = ["force", "agility", "craft"]
        .into_iter()
        .map(|stat_id| {
            let title_id =
                build_branch_mastery_title_id_for_stat(stat_id).unwrap_or("custom-title");
            let effect_id =
                build_branch_mastery_title_effect_for_stat(stat_id).unwrap_or("custom_effect");
            let action = NativeControlAction::EquipBuildTitle {
                title_id: title_id.to_string(),
            };
            let (_, reason) = native_live_action_availability(runtime, &action);
            format!(
                "{stat_id}:{title_id}:{} -> {} effect {effect_id} action {} reason {reason}",
                build_branch_title_loadout_status(runtime, stat_id),
                build_branch_mastery_title_label(stat_id),
                native_control_action_label(&action)
            )
        })
        .collect::<Vec<_>>()
        .join(" | ");
    format!(
        "TITLE LOADOUT | active {active_title} | {rows}\n{}\n{}\n{}\n{}",
        build_branch_title_route_progress_summary_text(runtime),
        build_branch_title_route_action_dashboard_text(runtime),
        build_branch_title_route_action_focus_text(runtime),
        build_branch_title_route_action_confirm_text(runtime)
    )
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct BuildBranchTitleRouteActionRow {
    stat_id: String,
    status: String,
    reward_item_id: String,
    action_label: String,
    enabled: bool,
    reason: String,
}

fn build_branch_title_route_progress_status(
    runtime: &NativeFirstPlayableRuntime,
    followup_task_id: &str,
    mastery_task_id: &str,
) -> &'static str {
    if runtime
        .completed_task_ids
        .iter()
        .any(|task_id| task_id == mastery_task_id)
    {
        "complete"
    } else if runtime
        .active_task_ids
        .iter()
        .any(|task_id| task_id == mastery_task_id)
    {
        "mastery_active"
    } else if runtime
        .unlocked_task_ids
        .iter()
        .any(|task_id| task_id == mastery_task_id)
    {
        "mastery_ready"
    } else if runtime
        .completed_task_ids
        .iter()
        .any(|task_id| task_id == followup_task_id)
    {
        "followup_complete"
    } else if runtime
        .active_task_ids
        .iter()
        .any(|task_id| task_id == followup_task_id)
    {
        "followup_active"
    } else if runtime
        .unlocked_task_ids
        .iter()
        .any(|task_id| task_id == followup_task_id)
    {
        "followup_ready"
    } else {
        "locked"
    }
}

fn build_branch_title_route_progress_next(
    runtime: &NativeFirstPlayableRuntime,
    stat_id: &str,
    title_id: &str,
    status: &str,
) -> String {
    if status == "complete" {
        return format!("title_route_complete:{stat_id}");
    }
    if !runtime_has_build_title_id(runtime, title_id) {
        return format!("unlock_title:{title_id}");
    }
    if active_build_title_parts(runtime)
        .is_some_and(|(_, active_stat_id, _)| active_stat_id == stat_id)
    {
        let (_, reason) = active_build_title_route_accept_availability(runtime);
        return reason;
    }
    format!("equip:{title_id}")
}

fn build_branch_title_route_progress_summary_text(runtime: &NativeFirstPlayableRuntime) -> String {
    let rows = ["force", "agility", "craft"]
        .into_iter()
        .map(|stat_id| {
            let title_id =
                build_branch_mastery_title_id_for_stat(stat_id).unwrap_or("custom-title");
            let followup_task_id =
                build_branch_followup_task_id_for_stat(stat_id).unwrap_or("custom-followup");
            let mastery_task_id = build_branch_mastery_challenge_task_id_for_stat(stat_id)
                .unwrap_or("custom-mastery-challenge");
            let (_, _, reward_item_id, _) = build_branch_mastery_challenge_reward(mastery_task_id);
            let status = build_branch_title_route_progress_status(
                runtime,
                followup_task_id,
                mastery_task_id,
            );
            let next = build_branch_title_route_progress_next(runtime, stat_id, title_id, status);
            format!("{stat_id}:{status} reward {reward_item_id} next {next}")
        })
        .collect::<Vec<_>>()
        .join(" | ");
    format!("TITLE ROUTE SUMMARY | {rows}")
}

fn build_branch_title_route_action_dashboard_row(
    runtime: &NativeFirstPlayableRuntime,
    stat_id: &str,
) -> BuildBranchTitleRouteActionRow {
    let title_id = build_branch_mastery_title_id_for_stat(stat_id).unwrap_or("custom-title");
    let followup_task_id =
        build_branch_followup_task_id_for_stat(stat_id).unwrap_or("custom-followup");
    let mastery_task_id =
        build_branch_mastery_challenge_task_id_for_stat(stat_id).unwrap_or("custom-mastery");
    let (_, _, reward_item_id, _) = build_branch_mastery_challenge_reward(mastery_task_id);
    let status =
        build_branch_title_route_progress_status(runtime, followup_task_id, mastery_task_id);
    let (action_label, enabled, reason) = build_branch_title_route_action_dashboard_action(
        runtime,
        stat_id,
        title_id,
        followup_task_id,
        mastery_task_id,
        status,
    );
    BuildBranchTitleRouteActionRow {
        stat_id: stat_id.to_string(),
        status: status.to_string(),
        reward_item_id: reward_item_id.to_string(),
        action_label,
        enabled,
        reason,
    }
}

fn build_branch_title_route_action_dashboard_rows(
    runtime: &NativeFirstPlayableRuntime,
) -> Vec<BuildBranchTitleRouteActionRow> {
    ["force", "agility", "craft"]
        .into_iter()
        .map(|stat_id| build_branch_title_route_action_dashboard_row(runtime, stat_id))
        .collect()
}

fn build_branch_title_route_action_dashboard_action(
    runtime: &NativeFirstPlayableRuntime,
    stat_id: &str,
    title_id: &str,
    followup_task_id: &str,
    mastery_task_id: &str,
    status: &str,
) -> (String, bool, String) {
    if status == "complete" {
        return (
            "DONE".to_string(),
            false,
            format!("title_route_complete:{stat_id}"),
        );
    }
    if !runtime_has_build_title_id(runtime, title_id) {
        return (
            format!("TITLE:EQUIP:{title_id}"),
            false,
            format!("unlock_title:{title_id}"),
        );
    }
    if active_build_title_parts(runtime)
        .is_none_or(|(_, active_stat_id, _)| active_stat_id != stat_id)
    {
        let action = NativeControlAction::EquipBuildTitle {
            title_id: title_id.to_string(),
        };
        let (enabled, reason) = native_live_action_availability(runtime, &action);
        return (native_control_action_label(&action), enabled, reason);
    }
    if status == "followup_active"
        && runtime
            .active_task_ids
            .iter()
            .any(|task_id| task_id == followup_task_id)
    {
        let action = NativeControlAction::CompleteTask;
        let (enabled, reason) = native_live_action_availability(runtime, &action);
        return (native_control_action_label(&action), enabled, reason);
    }
    if status == "mastery_active"
        && runtime
            .active_task_ids
            .iter()
            .any(|task_id| task_id == mastery_task_id)
    {
        let action = NativeControlAction::CompleteTask;
        let (enabled, reason) = native_live_action_availability(runtime, &action);
        return (native_control_action_label(&action), enabled, reason);
    }
    let action = NativeControlAction::AcceptTitleRouteRecommendation;
    let (enabled, reason) = native_live_action_availability(runtime, &action);
    (native_control_action_label(&action), enabled, reason)
}

fn build_branch_title_route_action_dashboard_text(runtime: &NativeFirstPlayableRuntime) -> String {
    let rows = build_branch_title_route_action_dashboard_rows(runtime)
        .into_iter()
        .map(|row| {
            format!(
                "{}:{} reward {} action {} enabled {} reason {}",
                row.stat_id,
                row.status,
                row.reward_item_id,
                row.action_label,
                row.enabled,
                row.reason
            )
        })
        .collect::<Vec<_>>()
        .join(" | ");
    format!("TITLE ROUTE DASHBOARD | {rows}")
}

fn build_branch_title_route_action_focus(
    runtime: &NativeFirstPlayableRuntime,
) -> Option<BuildBranchTitleRouteActionRow> {
    let rows = build_branch_title_route_action_dashboard_rows(runtime);
    if let Some((_, active_stat_id, _)) = active_build_title_parts(runtime) {
        if let Some(row) = rows
            .iter()
            .find(|row| row.stat_id == active_stat_id && row.status != "complete")
        {
            return Some(row.clone());
        }
    }
    rows.into_iter()
        .find(|row| row.enabled && row.action_label != "DONE")
}

fn build_branch_title_route_action_focus_text(runtime: &NativeFirstPlayableRuntime) -> String {
    build_branch_title_route_action_focus(runtime).map_or_else(
        || {
            "TITLE ROUTE FOCUS | none action DONE enabled false reason all_title_routes_complete"
                .to_string()
        },
        |focus| {
            format!(
                "TITLE ROUTE FOCUS | {}:{} reward {} action {} enabled {} reason {}",
                focus.stat_id,
                focus.status,
                focus.reward_item_id,
                focus.action_label,
                focus.enabled,
                focus.reason
            )
        },
    )
}

fn build_branch_title_route_action_confirm_text(runtime: &NativeFirstPlayableRuntime) -> String {
    build_branch_title_route_action_focus(runtime).map_or_else(
        || {
            "TITLE ROUTE CONFIRM | key Enter/NumpadEnter action DONE enabled false reason all_title_routes_complete"
                .to_string()
        },
        |focus| {
            format!(
                "TITLE ROUTE CONFIRM | key Enter/NumpadEnter action {} enabled {} reason {}",
                focus.action_label, focus.enabled, focus.reason
            )
        },
    )
}

fn build_branch_title_route_action_confirm_hud_text(
    runtime: &NativeFirstPlayableRuntime,
) -> String {
    build_branch_title_route_action_focus(runtime).map_or_else(
        || "Enter/NumpadEnter -> none [all_title_routes_complete]".to_string(),
        |focus| {
            if focus.action_label == "DONE" {
                format!("Enter/NumpadEnter -> none [{}]", focus.reason)
            } else {
                format!(
                    "Enter/NumpadEnter -> {} [{}]",
                    focus.action_label, focus.reason
                )
            }
        },
    )
}

fn build_branch_title_route_action_focus_control_action(
    runtime: &NativeFirstPlayableRuntime,
) -> Option<NativeControlAction> {
    let focus = build_branch_title_route_action_focus(runtime)?;
    if focus.action_label == "DONE" {
        return None;
    }
    native_control_action_from_label(&focus.action_label)
}

