fn task_requires_progression_unlock(task_id: &str) -> bool {
    matches!(task_id, "task-arena-rematch-route")
        || build_branch_task_required_stat(task_id).is_some()
        || build_branch_followup_required_stat(task_id).is_some()
        || build_branch_mastery_challenge_required_stat(task_id).is_some()
}

fn runtime_combat_actions(combat_active: bool, has_potion: bool) -> Vec<String> {
    let mut actions = if combat_active {
        vec![
            "attack".to_string(),
            "defend".to_string(),
            "escape".to_string(),
        ]
    } else {
        Vec::new()
    };
    if combat_active && has_potion {
        actions.push("potion".to_string());
    }
    actions
}

