pub fn build_native_bevy_app(world: WorldState, actor_id: &str) -> (App, BevyWorldBridgeReport) {
    let report = report_for_world(&world);
    let mut app = App::new();
    app.add_plugins(MinimalPlugins)
        .add_plugins(TrillionniumWorldBevyPlugin::new(world, actor_id));
    app.update();
    (app, report)
}

pub fn build_rendering_bevy_app(world: WorldState, actor_id: &str) -> (App, BevyWorldBridgeReport) {
    let report = report_for_world(&world);
    let mut app = App::new();
    app.insert_resource(ClearColor(Color::srgb(0.10, 0.16, 0.18)))
        .init_resource::<InputFocus>()
        .add_plugins(DefaultPlugins.set(WindowPlugin {
            primary_window: Some(Window {
                title: "Trillionnium World".to_string(),
                resolution: (960, 540).into(),
                resizable: true,
                ..default()
            }),
            ..default()
        }))
        .add_plugins(TrillionniumWorldBevyPlugin::new(world, actor_id))
        .add_systems(
            Startup,
            (
                spawn_native_render_scene,
                bind_runtime_textures_to_authored_sprite_surfaces,
            )
                .chain(),
        )
        .add_systems(
            Update,
            (
                handle_native_keyboard_input,
                handle_native_control_buttons,
                sync_player_sprite_to_world,
                update_native_visible_actor_runtime,
                update_native_world_hud,
                update_native_game_feedback_visuals,
                update_native_tile_rpg_interaction_ui,
                update_native_tile_rpg_scene_visuals,
                update_native_input_hint_ui,
                update_native_session_recovery_ui,
                update_native_session_slot_ui,
                update_native_session_resume_ui,
                update_native_pause_menu_ui,
                update_native_settings_menu_ui,
                update_native_title_menu_ui,
                update_native_character_create_ui,
                update_native_text_adventure_ui,
                update_native_right_rail_summary_ui,
                update_native_contextual_button_visuals,
                write_native_runtime_probe,
            ),
        );
    app.add_systems(Update, update_native_account_client_ui);
    (app, report)
}

