pub fn run_native_bevy_client(world: WorldState, actor_id: &str) {
    let (mut app, _report) = build_rendering_bevy_app(world, actor_id);
    if let Ok(stage) = env::var("TRNM_WORLD_BEVY_INITIAL_STAGE") {
        seed_rendering_app_for_stage(&mut app, actor_id, &stage);
    } else {
        seed_rendering_app_title_menu_state(&mut app);
    }
    app.run();
}

fn seed_rendering_app_title_menu_state(app: &mut App) {
    let mut first_playable = app.world_mut().resource_mut::<NativeFirstPlayableRuntime>();
    open_title_menu(&mut first_playable);
    refresh_contextual_action_runtime(&mut first_playable);
}

pub fn seed_rendering_app_title_menu(app: &mut App) {
    seed_rendering_app_title_menu_state(app);
    app.update();
}

pub fn seed_rendering_app_for_stage(app: &mut App, actor_id: &str, stage: &str) {
    let mut world = native_bevy_playable_fixture();
    let mut character = WorldTrillionniumCharacter::default_for(actor_id);
    let mut gameplay_log = NativeGameplayLog {
        turn: 0,
        last_action: "boot".to_string(),
        last_result: "native_bevy_client_ready".to_string(),
        last_rejection: None,
    };
    let mut first_playable = NativeFirstPlayableRuntime::default();
    let guarded_seed = matches!(
        stage,
        "contextual_button_guard" | "button_guard" | "disabled_button_guard" | "pause_menu"
    );
    for action in scripted_actions_for_stage(stage) {
        if guarded_seed {
            apply_live_native_action(
                &mut world,
                &mut character,
                &mut gameplay_log,
                &mut first_playable,
                actor_id,
                action,
            );
        } else {
            apply_native_first_playable_action(
                &mut world,
                &mut character,
                &mut gameplay_log,
                &mut first_playable,
                actor_id,
                action,
            );
        }
    }
    app.insert_resource(AuthoritativeWorldResource {
        state: world.clone(),
    });
    app.insert_resource(NativeTacticsCharacter { character });
    app.insert_resource(gameplay_log);
    app.insert_resource(first_playable);
    app.insert_resource(projection_resource(&world, actor_id));
}

fn scripted_actions_for_stage(stage: &str) -> Vec<NativeControlAction> {
    match stage {
        "dialogue" => vec![NativeControlAction::Talk],
        "training_room" | "training" | "indoor" => {
            vec![NativeControlAction::Talk, NativeControlAction::Train]
        }
        "arena" | "move" => vec![
            NativeControlAction::Talk,
            NativeControlAction::Train,
            NativeControlAction::Move {
                direction: "north".to_string(),
            },
        ],
        "combat" => vec![
            NativeControlAction::Talk,
            NativeControlAction::Train,
            NativeControlAction::Move {
                direction: "north".to_string(),
            },
            NativeControlAction::Fight,
        ],
        "visible_actor_runtime" | "visible_actor" | "visible" => {
            visible_actor_progression_actions(false)
        }
        "progression" | "progression_loop" | "next_task" => visible_actor_progression_actions(true),
        "route_director" | "scene_pack_route_director" | "director" => {
            scene_pack_route_director_action_sequence()
        }
        "contextual_actions" | "action_deck" | "contextual_action_deck" => {
            scene_pack_route_director_action_sequence()
        }
        "contextual_button_state" | "button_state" | "button_visuals" => {
            scene_pack_route_director_action_sequence()
        }
        "contextual_button_guard" | "button_guard" | "disabled_button_guard" => {
            contextual_button_guard_action_sequence()
        }
        "character_create" | "create_character" | "new_game_profile" => {
            vec![NativeControlAction::NewGameFromTitle]
        }
        "pause_menu" => vec![NativeControlAction::PauseMenu],
        _ => Vec::new(),
    }
}

pub fn native_bevy_playable_fixture() -> WorldState {
    let mut world = WorldState::trillionnium_default_map_fixture();
    if !world
        .npcs
        .iter()
        .any(|npc| npc.id == "npc-street-compass-sifu")
    {
        world.npcs.push(WorldNpc {
            id: "npc-street-compass-sifu".to_string(),
            name: "Street Compass Sifu".to_string(),
            node_id: "mirror-city-square".to_string(),
            teaches_skills: vec!["basic_unarmed".to_string()],
        });
    }
    if !world
        .tasks
        .iter()
        .any(|task| task.id == "task-fixture-first-route")
    {
        world.tasks.push(WorldTask {
            id: "task-fixture-first-route".to_string(),
            title: "Reach the League Coliseum objective".to_string(),
            node_id: "league-coliseum".to_string(),
            reward_units: 10,
            ledger_settlement_required: true,
        });
    }
    for npc in [
        WorldNpc {
            id: "npc-starter-artisan".to_string(),
            name: "Starter Studio Artisan".to_string(),
            node_id: "starter-studio".to_string(),
            teaches_skills: vec!["starter_forge".to_string()],
        },
        WorldNpc {
            id: "npc-market-clerk".to_string(),
            name: "Market Gate Clerk".to_string(),
            node_id: "zbj-market-gate".to_string(),
            teaches_skills: Vec::new(),
        },
        WorldNpc {
            id: "npc-client-runner".to_string(),
            name: "Client Board Runner".to_string(),
            node_id: "client-board".to_string(),
            teaches_skills: Vec::new(),
        },
        WorldNpc {
            id: "npc-dock-courier".to_string(),
            name: "Delivery Dock Courier".to_string(),
            node_id: "delivery-dock".to_string(),
            teaches_skills: Vec::new(),
        },
    ] {
        if !world.npcs.iter().any(|existing| existing.id == npc.id) {
            world.npcs.push(npc);
        }
    }
    for task in [
        WorldTask {
            id: "task-starter-forge-intro".to_string(),
            title: "Forge the starter route token".to_string(),
            node_id: "starter-studio".to_string(),
            reward_units: 6,
            ledger_settlement_required: false,
        },
        WorldTask {
            id: "task-market-client-intro".to_string(),
            title: "Read the first client board commission".to_string(),
            node_id: "client-board".to_string(),
            reward_units: 8,
            ledger_settlement_required: false,
        },
    ] {
        if !world.tasks.iter().any(|existing| existing.id == task.id) {
            world.tasks.push(task);
        }
    }
    world
}

