fn native_action_session_save_slot_path() -> String {
    env::var("TRNM_WORLD_BEVY_SESSION_SAVE_SLOT_PATH")
        .unwrap_or_else(|_| "target/trnm-world-bevy-session-action-slot.json".to_string())
}

fn native_session_slot_ids() -> [&'static str; 3] {
    ["A", "B", "C"]
}

fn normalize_session_slot_id(slot_id: &str) -> String {
    let normalized = slot_id
        .chars()
        .filter(|ch| ch.is_ascii_alphanumeric())
        .collect::<String>()
        .to_ascii_uppercase();
    if normalized.is_empty() {
        "A".to_string()
    } else {
        normalized
    }
}

fn native_action_session_slot_dir() -> String {
    env::var("TRNM_WORLD_BEVY_SESSION_SLOT_DIR")
        .unwrap_or_else(|_| "target/trnm-world-bevy-session-slots".to_string())
}

fn native_action_session_slot_path(slot_id: &str) -> String {
    let slot_id = normalize_session_slot_id(slot_id);
    Path::new(&native_action_session_slot_dir())
        .join(format!(
            "bevy-session-slot-{}.snapshot.json",
            slot_id.to_ascii_lowercase()
        ))
        .to_string_lossy()
        .to_string()
}

fn native_session_slot_statuses() -> Vec<NativeSessionSlotStatus> {
    native_session_slot_statuses_for("A", None)
}

fn native_session_slot_statuses_for(
    selected_slot_id: &str,
    overwrite_pending_slot_id: Option<&str>,
) -> Vec<NativeSessionSlotStatus> {
    let selected_slot_id = normalize_session_slot_id(selected_slot_id);
    let overwrite_pending_slot_id = overwrite_pending_slot_id.map(normalize_session_slot_id);
    native_session_slot_ids()
        .iter()
        .map(|slot_id| {
            let path = native_action_session_slot_path(slot_id);
            let bytes = fs::metadata(&path)
                .map(|metadata| metadata.len())
                .unwrap_or(0);
            let exists = bytes > 0 && Path::new(&path).exists();
            let load_reason = if exists {
                format!("enabled_session_slot_found:{slot_id}")
            } else {
                format!("session_slot_missing:{slot_id}")
            };
            let active_title_label = if exists {
                read_native_playable_snapshot_slot(&path)
                    .ok()
                    .map(|snapshot| active_build_title_label_text(&snapshot.first_playable))
                    .unwrap_or_else(|| "unreadable".to_string())
            } else {
                "none".to_string()
            };
            let selected = selected_slot_id == *slot_id;
            let overwrite_pending = overwrite_pending_slot_id.as_deref() == Some(*slot_id);
            let visible_label = if exists {
                format!(
                    "{}{slot_id}:saved {bytes}B LOAD {load_reason} TITLE {active_title_label}{}",
                    if selected { "SELECTED " } else { "" },
                    if overwrite_pending {
                        " PENDING overwrite"
                    } else {
                        ""
                    }
                )
            } else {
                format!(
                    "{}{slot_id}:empty LOAD {load_reason} TITLE {active_title_label}{}",
                    if selected { "SELECTED " } else { "" },
                    if overwrite_pending {
                        " PENDING overwrite"
                    } else {
                        ""
                    }
                )
            };
            NativeSessionSlotStatus {
                slot_id: (*slot_id).to_string(),
                path,
                exists,
                bytes,
                load_reason,
                selected,
                overwrite_pending,
                visible_label,
            }
        })
        .collect()
}

fn session_slot_status_text(runtime: &NativeFirstPlayableRuntime) -> String {
    let save_reason = if runtime.input_feedback_history.is_empty() {
        "session_checkpoint_requires_input_history"
    } else {
        "enabled_session_checkpoint"
    };
    let selected_slot = normalize_session_slot_id(&runtime.session_selected_slot_id);
    let pending_slot = runtime.session_overwrite_pending_slot_id.as_deref();
    let slot_status = native_session_slot_statuses_for(&selected_slot, pending_slot)
        .into_iter()
        .map(|status| status.visible_label)
        .collect::<Vec<_>>()
        .join(" | ");
    let pending = runtime
        .session_overwrite_pending_slot_id
        .as_deref()
        .map(normalize_session_slot_id)
        .unwrap_or_else(|| "none".to_string());
    format!("SLOTS selected:{selected_slot} pending:{pending} save:{save_reason} | {slot_status}")
}

fn mark_session_resume_overlay(runtime: &mut NativeFirstPlayableRuntime, slot_id: &str) {
    let slot_id = normalize_session_slot_id(slot_id);
    runtime.session_pause_menu_visible = false;
    runtime.session_pause_input_locked = false;
    runtime.session_pause_reason_text = "none".to_string();
    runtime.session_settings_menu_visible = false;
    runtime.session_title_menu_visible = false;
    runtime.session_title_input_locked = false;
    runtime.session_title_boot_state = "resume_overlay".to_string();
    runtime.session_character_create_visible = false;
    runtime.session_character_create_input_locked = false;
    runtime.session_resume_overlay_visible = true;
    runtime.session_resume_input_locked = true;
    runtime.session_continue_cta_visible = true;
    runtime.session_resume_source_slot_id = Some(slot_id.clone());
    runtime.session_resume_toast_text =
        format!("Restore complete from slot {slot_id}; press CONTINUE");
    push_progression_checkpoint(runtime, "session_snapshot_restored");
    push_progression_checkpoint(runtime, &format!("session_resume_from:{slot_id}"));
    push_history(
        &mut runtime.session_resume_history,
        &format!("session_resume_from:{slot_id}"),
    );
    let toast = runtime.session_resume_toast_text.clone();
    push_feedback_event(runtime, &toast);
}

fn clear_session_resume_overlay(runtime: &mut NativeFirstPlayableRuntime) {
    let slot_id = runtime
        .session_resume_source_slot_id
        .clone()
        .unwrap_or_else(|| "unknown".to_string());
    runtime.session_resume_overlay_visible = false;
    runtime.session_resume_input_locked = false;
    runtime.session_continue_cta_visible = false;
    runtime.session_title_boot_state = "game_active".to_string();
    runtime.session_resume_toast_text = format!("Map controls restored after slot {slot_id}");
    push_history(
        &mut runtime.session_resume_history,
        &format!("session_resume_continued:{slot_id}"),
    );
    let toast = runtime.session_resume_toast_text.clone();
    push_feedback_event(runtime, &toast);
}

fn session_resume_status_text(runtime: &NativeFirstPlayableRuntime) -> String {
    if runtime.session_resume_input_locked || runtime.session_continue_cta_visible {
        format!(
            "RESUME ACTIVE | {} | input locked | CTA CONTINUE",
            runtime.session_resume_toast_text
        )
    } else if let Some(slot_id) = runtime.session_resume_source_slot_id.as_deref() {
        format!("RESUME READY | map controls active | last slot {slot_id}")
    } else {
        "RESUME READY | map controls active".to_string()
    }
}

