fn character_for_creation(
    actor_id: &str,
    name: &str,
    archetype: &str,
) -> WorldTrillionniumCharacter {
    let mut character = WorldTrillionniumCharacter::default_for(actor_id);
    character.display_name = name.to_string();
    character.title = format!("{} starter", archetype);
    match archetype {
        "artisan" => {
            character.attributes.craft = 15;
            character.attributes.insight = 14;
            character.attributes.commerce = 12;
            character.attributes.force = 9;
            push_unique_string(&mut character.skill_ids, "starter_craft");
        }
        "scout" => {
            character.attributes.agility = 15;
            character.attributes.insight = 14;
            character.attributes.physique = 11;
            character.attributes.craft = 9;
            push_unique_string(&mut character.skill_ids, "starter_scouting");
        }
        _ => {
            character.attributes.resolve = 14;
            character.attributes.physique = 13;
            character.attributes.force = 12;
            push_unique_string(&mut character.skill_ids, "starter_balance");
        }
    }
    character.ensure_defaults(native_now_epoch());
    character
}

