fn authored_runtime_material_asset_handle(material_slot: &str) -> String {
    format!("bevy_material_handle::{material_slot}::trnm_world_authored_sprite_sheet_v1")
}

fn authored_runtime_texture_sprite_binding(application: &Value) -> Value {
    let application_id = authored_surface_string(application, "application_id");
    let scene_layer = authored_surface_string(application, "scene_layer");
    let material_slot = authored_surface_string(application, "material_slot");
    let frame_index = application
        .get("frame_index")
        .and_then(Value::as_u64)
        .unwrap_or_default();
    json!({
        "sprite_binding_id": format!("runtime_texture_sprite_binding::{application_id}"),
        "application_id": application_id,
        "scene_layer": scene_layer,
        "runtime_target": sample_pointer_value(application, "/runtime_target"),
        "visible_runtime_surface_id": sample_pointer_value(application, "/visible_runtime_surface_id"),
        "image_asset_handle_id": "bevy_image_handle::trnm_world_authored_sprite_sheet_v1",
        "texture_atlas_layout_handle_id": "bevy_texture_atlas_layout_handle::trnm_world_authored_sprite_sheet_layout_v1",
        "texture_atlas_index": frame_index,
        "material_slot": material_slot,
        "material_asset_handle_id": authored_runtime_material_asset_handle(&material_slot),
        "uv_rect": sample_pointer_value(application, "/uv_rect"),
        "sampler": "ImageSampler::nearest_pixel_art",
        "bevy_component_target": sample_pointer_value(application, "/bevy_consumer_component"),
        "binding_mode": "Handle<Image> + TextureAtlasLayout + texture_atlas_index attached_to_visible_sprite_surface",
        "gpu_upload_claimed": false,
        "android_s5_real_device_claimed": false,
    })
}

pub fn native_runtime_texture_asset_evidence_json(
    actor_id: &str,
    atlas_path: &str,
    manifest_path: &str,
    binding_path: &str,
    consumption_path: &str,
    application_path: &str,
    runtime_asset_path: &str,
) -> String {
    let material_application_evidence: Value =
        serde_json::from_str(&native_authored_material_application_evidence_json(
            actor_id,
            atlas_path,
            manifest_path,
            binding_path,
            consumption_path,
            application_path,
        ))
        .expect("material application evidence parses for runtime texture asset");
    let manifest_text = fs::read_to_string(manifest_path).unwrap_or_default();
    let manifest: Value = serde_json::from_str(&manifest_text).unwrap_or_else(|_| json!({}));
    let application_text = fs::read_to_string(application_path).unwrap_or_default();
    let application_manifest: Value =
        serde_json::from_str(&application_text).unwrap_or_else(|_| json!({}));
    let frames = manifest
        .get("frames")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    let applications = application_manifest
        .get("applications")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    let atlas_columns = manifest
        .get("atlas_columns")
        .and_then(Value::as_u64)
        .unwrap_or(8)
        .max(1);
    let cell_size = manifest
        .get("cell_size_px")
        .and_then(Value::as_u64)
        .unwrap_or(32)
        .max(1);
    let atlas_rows = (frames.len() as u64).div_ceil(atlas_columns).max(1);
    let atlas_width = atlas_columns * cell_size;
    let atlas_height = atlas_rows * cell_size;
    let atlas_bytes = fs::metadata(atlas_path)
        .map(|metadata| metadata.len())
        .unwrap_or_default();
    let atlas_header_gate = fs::read_to_string(atlas_path)
        .ok()
        .and_then(|text| text.lines().next().map(str::to_string))
        == Some("P3".to_string());
    let sprite_bindings = applications
        .iter()
        .map(authored_runtime_texture_sprite_binding)
        .collect::<Vec<_>>();
    let scene_layers = authored_binding_set(&sprite_bindings, "scene_layer");
    let material_slots = authored_binding_set(&sprite_bindings, "material_slot");
    let material_asset_handles = authored_binding_set(&sprite_bindings, "material_asset_handle_id");
    let binding_modes = authored_binding_set(&sprite_bindings, "binding_mode");
    let image_asset_descriptor = json!({
        "asset_kind": "bevy::image::Image",
        "image_asset_handle_id": "bevy_image_handle::trnm_world_authored_sprite_sheet_v1",
        "source_texture_handle_id": "runtime_texture_handle::trnm_world_authored_sprite_sheet_v1",
        "source_path": atlas_path,
        "source_format": "ppm_p3_rgb",
        "runtime_format": "Rgba8UnormSrgb",
        "extent3d": { "width": atlas_width, "height": atlas_height, "depth_or_array_layers": 1 },
        "sampler": "ImageSampler::nearest_pixel_art",
        "usage": "TextureUsages::TEXTURE_BINDING | TextureUsages::COPY_DST",
        "host_side_asset_registration_claimed": true,
        "gpu_upload_claimed": false,
    });
    let texture_atlas_layout_descriptor = json!({
        "asset_kind": "bevy::sprite::TextureAtlasLayout",
        "texture_atlas_layout_handle_id": "bevy_texture_atlas_layout_handle::trnm_world_authored_sprite_sheet_layout_v1",
        "grid_cell_size_px": { "width": cell_size, "height": cell_size },
        "columns": atlas_columns,
        "rows": atlas_rows,
        "frame_count": frames.len(),
        "layout_mode": "TextureAtlasLayout::from_grid(UVec2::splat(32), 8, 4, None, None)",
    });
    let material_asset_manifest = [
        "world_tile_material",
        "hud_icon_material",
        "actor_sprite_material",
        "feedback_glyph_material",
    ]
    .iter()
    .map(|slot| {
        json!({
            "material_slot": slot,
            "material_asset_handle_id": authored_runtime_material_asset_handle(slot),
            "image_asset_handle_id": "bevy_image_handle::trnm_world_authored_sprite_sheet_v1",
            "texture_atlas_layout_handle_id": "bevy_texture_atlas_layout_handle::trnm_world_authored_sprite_sheet_layout_v1",
            "material_kind": "SpriteMaterial/TextureAtlasSpriteMaterial runtime binding",
            "gpu_upload_claimed": false,
        })
    })
    .collect::<Vec<_>>();
    let material_application_gate = material_application_evidence
        .get("green")
        .and_then(Value::as_bool)
        == Some(true);
    let atlas_file_gate = atlas_header_gate && atlas_bytes > 50_000;
    let manifest_frame_gate = frames.len() >= 32
        && manifest
            .get("frame_count")
            .and_then(Value::as_u64)
            .unwrap_or(frames.len() as u64)
            == frames.len() as u64
        && atlas_width == 256
        && atlas_height == 128;
    let runtime_image_descriptor_gate = image_asset_descriptor
        .get("asset_kind")
        .and_then(Value::as_str)
        == Some("bevy::image::Image")
        && image_asset_descriptor
            .get("runtime_format")
            .and_then(Value::as_str)
            == Some("Rgba8UnormSrgb")
        && image_asset_descriptor
            .get("host_side_asset_registration_claimed")
            .and_then(Value::as_bool)
            == Some(true);
    let texture_atlas_layout_gate = texture_atlas_layout_descriptor
        .get("asset_kind")
        .and_then(Value::as_str)
        == Some("bevy::sprite::TextureAtlasLayout")
        && texture_atlas_layout_descriptor
            .get("frame_count")
            .and_then(Value::as_u64)
            .unwrap_or_default()
            >= 32;
    let material_handle_gate = [
        "bevy_material_handle::world_tile_material::trnm_world_authored_sprite_sheet_v1",
        "bevy_material_handle::hud_icon_material::trnm_world_authored_sprite_sheet_v1",
        "bevy_material_handle::actor_sprite_material::trnm_world_authored_sprite_sheet_v1",
        "bevy_material_handle::feedback_glyph_material::trnm_world_authored_sprite_sheet_v1",
    ]
    .iter()
    .all(|handle| material_asset_handles.contains(*handle));
    let sprite_binding_gate = sprite_bindings.len() >= 32
        && sprite_bindings.len() == applications.len()
        && sprite_bindings.iter().all(|binding| {
            binding
                .get("image_asset_handle_id")
                .and_then(Value::as_str)
                == Some("bevy_image_handle::trnm_world_authored_sprite_sheet_v1")
                && binding
                    .get("texture_atlas_layout_handle_id")
                    .and_then(Value::as_str)
                    == Some(
                        "bevy_texture_atlas_layout_handle::trnm_world_authored_sprite_sheet_layout_v1",
                    )
                && binding
                    .get("texture_atlas_index")
                    .and_then(Value::as_u64)
                    .unwrap_or(u64::MAX)
                    < frames.len() as u64
                && binding
                    .get("gpu_upload_claimed")
                    .and_then(Value::as_bool)
                    == Some(false)
        });
    let scene_layer_asset_gate = ["map", "hud", "actor", "feedback"]
        .iter()
        .all(|layer| scene_layers.contains(*layer))
        && [
            "world_tile_material",
            "hud_icon_material",
            "actor_sprite_material",
            "feedback_glyph_material",
        ]
        .iter()
        .all(|slot| material_slots.contains(*slot));
    let boundary_gate = material_application_evidence
        .get("gpu_upload_claimed")
        .and_then(Value::as_bool)
        == Some(false)
        && material_application_evidence
            .get("android_s5_real_device_claimed")
            .and_then(Value::as_bool)
            == Some(false);
    let runtime_asset_manifest = json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_RUNTIME_TEXTURE_ASSET_CONTRACT,
        "actor_id": actor_id,
        "authored_material_application_contract": TRILLIONNIUM_WORLD_BEVY_AUTHORED_MATERIAL_APPLICATION_CONTRACT,
        "atlas_path": atlas_path,
        "manifest_path": manifest_path,
        "binding_path": binding_path,
        "consumption_path": consumption_path,
        "application_path": application_path,
        "image_asset_descriptor": image_asset_descriptor,
        "texture_atlas_layout_descriptor": texture_atlas_layout_descriptor,
        "material_asset_manifest": material_asset_manifest.clone(),
        "sprite_bindings": sprite_bindings.clone(),
        "asset_boundary": "host_side_bevy_image_texture_atlas_handle_registration_not_gpu_upload_or_device_claim",
        "gpu_upload_claimed": false,
        "android_s5_real_device_claimed": false,
        "live_osm_ingestion_claimed": false,
    });
    if let Some(parent) = Path::new(runtime_asset_path).parent() {
        fs::create_dir_all(parent).expect("runtime texture asset parent is writable");
    }
    fs::write(
        runtime_asset_path,
        serde_json::to_string_pretty(&runtime_asset_manifest)
            .expect("runtime texture asset manifest serializes"),
    )
    .expect("runtime texture asset manifest writes to disk");
    let runtime_asset_bytes = fs::metadata(runtime_asset_path)
        .map(|metadata| metadata.len())
        .unwrap_or_default();
    let runtime_asset_parse_gate = fs::read_to_string(runtime_asset_path)
        .ok()
        .and_then(|text| serde_json::from_str::<Value>(&text).ok())
        .and_then(|value| {
            value
                .get("contract_version")
                .and_then(Value::as_str)
                .map(|contract| contract == TRILLIONNIUM_WORLD_BEVY_RUNTIME_TEXTURE_ASSET_CONTRACT)
        })
        == Some(true);
    let runtime_asset_manifest_write_gate = runtime_asset_bytes > 8_192 && runtime_asset_parse_gate;
    let green = material_application_gate
        && atlas_file_gate
        && manifest_frame_gate
        && runtime_image_descriptor_gate
        && texture_atlas_layout_gate
        && material_handle_gate
        && sprite_binding_gate
        && scene_layer_asset_gate
        && boundary_gate
        && runtime_asset_manifest_write_gate;
    let evidence = json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_RUNTIME_TEXTURE_ASSET_CONTRACT,
        "actor_id": actor_id,
        "green": green,
        "authored_material_application_contract": TRILLIONNIUM_WORLD_BEVY_AUTHORED_MATERIAL_APPLICATION_CONTRACT,
        "atlas_path": atlas_path,
        "manifest_path": manifest_path,
        "binding_path": binding_path,
        "consumption_path": consumption_path,
        "application_path": application_path,
        "runtime_asset_path": runtime_asset_path,
        "image_asset_handle_id": "bevy_image_handle::trnm_world_authored_sprite_sheet_v1",
        "texture_atlas_layout_handle_id": "bevy_texture_atlas_layout_handle::trnm_world_authored_sprite_sheet_layout_v1",
        "atlas_bytes": atlas_bytes,
        "runtime_asset_bytes": runtime_asset_bytes,
        "atlas_dimensions": { "width": atlas_width, "height": atlas_height },
        "frame_count": frames.len(),
        "sprite_binding_count": sprite_bindings.len(),
        "material_asset_count": material_asset_manifest.len(),
        "scene_layers": scene_layers.iter().cloned().collect::<Vec<_>>(),
        "material_slots": material_slots.iter().cloned().collect::<Vec<_>>(),
        "material_asset_handles": material_asset_handles.iter().cloned().collect::<Vec<_>>(),
        "binding_modes": binding_modes.iter().cloned().collect::<Vec<_>>(),
        "image_asset_descriptor": sample_pointer_value(&runtime_asset_manifest, "/image_asset_descriptor"),
        "texture_atlas_layout_descriptor": sample_pointer_value(&runtime_asset_manifest, "/texture_atlas_layout_descriptor"),
        "material_application_gate": material_application_gate,
        "atlas_file_gate": atlas_file_gate,
        "manifest_frame_gate": manifest_frame_gate,
        "runtime_image_descriptor_gate": runtime_image_descriptor_gate,
        "texture_atlas_layout_gate": texture_atlas_layout_gate,
        "material_handle_gate": material_handle_gate,
        "sprite_binding_gate": sprite_binding_gate,
        "scene_layer_asset_gate": scene_layer_asset_gate,
        "boundary_gate": boundary_gate,
        "runtime_asset_manifest_write_gate": runtime_asset_manifest_write_gate,
        "runtime_asset_parse_gate": runtime_asset_parse_gate,
        "asset_boundary": "host_side_bevy_image_texture_atlas_handle_registration_not_gpu_upload_or_device_claim",
        "source_of_truth": "The native Bevy host-side runtime maps the generated local PPM atlas and authored material-application records into Image handle, TextureAtlasLayout handle, material handles, and per-sprite texture-atlas indexes. This proves asset registration plumbing, not GPU upload or Android S5 device rendering.",
        "host_side_asset_registration_claimed": true,
        "gpu_upload_claimed": false,
        "android_s5_real_device_claimed": false,
        "live_osm_ingestion_claimed": false,
    });
    serde_json::to_string_pretty(&evidence).expect("runtime texture asset evidence serializes")
}

fn sha256_hex(bytes: &[u8]) -> String {
    let digest = Sha256::digest(bytes);
    digest
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect::<String>()
}

fn runtime_texture_manifest_probe_from_env() -> NativeRuntimeTextureManifestProbe {
    let manifest_path =
        env::var("TRNM_WORLD_BEVY_RUNTIME_TEXTURE_ASSET_MANIFEST").unwrap_or_default();
    let expected_sha256 =
        env::var("TRNM_WORLD_BEVY_RUNTIME_TEXTURE_ASSET_SHA256").unwrap_or_default();
    let manifest_bytes_data = (!manifest_path.is_empty())
        .then(|| fs::read(&manifest_path).ok())
        .flatten()
        .unwrap_or_default();
    let manifest_bytes = manifest_bytes_data.len() as u64;
    let computed_sha256 = if manifest_bytes_data.is_empty() {
        String::new()
    } else {
        sha256_hex(&manifest_bytes_data)
    };
    let manifest: Value =
        serde_json::from_slice(&manifest_bytes_data).unwrap_or_else(|_| json!({}));
    let image_asset_handle_id = manifest
        .pointer("/image_asset_descriptor/image_asset_handle_id")
        .and_then(Value::as_str)
        .unwrap_or_default()
        .to_string();
    let texture_atlas_layout_handle_id = manifest
        .pointer("/texture_atlas_layout_descriptor/texture_atlas_layout_handle_id")
        .and_then(Value::as_str)
        .unwrap_or_default()
        .to_string();
    let frame_count = manifest
        .pointer("/texture_atlas_layout_descriptor/frame_count")
        .and_then(Value::as_u64)
        .unwrap_or_default() as usize;
    let sprite_binding_count = manifest
        .get("sprite_bindings")
        .and_then(Value::as_array)
        .map(Vec::len)
        .unwrap_or_default();
    let material_asset_count = manifest
        .get("material_asset_manifest")
        .and_then(Value::as_array)
        .map(Vec::len)
        .unwrap_or_default();
    let manifest_present = Path::new(&manifest_path).exists() && manifest_bytes > 8_192;
    let manifest_parse_gate = manifest.get("contract_version").and_then(Value::as_str)
        == Some(TRILLIONNIUM_WORLD_BEVY_RUNTIME_TEXTURE_ASSET_CONTRACT)
        && frame_count >= 32
        && sprite_binding_count >= 32
        && material_asset_count == 4;
    let manifest_hash_gate = expected_sha256.len() == 64 && expected_sha256 == computed_sha256;
    let handle_gate = image_asset_handle_id
        == "bevy_image_handle::trnm_world_authored_sprite_sheet_v1"
        && texture_atlas_layout_handle_id
            == "bevy_texture_atlas_layout_handle::trnm_world_authored_sprite_sheet_layout_v1";
    let green = manifest_present && manifest_parse_gate && manifest_hash_gate && handle_gate;
    NativeRuntimeTextureManifestProbe {
        contract_version: TRILLIONNIUM_WORLD_BEVY_RUNTIME_TEXTURE_MANIFEST_PROBE_CONTRACT
            .to_string(),
        manifest_path,
        expected_sha256,
        computed_sha256,
        manifest_bytes,
        image_asset_handle_id,
        texture_atlas_layout_handle_id,
        frame_count,
        sprite_binding_count,
        material_asset_count,
        manifest_present,
        manifest_parse_gate,
        manifest_hash_gate,
        handle_gate,
        host_side_asset_registration_claimed: true,
        gpu_upload_claimed: false,
        android_s5_real_device_claimed: false,
        live_osm_ingestion_claimed: false,
        green,
    }
}

fn read_ppm_p3_rgba(
    atlas_path: &str,
    expected_width: u32,
    expected_height: u32,
) -> Result<(Vec<u8>, usize), String> {
    let text = fs::read_to_string(atlas_path).map_err(|err| err.to_string())?;
    let mut tokens = text.split_whitespace();
    if tokens.next() != Some("P3") {
        return Err("ppm magic must be P3".to_string());
    }
    let width = tokens
        .next()
        .ok_or_else(|| "ppm width missing".to_string())?
        .parse::<u32>()
        .map_err(|err| err.to_string())?;
    let height = tokens
        .next()
        .ok_or_else(|| "ppm height missing".to_string())?
        .parse::<u32>()
        .map_err(|err| err.to_string())?;
    let max_value = tokens
        .next()
        .ok_or_else(|| "ppm max value missing".to_string())?
        .parse::<u32>()
        .map_err(|err| err.to_string())?;
    if width != expected_width || height != expected_height || max_value != 255 {
        return Err(format!(
            "ppm header mismatch {width}x{height} max={max_value}, expected {expected_width}x{expected_height} max=255"
        ));
    }
    let pixel_count = width as usize * height as usize;
    let mut rgba = Vec::with_capacity(pixel_count * 4);
    let mut unique_colors = HashSet::new();
    for _ in 0..pixel_count {
        let r = tokens
            .next()
            .ok_or_else(|| "ppm red channel missing".to_string())?
            .parse::<u8>()
            .map_err(|err| err.to_string())?;
        let g = tokens
            .next()
            .ok_or_else(|| "ppm green channel missing".to_string())?
            .parse::<u8>()
            .map_err(|err| err.to_string())?;
        let b = tokens
            .next()
            .ok_or_else(|| "ppm blue channel missing".to_string())?
            .parse::<u8>()
            .map_err(|err| err.to_string())?;
        unique_colors.insert([r, g, b]);
        rgba.extend_from_slice(&[r, g, b, 255]);
    }
    Ok((rgba, unique_colors.len()))
}

fn runtime_texture_sprite_binding_record_from_value(
    binding: &Value,
) -> NativeRuntimeTextureSpriteBindingRecord {
    NativeRuntimeTextureSpriteBindingRecord {
        sprite_binding_id: authored_surface_string(binding, "sprite_binding_id"),
        visible_runtime_surface_id: authored_surface_string(binding, "visible_runtime_surface_id"),
        scene_layer: authored_surface_string(binding, "scene_layer"),
        material_slot: authored_surface_string(binding, "material_slot"),
        material_asset_handle_id: authored_surface_string(binding, "material_asset_handle_id"),
        texture_atlas_index: binding
            .get("texture_atlas_index")
            .and_then(Value::as_u64)
            .unwrap_or_default() as usize,
        image_asset_handle_id: authored_surface_string(binding, "image_asset_handle_id"),
        texture_atlas_layout_handle_id: authored_surface_string(
            binding,
            "texture_atlas_layout_handle_id",
        ),
        binding_mode: authored_surface_string(binding, "binding_mode"),
    }
}

fn register_runtime_texture_asset_store_from_probe(
    world: &mut World,
    probe: &NativeRuntimeTextureManifestProbe,
) -> NativeRuntimeTextureAssetStoreRegistration {
    if !world.contains_resource::<Assets<Image>>() {
        world.insert_resource(Assets::<Image>::default());
    }
    if !world.contains_resource::<Assets<TextureAtlasLayout>>() {
        world.insert_resource(Assets::<TextureAtlasLayout>::default());
    }
    let image_asset_count_before = world.resource::<Assets<Image>>().len();
    let texture_atlas_layout_count_before = world.resource::<Assets<TextureAtlasLayout>>().len();
    let manifest_bytes_data = fs::read(&probe.manifest_path).unwrap_or_default();
    let manifest_sha256 = if manifest_bytes_data.is_empty() {
        String::new()
    } else {
        sha256_hex(&manifest_bytes_data)
    };
    let manifest: Value =
        serde_json::from_slice(&manifest_bytes_data).unwrap_or_else(|_| json!({}));
    let atlas_path = manifest
        .get("atlas_path")
        .and_then(Value::as_str)
        .unwrap_or_default()
        .to_string();
    let image_extent_width = manifest
        .pointer("/image_asset_descriptor/extent3d/width")
        .and_then(Value::as_u64)
        .unwrap_or_default() as u32;
    let image_extent_height = manifest
        .pointer("/image_asset_descriptor/extent3d/height")
        .and_then(Value::as_u64)
        .unwrap_or_default() as u32;
    let cell_size = manifest
        .pointer("/texture_atlas_layout_descriptor/grid_cell_size_px/width")
        .and_then(Value::as_u64)
        .unwrap_or(32) as u32;
    let columns = manifest
        .pointer("/texture_atlas_layout_descriptor/columns")
        .and_then(Value::as_u64)
        .unwrap_or(8) as u32;
    let rows = manifest
        .pointer("/texture_atlas_layout_descriptor/rows")
        .and_then(Value::as_u64)
        .unwrap_or(4) as u32;
    let frame_count = manifest
        .pointer("/texture_atlas_layout_descriptor/frame_count")
        .and_then(Value::as_u64)
        .unwrap_or_default() as usize;
    let sprite_binding_count = manifest
        .get("sprite_bindings")
        .and_then(Value::as_array)
        .map(Vec::len)
        .unwrap_or_default();
    let material_asset_count = manifest
        .get("material_asset_manifest")
        .and_then(Value::as_array)
        .map(Vec::len)
        .unwrap_or_default();
    let sprite_binding_records = manifest
        .get("sprite_bindings")
        .and_then(Value::as_array)
        .map(|bindings| {
            bindings
                .iter()
                .map(runtime_texture_sprite_binding_record_from_value)
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    let image_asset_handle_id = manifest
        .pointer("/image_asset_descriptor/image_asset_handle_id")
        .and_then(Value::as_str)
        .unwrap_or_default()
        .to_string();
    let texture_atlas_layout_handle_id = manifest
        .pointer("/texture_atlas_layout_descriptor/texture_atlas_layout_handle_id")
        .and_then(Value::as_str)
        .unwrap_or_default()
        .to_string();

    let parsed_ppm = read_ppm_p3_rgba(&atlas_path, image_extent_width, image_extent_height);
    let (rgba, image_unique_color_count, ppm_parse_gate) = match parsed_ppm {
        Ok((rgba, unique_count)) => (rgba, unique_count, true),
        Err(_) => (Vec::new(), 0, false),
    };
    let mut bevy_image_asset_id_debug = String::new();
    let mut image_data_bytes = 0_usize;
    let mut image_handle_for_binding: Option<Handle<Image>> = None;
    if ppm_parse_gate {
        let image = Image::new(
            Extent3d {
                width: image_extent_width,
                height: image_extent_height,
                depth_or_array_layers: 1,
            },
            TextureDimension::D2,
            rgba,
            TextureFormat::Rgba8UnormSrgb,
            RenderAssetUsages::default(),
        );
        let image_handle = world.resource_mut::<Assets<Image>>().add(image);
        bevy_image_asset_id_debug = format!("{:?}", image_handle.id());
        image_data_bytes = world
            .resource::<Assets<Image>>()
            .get(&image_handle)
            .and_then(|image| image.data.as_ref().map(Vec::len))
            .unwrap_or_default();
        image_handle_for_binding = Some(image_handle);
    }

    let layout = TextureAtlasLayout::from_grid(UVec2::splat(cell_size), columns, rows, None, None);
    let texture_atlas_rect_count = layout.textures.len();
    let layout_handle = world
        .resource_mut::<Assets<TextureAtlasLayout>>()
        .add(layout);
    let bevy_texture_atlas_layout_asset_id_debug = format!("{:?}", layout_handle.id());

    let image_asset_count_after = world.resource::<Assets<Image>>().len();
    let texture_atlas_layout_count_after = world.resource::<Assets<TextureAtlasLayout>>().len();
    let bevy_image_store_registration_gate = ppm_parse_gate
        && image_asset_count_after == image_asset_count_before + 1
        && image_data_bytes == image_extent_width as usize * image_extent_height as usize * 4
        && image_unique_color_count >= 8;
    let texture_atlas_layout_store_registration_gate = texture_atlas_layout_count_after
        == texture_atlas_layout_count_before + 1
        && texture_atlas_rect_count >= frame_count
        && texture_atlas_rect_count >= 32;
    let asset_store_registered_gate =
        bevy_image_store_registration_gate && texture_atlas_layout_store_registration_gate;
    let render_world_asset_usage_requested = true;
    let green = probe.green
        && manifest_sha256 == probe.computed_sha256
        && asset_store_registered_gate
        && sprite_binding_count >= 32
        && material_asset_count == 4;
    if let Some(image_handle) = image_handle_for_binding {
        if asset_store_registered_gate {
            world.insert_resource(NativeRuntimeTextureAssetStoreHandles {
                image_handle,
                texture_atlas_layout_handle: layout_handle,
                image_asset_handle_id: image_asset_handle_id.clone(),
                texture_atlas_layout_handle_id: texture_atlas_layout_handle_id.clone(),
                bevy_image_asset_id_debug: bevy_image_asset_id_debug.clone(),
                bevy_texture_atlas_layout_asset_id_debug: bevy_texture_atlas_layout_asset_id_debug
                    .clone(),
            });
            world.insert_resource(NativeRuntimeTextureSpriteBindingLookup {
                manifest_path: probe.manifest_path.clone(),
                manifest_sha256: manifest_sha256.clone(),
                image_asset_handle_id: image_asset_handle_id.clone(),
                texture_atlas_layout_handle_id: texture_atlas_layout_handle_id.clone(),
                binding_count: sprite_binding_records.len(),
                records: sprite_binding_records,
                green: sprite_binding_count >= 32
                    && image_asset_handle_id
                        == "bevy_image_handle::trnm_world_authored_sprite_sheet_v1"
                    && texture_atlas_layout_handle_id
                        == "bevy_texture_atlas_layout_handle::trnm_world_authored_sprite_sheet_layout_v1",
            });
        }
    }
    NativeRuntimeTextureAssetStoreRegistration {
        contract_version: TRILLIONNIUM_WORLD_BEVY_ASSET_STORE_REGISTRATION_CONTRACT.to_string(),
        manifest_path: probe.manifest_path.clone(),
        atlas_path,
        manifest_sha256,
        image_asset_handle_id,
        texture_atlas_layout_handle_id,
        bevy_image_asset_id_debug,
        bevy_texture_atlas_layout_asset_id_debug,
        image_asset_count_before,
        image_asset_count_after,
        texture_atlas_layout_count_before,
        texture_atlas_layout_count_after,
        image_extent_width,
        image_extent_height,
        image_data_bytes,
        image_unique_color_count,
        texture_atlas_rect_count,
        frame_count,
        sprite_binding_count,
        material_asset_count,
        ppm_parse_gate,
        bevy_image_store_registration_gate,
        texture_atlas_layout_store_registration_gate,
        asset_store_registered_gate,
        render_asset_usage: "RenderAssetUsages::MAIN_WORLD | RenderAssetUsages::RENDER_WORLD"
            .to_string(),
        render_world_asset_usage_requested,
        host_side_asset_registration_claimed: true,
        gpu_upload_claimed: false,
        android_s5_real_device_claimed: false,
        live_osm_ingestion_claimed: false,
        green,
    }
}

fn runtime_texture_binding_record_for_surface<'a>(
    lookup: &'a NativeRuntimeTextureSpriteBindingLookup,
    authored_surface: &BevyWorldAuthoredArtAssetSurface,
) -> Option<&'a NativeRuntimeTextureSpriteBindingRecord> {
    lookup
        .records
        .iter()
        .find(|record| record.visible_runtime_surface_id == authored_surface.surface_id)
}

pub fn bind_runtime_textures_to_authored_sprite_surfaces(
    mut commands: Commands,
    handles: Option<Res<NativeRuntimeTextureAssetStoreHandles>>,
    lookup: Option<Res<NativeRuntimeTextureSpriteBindingLookup>>,
    mut query: Query<(
        Entity,
        &mut Sprite,
        &BevyWorldAuthoredArtAssetSurface,
        Option<&BevyWorldSpriteAssetSurface>,
    )>,
) {
    let (Some(handles), Some(lookup)) = (handles, lookup) else {
        return;
    };
    if !lookup.green {
        return;
    }
    for (entity, mut sprite, authored_surface, sprite_surface) in &mut query {
        let Some(record) = runtime_texture_binding_record_for_surface(&lookup, authored_surface)
        else {
            continue;
        };
        sprite.image = handles.image_handle.clone();
        sprite.texture_atlas = Some(TextureAtlas {
            layout: handles.texture_atlas_layout_handle.clone(),
            index: record.texture_atlas_index,
        });
        let sprite_image_asset_id_debug = format!("{:?}", sprite.image.id());
        let sprite_texture_atlas_layout_asset_id_debug = sprite
            .texture_atlas
            .as_ref()
            .map(|atlas| format!("{:?}", atlas.layout.id()))
            .unwrap_or_default();
        let sprite_surface_id = sprite_surface
            .map(|surface| surface.surface_id.clone())
            .unwrap_or_else(|| authored_surface.surface_id.clone());
        let sprite_component_texture_handle_gate =
            sprite_image_asset_id_debug == handles.bevy_image_asset_id_debug;
        let sprite_component_texture_atlas_gate = sprite_texture_atlas_layout_asset_id_debug
            == handles.bevy_texture_atlas_layout_asset_id_debug;
        commands
            .entity(entity)
            .insert(BevyWorldRuntimeTextureSpriteAssetBinding {
                contract_version: TRILLIONNIUM_WORLD_BEVY_SPRITE_ASSET_BINDING_CONTRACT.to_string(),
                visible_runtime_surface_id: authored_surface.surface_id.clone(),
                sprite_surface_id,
                asset_id: authored_surface.asset_id.clone(),
                scene_layer: record.scene_layer.clone(),
                material_slot: record.material_slot.clone(),
                material_asset_handle_id: record.material_asset_handle_id.clone(),
                image_asset_handle_id: handles.image_asset_handle_id.clone(),
                texture_atlas_layout_handle_id: handles.texture_atlas_layout_handle_id.clone(),
                bevy_image_asset_id_debug: handles.bevy_image_asset_id_debug.clone(),
                bevy_texture_atlas_layout_asset_id_debug: handles
                    .bevy_texture_atlas_layout_asset_id_debug
                    .clone(),
                sprite_image_asset_id_debug,
                sprite_texture_atlas_layout_asset_id_debug,
                texture_atlas_index: record.texture_atlas_index,
                binding_mode: "Sprite.image + Sprite.texture_atlas bound_to_registered_bevy_assets"
                    .to_string(),
                sprite_component_texture_handle_gate,
                sprite_component_texture_atlas_gate,
                visible_sprite_surface_attached: true,
                gpu_upload_claimed: false,
                android_s5_real_device_claimed: false,
                live_osm_ingestion_claimed: false,
            });
    }
}

pub fn native_runtime_texture_manifest_probe_evidence_json(
    actor_id: &str,
    runtime_summary_path: &str,
    runtime_manifest_path: &str,
) -> String {
    let runtime_summary_text = fs::read_to_string(runtime_summary_path).unwrap_or_default();
    let runtime_summary: Value =
        serde_json::from_str(&runtime_summary_text).unwrap_or_else(|_| json!({}));
    let manifest_bytes_data = fs::read(runtime_manifest_path).unwrap_or_default();
    let manifest_sha256 = sha256_hex(&manifest_bytes_data);
    let previous_manifest = env::var("TRNM_WORLD_BEVY_RUNTIME_TEXTURE_ASSET_MANIFEST").ok();
    let previous_sha256 = env::var("TRNM_WORLD_BEVY_RUNTIME_TEXTURE_ASSET_SHA256").ok();
    env::set_var(
        "TRNM_WORLD_BEVY_RUNTIME_TEXTURE_ASSET_MANIFEST",
        runtime_manifest_path,
    );
    env::set_var(
        "TRNM_WORLD_BEVY_RUNTIME_TEXTURE_ASSET_SHA256",
        &manifest_sha256,
    );
    let (app, _report) = build_native_bevy_app(native_bevy_playable_fixture(), actor_id);
    let probe = app
        .world()
        .resource::<NativeRuntimeTextureManifestProbe>()
        .clone();
    let asset_store_registration = app
        .world()
        .resource::<NativeRuntimeTextureAssetStoreRegistration>()
        .clone();
    let world = app.world().resource::<AuthoritativeWorldResource>();
    let tactics_character = app.world().resource::<NativeTacticsCharacter>();
    let gameplay_log = app.world().resource::<NativeGameplayLog>();
    let first_playable = app.world().resource::<NativeFirstPlayableRuntime>();
    let runtime_probe = native_runtime_probe_value_with_texture_manifest(
        actor_id,
        &world.state,
        &tactics_character.character,
        gameplay_log,
        first_playable,
        Some(&probe),
        Some(&asset_store_registration),
    );
    match previous_manifest {
        Some(value) => env::set_var("TRNM_WORLD_BEVY_RUNTIME_TEXTURE_ASSET_MANIFEST", value),
        None => env::remove_var("TRNM_WORLD_BEVY_RUNTIME_TEXTURE_ASSET_MANIFEST"),
    }
    match previous_sha256 {
        Some(value) => env::set_var("TRNM_WORLD_BEVY_RUNTIME_TEXTURE_ASSET_SHA256", value),
        None => env::remove_var("TRNM_WORLD_BEVY_RUNTIME_TEXTURE_ASSET_SHA256"),
    }
    let runtime_summary_gate = runtime_summary.get("green").and_then(Value::as_bool) == Some(true)
        && runtime_summary
            .get("runtime_asset_path")
            .and_then(Value::as_str)
            == Some(runtime_manifest_path);
    let app_resource_registered_gate = probe.green
        && probe.manifest_path == runtime_manifest_path
        && probe.expected_sha256 == manifest_sha256
        && probe.computed_sha256 == manifest_sha256;
    let runtime_probe_gate = runtime_probe
        .get("runtime_texture_manifest_probe_gate")
        .and_then(Value::as_bool)
        == Some(true)
        && runtime_probe
            .pointer("/runtime_texture_manifest_probe/computed_sha256")
            .and_then(Value::as_str)
            == Some(manifest_sha256.as_str());
    let host_log_line = format!(
        "TRNM_WORLD_BEVY_RUNTIME_TEXTURE_MANIFEST_PROBE green={} sha256={} image_handle={} layout_handle={}",
        probe.green,
        probe.computed_sha256,
        probe.image_asset_handle_id,
        probe.texture_atlas_layout_handle_id
    );
    let green = runtime_summary_gate
        && app_resource_registered_gate
        && runtime_probe_gate
        && probe.manifest_hash_gate
        && probe.handle_gate
        && !probe.gpu_upload_claimed
        && !probe.android_s5_real_device_claimed
        && !probe.live_osm_ingestion_claimed;
    let evidence = json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_RUNTIME_TEXTURE_MANIFEST_PROBE_CONTRACT,
        "actor_id": actor_id,
        "green": green,
        "runtime_texture_asset_contract": TRILLIONNIUM_WORLD_BEVY_RUNTIME_TEXTURE_ASSET_CONTRACT,
        "runtime_summary_path": runtime_summary_path,
        "runtime_manifest_path": runtime_manifest_path,
        "runtime_manifest_sha256": manifest_sha256,
        "app_resource_probe": probe,
        "runtime_probe_contract": TRILLIONNIUM_WORLD_BEVY_RUNTIME_PROBE_CONTRACT,
        "runtime_probe": runtime_probe,
        "runtime_summary_gate": runtime_summary_gate,
        "app_resource_registered_gate": app_resource_registered_gate,
        "runtime_probe_gate": runtime_probe_gate,
        "manifest_hash_gate": sample_pointer_value(&serde_json::to_value(&probe).expect("probe serializes"), "/manifest_hash_gate"),
        "handle_gate": sample_pointer_value(&serde_json::to_value(&probe).expect("probe serializes"), "/handle_gate"),
        "host_log_line": host_log_line,
        "asset_boundary": "bevy_app_resource_reads_runtime_texture_manifest_env_and_reports_hash_not_gpu_upload_claim",
        "source_of_truth": "The Bevy app inserts NativeRuntimeTextureManifestProbe during plugin build by reading TRNM_WORLD_BEVY_RUNTIME_TEXTURE_ASSET_MANIFEST and TRNM_WORLD_BEVY_RUNTIME_TEXTURE_ASSET_SHA256, validates the manifest hash and handle ids, and exposes the same probe through the runtime probe contract.",
        "gpu_upload_claimed": false,
        "android_s5_real_device_claimed": false,
        "live_osm_ingestion_claimed": false,
    });
    serde_json::to_string_pretty(&evidence)
        .expect("runtime texture manifest probe evidence serializes")
}

