    let save_sample = sample_live_app_state(&mut app, "after_save_title_route_accept");
    let load_event = press_live_button_action(&mut app, NativeControlAction::LoadSelectedSlot);
    let load_sample = sample_live_app_state(&mut app, "after_load_title_route_accept");
    let continue_event = press_live_button_action(&mut app, NativeControlAction::ContinueAfterLoad);
    let continue_sample = sample_live_app_state(&mut app, "after_continue_title_route_accept");
    let final_runtime = app.world().resource::<NativeFirstPlayableRuntime>().clone();

