#[derive(Clone)]
struct NativeKeyboardReplayStep {
    stage: String,
    input: NativeKeyboardScriptInput,
    recorded_signature: serde_json::Value,
}

fn build_branch_title_route_keyboard_replay_app(
    actor_id: &str,
    spec: BuildTitleRouteBranchCompletionSpec<'_>,
) -> App {
    let mut app = build_keyboard_runtime_app(native_bevy_playable_fixture(), actor_id);
    {
        let mut runtime = app.world_mut().resource_mut::<NativeFirstPlayableRuntime>();
        seed_build_branch_title_collection_runtime(&mut runtime);
        runtime.build_title_unlocked_ids = vec![spec.title_id.to_string()];
        runtime.active_build_title_id = None;
        runtime.active_build_title_effect = None;
        for task_id in [spec.followup_task_id, spec.mastery_task_id] {
            runtime
                .completed_task_ids
                .retain(|completed| completed != task_id);
            runtime.active_task_ids.retain(|active| active != task_id);
        }
        runtime.reward_settlement_text = format!("TITLE ROUTE KEYBOARD REPLAY | {}", spec.stat_id);
        refresh_contextual_action_runtime(&mut runtime);
    }
    app.update();
    app
}

fn title_route_keyboard_replay_key(label: &str) -> Option<(KeyCode, &'static str)> {
    match label {
        "Enter" => Some((KeyCode::Enter, "Enter")),
        "NumpadEnter" => Some((KeyCode::NumpadEnter, "NumpadEnter")),
        "KeyJ" => Some((KeyCode::KeyJ, "KeyJ")),
        _ => None,
    }
}

fn title_route_keyboard_event_replay_signature(event: &serde_json::Value) -> serde_json::Value {
    json!({
        "key": sample_pointer_value(event, "/key"),
        "action": sample_pointer_value(event, "/action"),
        "input_path": sample_pointer_value(event, "/input_path"),
        "accepted": sample_pointer_value(event, "/accepted"),
        "availability_before": sample_pointer_value(event, "/availability_before"),
        "current_room_before": sample_pointer_value(event, "/current_room_before"),
        "current_room_after": sample_pointer_value(event, "/current_room_after"),
        "core_state_before": sample_pointer_value(event, "/core_state_before"),
        "core_state_after": sample_pointer_value(event, "/core_state_after"),
    })
}

fn title_route_keyboard_replay_record(
    step: &serde_json::Value,
    fallback_stage: String,
) -> Option<NativeKeyboardReplayStep> {
    let event = step.get("event")?;
    let key_label = event.get("key").and_then(|value| value.as_str())?;
    let (key, key_label) = title_route_keyboard_replay_key(key_label)?;
    let action_label = event.get("action").and_then(|value| value.as_str())?;
    let action = native_control_action_from_label(action_label)?;
    let stage = step
        .get("stage")
        .and_then(|value| value.as_str())
        .map(str::to_string)
        .unwrap_or(fallback_stage);
    Some(NativeKeyboardReplayStep {
        stage,
        input: NativeKeyboardScriptInput {
            key,
            key_label,
            action,
        },
        recorded_signature: title_route_keyboard_event_replay_signature(event),
    })
}

fn title_route_keyboard_replay_sequence(
    branch: &serde_json::Value,
) -> Option<Vec<NativeKeyboardReplayStep>> {
    let mut steps = Vec::new();
    steps.push(title_route_keyboard_replay_record(
        branch.pointer("/keyboard_steps/equip_title")?,
        "equip_title".to_string(),
    )?);
    for (index, step) in branch
        .pointer("/keyboard_steps/followup_route")?
        .as_array()?
        .iter()
        .enumerate()
    {
        steps.push(title_route_keyboard_replay_record(
            step,
            format!("followup_route_{}", index + 1),
        )?);
    }
    steps.push(title_route_keyboard_replay_record(
        branch.pointer("/keyboard_steps/complete_followup")?,
        "complete_followup".to_string(),
    )?);
    for (index, step) in branch
        .pointer("/keyboard_steps/mastery_route")?
        .as_array()?
        .iter()
        .enumerate()
    {
        steps.push(title_route_keyboard_replay_record(
            step,
            format!("mastery_route_{}", index + 1),
        )?);
    }
    for (index, step) in branch
        .pointer("/keyboard_steps/combat_prereq")?
        .as_array()?
        .iter()
        .enumerate()
    {
        steps.push(title_route_keyboard_replay_record(
            step,
            format!("combat_prereq_{}", index + 1),
        )?);
    }
    steps.push(title_route_keyboard_replay_record(
        branch.pointer("/keyboard_steps/complete_mastery")?,
        "complete_mastery".to_string(),
    )?);
    Some(steps)
}

fn title_route_branch_final_runtime_summary(
    runtime: &NativeFirstPlayableRuntime,
) -> serde_json::Value {
    json!({
        "current_room_id": runtime.current_room_id.clone(),
        "active_build_title_id": runtime.active_build_title_id.clone(),
        "active_build_title_effect": runtime.active_build_title_effect.clone(),
        "route_director_task_id": runtime.route_director_task_id.clone(),
        "completed_task_ids": runtime.completed_task_ids.clone(),
        "active_task_ids": runtime.active_task_ids.clone(),
        "inventory_items": runtime.inventory_items.clone(),
        "objective_status": runtime.objective_status.clone(),
        "loot_history": runtime.loot_history.clone(),
        "combat_result_state": runtime.combat_result_state.clone(),
    })
}

fn native_build_branch_title_route_branch_keyboard_replay_result(
    actor_id: &str,
    spec: BuildTitleRouteBranchCompletionSpec<'_>,
    recorded_branch: Option<&serde_json::Value>,
) -> serde_json::Value {
    let Some(recorded_branch) = recorded_branch else {
        return json!({
            "stat_id": spec.stat_id,
            "green": false,
            "recorded_sequence_parse_gate": false,
            "failure": "missing_recorded_branch",
        });
    };
    let recorded_branch_green = recorded_branch
        .get("green")
        .and_then(|value| value.as_bool())
        == Some(true);
    let Some(records) = title_route_keyboard_replay_sequence(recorded_branch) else {
        return json!({
            "stat_id": spec.stat_id,
            "green": false,
            "recorded_branch_green": recorded_branch_green,
            "recorded_sequence_parse_gate": false,
            "failure": "recorded_keyboard_sequence_parse_failed",
        });
    };
    let recorded_sequence_count = records.len();
    let recorded_sequence_path_gate = records.iter().all(|record| {
        record
            .recorded_signature
            .get("input_path")
            .and_then(|value| value.as_str())
            == Some(
                "ButtonInput<KeyCode> -> handle_native_keyboard_input -> apply_live_native_action",
            )
    });
    let recorded_sequence = records
        .iter()
        .map(|record| {
            json!({
                "stage": record.stage,
                "key": record.input.key_label,
                "action": native_control_action_label(&record.input.action),
                "recorded_signature": record.recorded_signature,
            })
        })
        .collect::<Vec<_>>();

    let mut app = build_branch_title_route_keyboard_replay_app(actor_id, spec);
    let mut replay_events = Vec::new();
    for record in records {
        let action_label = native_control_action_label(&record.input.action);
        let replay_event = press_keyboard_script_step(&mut app, record.input.clone());
        let replay_signature = title_route_keyboard_event_replay_signature(&replay_event);
        let signature_match = replay_signature == record.recorded_signature;
        replay_events.push(json!({
            "stage": record.stage,
            "key": record.input.key_label,
            "action": action_label,
            "recorded_signature": record.recorded_signature,
            "replay_signature": replay_signature,
            "signature_match": signature_match,
        }));
    }
    let final_runtime = title_route_branch_final_runtime_summary(
        app.world().resource::<NativeFirstPlayableRuntime>(),
    );
    let expected_final_runtime = recorded_branch
        .get("final_runtime")
        .cloned()
        .unwrap_or_else(|| json!({}));
    let replay_sequence_signature_match = replay_events.iter().all(|event| {
        event
            .get("signature_match")
            .and_then(|value| value.as_bool())
            == Some(true)
    });
    let replay_event_count = replay_events.len();
    let final_runtime_match = final_runtime == expected_final_runtime;
    let green = recorded_branch_green
        && recorded_sequence_count > 0
        && recorded_sequence_path_gate
        && replay_event_count == recorded_sequence_count
        && replay_sequence_signature_match
        && final_runtime_match;

    json!({
        "stat_id": spec.stat_id,
        "title_id": spec.title_id,
        "followup_task_id": spec.followup_task_id,
        "mastery_task_id": spec.mastery_task_id,
        "reward_item_id": spec.reward_item_id,
        "green": green,
        "recorded_branch_green": recorded_branch_green,
        "recorded_sequence_parse_gate": true,
        "recorded_sequence_path_gate": recorded_sequence_path_gate,
        "recorded_sequence_count": recorded_sequence_count,
        "replay_event_count": replay_event_count,
        "replay_sequence_signature_match": replay_sequence_signature_match,
        "final_runtime_match": final_runtime_match,
        "recorded_sequence": recorded_sequence,
        "replay_events": replay_events,
        "expected_final_runtime": expected_final_runtime,
        "replay_final_runtime": final_runtime,
    })
}

