fn first_minute_next_button_from_sample(sample: &serde_json::Value) -> Option<String> {
    sample
        .get("quest_panel_text")
        .and_then(|value| value.as_str())
        .and_then(|text| text.split("NEXT BUTTON: ").nth(1))
        .map(|tail| {
            tail.lines()
                .next()
                .unwrap_or(tail)
                .split(" | ")
                .next()
                .unwrap_or(tail)
                .trim()
                .to_string()
        })
}

