fn summary_text_contains(summary: &serde_json::Value, pointer: &str, needle: &str) -> bool {
    summary
        .pointer(pointer)
        .and_then(|value| value.as_str())
        .is_some_and(|text| text.contains(needle))
}

fn first_minute_frame_visible_state_gate(frame_id: &str, summary: &serde_json::Value) -> bool {
    match frame_id {
        "title" => {
            summary_text_contains(summary, "/title_menu_text", "TITLE ACTIVE")
                && summary
                    .pointer("/runtime/session_title_menu_visible")
                    .and_then(|value| value.as_bool())
                    == Some(true)
        }
        "create" => {
            summary_text_contains(summary, "/character_create_text", "CREATE ACTIVE")
                && summary
                    .pointer("/runtime/session_character_create_visible")
                    .and_then(|value| value.as_bool())
                    == Some(true)
        }
        "talk" => {
            summary
                .pointer("/current_node_id")
                .and_then(|value| value.as_str())
                == Some("mirror-city-square")
                && summary
                    .pointer("/runtime/session_character_create_visible")
                    .and_then(|value| value.as_bool())
                    == Some(false)
        }
        "train" => {
            summary
                .pointer("/runtime/tutorial_step")
                .and_then(|value| value.as_str())
                == Some("train_with_mentor")
                && summary
                    .pointer("/current_node_id")
                    .and_then(|value| value.as_str())
                    == Some("mirror-city-square")
        }
        "training_room" => {
            summary
                .pointer("/runtime/active_scene_layer")
                .and_then(|value| value.as_str())
                == Some("mentor_training_room_indoor_tilemap")
        }
        "arena" => {
            summary
                .pointer("/current_node_id")
                .and_then(|value| value.as_str())
                == Some("league-coliseum")
                && summary
                    .pointer("/runtime/active_scene_layer")
                    .and_then(|value| value.as_str())
                    == Some("arena_outdoor_tilemap")
        }
        "fight_result" => {
            summary
                .pointer("/runtime/objective_status")
                .and_then(|value| value.as_str())
                == Some("combat_resolved")
        }
        "save_continue" => summary_text_contains(summary, "/session_slot_text", "A:saved"),
        "resume_continue" => {
            summary_text_contains(summary, "/session_resume_text", "RESUME ACTIVE")
                && summary
                    .pointer("/runtime/session_resume_input_locked")
                    .and_then(|value| value.as_bool())
                    == Some(true)
        }
        "complete" => {
            summary
                .pointer("/next_button")
                .and_then(|value| value.as_str())
                == Some("FIRST MINUTE COMPLETE")
                && summary
                    .pointer("/runtime/session_resume_input_locked")
                    .and_then(|value| value.as_bool())
                    == Some(false)
        }
        _ => false,
    }
}

fn first_minute_screenshot_manifest_frame(
    replay_steps: &[serde_json::Value],
    frame_index: usize,
    frame_id: &str,
    step_name: &str,
    sample_key: &str,
    expected_next_button: &str,
) -> serde_json::Value {
    let summary = replay_step_sample_summary(replay_steps, step_name, sample_key);
    let next_button = summary
        .get("next_button")
        .and_then(|value| value.as_str())
        .unwrap_or_default()
        .to_string();
    let highlighted_actions = highlighted_action_labels_from_summary(&summary);
    let highlight_gate = if expected_next_button == "FIRST MINUTE COMPLETE" {
        highlighted_actions.is_empty()
    } else {
        highlighted_actions == vec![expected_next_button.to_string()]
    };
    let visible_state_gate = first_minute_frame_visible_state_gate(frame_id, &summary);
    json!({
        "frame_index": frame_index,
        "frame_id": frame_id,
        "source_replay_step": step_name,
        "sample_key": sample_key,
        "expected_next_button": expected_next_button,
        "next_button": next_button,
        "highlighted_actions": highlighted_actions,
        "highlight_gate": highlight_gate,
        "visible_state_gate": visible_state_gate,
        "current_node_id": sample_pointer_value(&summary, "/current_node_id"),
        "map_scene": sample_pointer_value(&summary, "/runtime/map_scene"),
        "active_scene_layer": sample_pointer_value(&summary, "/runtime/active_scene_layer"),
        "objective_status": sample_pointer_value(&summary, "/runtime/objective_status"),
        "tutorial_step": sample_pointer_value(&summary, "/runtime/tutorial_step"),
        "title_menu_text": sample_pointer_value(&summary, "/title_menu_text"),
        "character_create_text": sample_pointer_value(&summary, "/character_create_text"),
        "quest_panel_text": sample_pointer_value(&summary, "/quest_panel_text"),
        "session_resume_text": sample_pointer_value(&summary, "/session_resume_text"),
        "session_slot_text": sample_pointer_value(&summary, "/session_slot_text"),
        "player_transform": sample_pointer_value(&summary, "/player_transform"),
        "input_telemetry_summary": sample_pointer_value(&summary, "/input_telemetry_summary"),
    })
}

fn sample_pointer_value(sample: &serde_json::Value, pointer: &str) -> serde_json::Value {
    sample
        .pointer(pointer)
        .cloned()
        .unwrap_or(serde_json::Value::Null)
}

