fn run_live_bevy_button_session(
    actor_id: &str,
) -> (
    Vec<serde_json::Value>,
    Vec<serde_json::Value>,
    Vec<serde_json::Value>,
    NativeFirstPlayableRuntime,
) {
    run_bevy_button_sequence(
        actor_id,
        vec![
            NativeControlAction::Talk,
            NativeControlAction::Train,
            NativeControlAction::Move {
                direction: "north".to_string(),
            },
            NativeControlAction::Fight,
            NativeControlAction::CompleteTask,
            NativeControlAction::Equip,
        ],
    )
}

fn run_bevy_button_sequence(
    actor_id: &str,
    actions: Vec<NativeControlAction>,
) -> (
    Vec<serde_json::Value>,
    Vec<serde_json::Value>,
    Vec<serde_json::Value>,
    NativeFirstPlayableRuntime,
) {
    let mut app = build_native_button_sequence_app(actor_id);
    let mut samples = vec![sample_live_app_state(&mut app, "initial")];
    let mut input_samples = vec![sample_live_input_state(
        app.world().resource::<NativeFirstPlayableRuntime>(),
        "initial",
    )];
    let mut button_events = Vec::new();
    for action in actions {
        let event = press_live_button_action(&mut app, action.clone());
        let stage = format!("after_{}", native_control_action_label(&action));
        button_events.push(event);
        samples.push(sample_live_app_state(&mut app, &stage));
        input_samples.push(sample_live_input_state(
            app.world().resource::<NativeFirstPlayableRuntime>(),
            &stage,
        ));
    }
    let final_runtime = app.world().resource::<NativeFirstPlayableRuntime>().clone();
    (samples, input_samples, button_events, final_runtime)
}

fn build_native_button_sequence_app(actor_id: &str) -> App {
    let mut app = App::new();
    app.init_resource::<InputFocus>()
        .add_plugins(MinimalPlugins)
        .add_plugins(TrillionniumWorldBevyPlugin::new(
            native_bevy_playable_fixture(),
            actor_id,
        ))
        .add_systems(
            Startup,
            (
                spawn_native_render_scene,
                bind_runtime_textures_to_authored_sprite_surfaces,
            )
                .chain(),
        )
        .add_systems(
            Update,
            (
                handle_native_control_buttons,
                sync_player_sprite_to_world,
                update_native_visible_actor_runtime,
                update_native_world_hud,
                update_native_game_feedback_visuals,
                update_native_tile_rpg_interaction_ui,
                update_native_tile_rpg_scene_visuals,
                update_native_input_hint_ui,
                update_native_session_recovery_ui,
                update_native_session_slot_ui,
                update_native_session_resume_ui,
                update_native_pause_menu_ui,
                update_native_settings_menu_ui,
                update_native_title_menu_ui,
                update_native_character_create_ui,
                update_native_text_adventure_ui,
                update_native_right_rail_summary_ui,
                update_native_contextual_button_visuals,
            ),
        );
    app.add_systems(Update, update_native_account_client_ui);
    app.update();
    app
}

