fn sample_live_input_state(runtime: &NativeFirstPlayableRuntime, stage: &str) -> serde_json::Value {
    let actions = native_live_probe_actions();
    let availability = actions
        .iter()
        .map(|action| {
            let (enabled, reason) = native_live_action_availability(runtime, action);
            json!({
                "action": native_control_action_label(action),
                "enabled": enabled,
                "reason": reason,
            })
        })
        .collect::<Vec<_>>();
    let contextual_action_deck = native_contextual_action_deck(runtime);
    json!({
        "stage": stage,
        "movement_input_locked": runtime.movement_input_locked,
        "session_resume_input_locked": runtime.session_resume_input_locked,
        "session_continue_cta_visible": runtime.session_continue_cta_visible,
        "session_pause_input_locked": runtime.session_pause_input_locked,
        "session_pause_menu_visible": runtime.session_pause_menu_visible,
        "session_settings_menu_visible": runtime.session_settings_menu_visible,
        "session_settings_volume_level": runtime.session_settings_volume_level,
        "session_settings_low_motion_enabled": runtime.session_settings_low_motion_enabled,
        "session_settings_input_mode": runtime.session_settings_input_mode,
        "session_title_menu_visible": runtime.session_title_menu_visible,
        "session_title_input_locked": runtime.session_title_input_locked,
        "session_title_boot_state": runtime.session_title_boot_state,
        "session_title_last_slot_id": runtime.session_title_last_slot_id,
        "session_account_auth_state": runtime.session_account_auth_state,
        "session_account_display_name": runtime.session_account_display_name,
        "session_account_last_action": runtime.session_account_last_action,
        "session_account_session_bound": runtime.session_account_session_bound,
        "session_character_create_visible": runtime.session_character_create_visible,
        "session_character_create_input_locked": runtime.session_character_create_input_locked,
        "session_character_create_name": runtime.session_character_create_name,
        "session_character_create_archetype": runtime.session_character_create_archetype,
        "availability": availability,
        "contextual_action_deck": contextual_action_deck,
    })
}

