fn availability_enabled(sample: Option<&serde_json::Value>, action: &str) -> bool {
    sample
        .and_then(|sample| sample.get("availability"))
        .and_then(|value| value.as_array())
        .and_then(|items| {
            items
                .iter()
                .find(|item| item.get("action").and_then(|value| value.as_str()) == Some(action))
        })
        .and_then(|item| item.get("enabled"))
        .and_then(|value| value.as_bool())
        .unwrap_or(false)
}

fn locked_movement_blocks_input(runtime: &NativeFirstPlayableRuntime) -> bool {
    let mut locked_runtime = runtime.clone();
    locked_runtime.movement_input_locked = true;
    !native_live_action_availability(
        &locked_runtime,
        &NativeControlAction::Move {
            direction: "north".to_string(),
        },
    )
    .0
}

