fn authored_art_asset_surface(
    surface_id: impl Into<String>,
    asset_id: impl Into<String>,
    asset_kind: impl Into<String>,
    gameplay_layer: impl Into<String>,
    replacement_slot: impl Into<String>,
    target_resolution_px: u16,
) -> BevyWorldAuthoredArtAssetSurface {
    BevyWorldAuthoredArtAssetSurface {
        surface_id: surface_id.into(),
        asset_pack_id: "trnm_world_authored_art_pack_v1".to_string(),
        asset_id: asset_id.into(),
        asset_kind: asset_kind.into(),
        gameplay_layer: gameplay_layer.into(),
        replacement_slot: replacement_slot.into(),
        source_origin: "local_authored_primitive_manifest_v1".to_string(),
        license_scope: "project_owned_internal_placeholder".to_string(),
        target_resolution_px,
        export_ready: true,
    }
}

fn authored_asset_kind_for_layer(layer: &str, asset_role: &str) -> &'static str {
    match layer {
        "road" => "road_tile",
        "building" => "building_tile",
        "greenery" => "foliage_sprite",
        "water" => "water_tile",
        "hud" if asset_role.contains("glyph") => "hud_glyph",
        "hud" => "hud_icon",
        _ => "terrain_tile",
    }
}

fn authored_replacement_slot_for_layer(layer: &str, asset_role: &str) -> &'static str {
    match layer {
        "hud" if asset_role.contains("glyph") => "hud_glyph_slot",
        "hud" => "hud_icon_slot",
        "road" | "building" | "greenery" | "water" | "terrain" => "tile_sprite_slot",
        _ => "generic_sprite_slot",
    }
}

fn map_tile_tileset_polish_surface(
    base_surface_id: &str,
    row: usize,
    col: usize,
) -> BevyWorldTilesetPolishSurface {
    let (atlas_family, layer, asset_role, palette_role, detail_role) = match base_surface_id {
        "indoor_room_tiles" => (
            "city_ground_tileset_v1",
            "terrain",
            "terrain_base",
            "earth",
            "interior_floor_checker",
        ),
        "stone_road_tiles" => (
            "road_tileset_v1",
            "road",
            "road_base",
            "stone",
            "walkable_center_tile",
        ),
        "water_tiles" => (
            "water_tileset_v1",
            "water",
            "water_base",
            "water",
            "harbor_water_tile",
        ),
        "town_wall_tiles" => (
            "building_tileset_v1",
            "building",
            "building_wall_base",
            "cool_stone",
            "town_wall_block",
        ),
        _ => (
            "city_ground_tileset_v1",
            "terrain",
            "terrain_base",
            "foliage",
            "outdoor_grass_variation",
        ),
    };
    tileset_polish_surface(
        format!("tile:{base_surface_id}:{row}:{col}"),
        atlas_family,
        layer,
        asset_role,
        palette_role,
        detail_role,
    )
}

fn map_tile_authored_art_asset_surface(
    base_surface_id: &str,
    row: usize,
    col: usize,
) -> BevyWorldAuthoredArtAssetSurface {
    let (asset_kind, gameplay_layer, replacement_slot, target_resolution_px) = match base_surface_id
    {
        "indoor_room_tiles" => ("terrain_tile", "terrain", "tile_sprite_slot", 32),
        "stone_road_tiles" => ("road_tile", "road", "tile_sprite_slot", 32),
        "water_tiles" => ("water_tile", "water", "tile_sprite_slot", 32),
        "town_wall_tiles" => ("building_tile", "building", "tile_sprite_slot", 32),
        _ => ("terrain_tile", "terrain", "tile_sprite_slot", 32),
    };
    authored_art_asset_surface(
        format!("art_asset:tile:{base_surface_id}:{row}:{col}"),
        format!("asset.{gameplay_layer}.{base_surface_id}.{row}.{col}"),
        asset_kind,
        gameplay_layer,
        replacement_slot,
        target_resolution_px,
    )
}

