fn spawn_map_pack_model_visuals(commands: &mut Commands) {
    let modeling = trnm_world_map_provider::trillionnium_world_map_modeling_gate_json();
    if modeling
        .pointer("/gates/all_layers_modeled")
        .and_then(Value::as_bool)
        != Some(true)
    {
        return;
    }

    if let Some(terrains) = modeling
        .pointer("/modeling_layers/terrain")
        .and_then(Value::as_array)
    {
        for terrain in terrains {
            let zone_id = json_str(terrain, "zone_id");
            let (center, size, color) = terrain_zone_visual(zone_id);
            commands.spawn((
                Sprite::from_color(color, size),
                Transform::from_translation(center),
                map_model_surface(zone_id, "terrain", zone_id, zone_id, "terrain_zone_surface"),
                BevyWorldTileRpgSurface {
                    surface_id: zone_id.to_string(),
                    role: "terrain_zone_surface".to_string(),
                },
            ));
        }
    }

    if let Some(roads) = modeling
        .pointer("/modeling_layers/roads")
        .and_then(Value::as_array)
    {
        for road in roads {
            let model_id = json_str(road, "model_id");
            let Some(points) = road.get("path_polyline").and_then(Value::as_array) else {
                continue;
            };
            if points.len() < 2 {
                continue;
            }
            let start = map_model_point_from_json(&points[0], 3.62);
            let end = map_model_point_from_json(&points[1], 3.62);
            let midpoint = Vec3::new((start.x + end.x) * 0.5, (start.y + end.y) * 0.5, 3.62);
            let dx = end.x - start.x;
            let dy = end.y - start.y;
            let segment_length = (dx * dx + dy * dy).sqrt();
            let road_angle = dy.atan2(dx);
            let size = Vec2::new(segment_length + 34.0, 7.0);
            let source_id = road
                .get("source_edge")
                .and_then(|edge| {
                    let from = edge.get("from").and_then(Value::as_str)?;
                    let to = edge.get("to").and_then(Value::as_str)?;
                    Some(format!("{from}->{to}"))
                })
                .unwrap_or_else(|| "unknown-road-edge".to_string());
            commands.spawn((
                Sprite::from_color(Color::srgba(0.50, 0.44, 0.32, 0.72), size),
                Transform {
                    translation: midpoint,
                    rotation: Quat::from_rotation_z(road_angle),
                    ..Default::default()
                },
                map_model_surface(model_id, "road", model_id, source_id, "walkable_road_path"),
                BevyWorldTileRpgSurface {
                    surface_id: model_id.to_string(),
                    role: "map_pack_road_path".to_string(),
                },
            ));
        }
    }

    if let Some(buildings) = modeling
        .pointer("/modeling_layers/buildings")
        .and_then(Value::as_array)
    {
        for building in buildings {
            let model_id = json_str(building, "model_id");
            let source_node_id = json_str(building, "source_node_id");
            let node_kind = json_str(building, "node_kind");
            let Some(center_value) = building.pointer("/footprint/center") else {
                continue;
            };
            let height_m = building
                .get("height_m")
                .and_then(Value::as_i64)
                .unwrap_or(10);
            let center = map_model_point_from_json(center_value, 3.82);
            let size = if height_m >= 20 {
                Vec2::new(26.0, 52.0)
            } else if height_m <= 4 {
                Vec2::new(42.0, 18.0)
            } else if node_kind.contains("gate") || node_kind.contains("arcade") {
                Vec2::new(48.0, 34.0)
            } else {
                Vec2::new(32.0, 30.0)
            };
            commands.spawn((
                Sprite::from_color(map_model_building_color(node_kind), size),
                Transform::from_translation(center),
                map_model_surface(
                    model_id,
                    "building",
                    model_id,
                    source_node_id,
                    "building_mass",
                ),
                BevyWorldTileRpgSurface {
                    surface_id: model_id.to_string(),
                    role: "map_pack_building_mass".to_string(),
                },
            ));
        }
    }

    if let Some(greeneries) = modeling
        .pointer("/modeling_layers/greenery")
        .and_then(Value::as_array)
    {
        for greenery in greeneries {
            let model_id = json_str(greenery, "model_id");
            let source_node_id = json_str(greenery, "source_node_id");
            let Some(center_value) = greenery.get("center") else {
                continue;
            };
            let center = map_model_point_from_json(center_value, 4.02);
            let density = json_str(greenery, "density");
            let size = if density == "medium" {
                Vec2::new(34.0, 28.0)
            } else {
                Vec2::new(26.0, 22.0)
            };
            commands.spawn((
                Sprite::from_color(Color::srgba(0.22, 0.55, 0.24, 0.86), size),
                Transform::from_translation(center + Vec3::new(12.0, 10.0, 0.0)),
                map_model_surface(
                    model_id,
                    "greenery",
                    model_id,
                    source_node_id,
                    "greenery_cluster",
                ),
                BevyWorldTileRpgSurface {
                    surface_id: model_id.to_string(),
                    role: "map_pack_greenery_cluster".to_string(),
                },
            ));
        }
    }
}

fn json_str<'a>(value: &'a Value, key: &str) -> &'a str {
    value.get(key).and_then(Value::as_str).unwrap_or("unknown")
}

fn map_model_point_from_json(value: &Value, z: f32) -> Vec3 {
    let x = value.get("x").and_then(Value::as_f64).unwrap_or_default() as f32;
    let y = value.get("y").and_then(Value::as_f64).unwrap_or_default() as f32;
    Vec3::new(-124.0 + x * 58.0, 122.0 - y * 38.0, z)
}

fn terrain_zone_visual(zone_id: &str) -> (Vec3, Vec2, Color) {
    match zone_id {
        "terrain:mirror-city-paved-lowland" => (
            Vec3::new(-84.0, 78.0, 3.05),
            Vec2::new(238.0, 128.0),
            Color::srgba(0.22, 0.26, 0.24, 0.58),
        ),
        "terrain:craft-district-yard" => (
            Vec3::new(-42.0, 94.0, 3.06),
            Vec2::new(190.0, 106.0),
            Color::srgba(0.24, 0.34, 0.22, 0.50),
        ),
        "terrain:river-cistern-wetland" => (
            Vec3::new(-2.0, -28.0, 3.07),
            Vec2::new(224.0, 92.0),
            Color::srgba(0.16, 0.34, 0.40, 0.52),
        ),
        "terrain:survey-tower-ridge" => (
            Vec3::new(160.0, -88.0, 3.08),
            Vec2::new(250.0, 118.0),
            Color::srgba(0.38, 0.36, 0.28, 0.50),
        ),
        _ => (
            Vec3::new(-120.0, -20.0, 3.04),
            Vec2::new(160.0, 90.0),
            Color::srgba(0.18, 0.28, 0.22, 0.45),
        ),
    }
}

fn map_model_building_color(node_kind: &str) -> Color {
    if node_kind.contains("tower") {
        Color::srgba(0.55, 0.52, 0.43, 0.92)
    } else if node_kind.contains("gate") || node_kind.contains("arcade") {
        Color::srgba(0.60, 0.42, 0.30, 0.92)
    } else if node_kind.contains("yard") || node_kind.contains("camp") {
        Color::srgba(0.36, 0.42, 0.24, 0.86)
    } else if node_kind.contains("water") || node_kind.contains("cistern") {
        Color::srgba(0.24, 0.46, 0.50, 0.88)
    } else {
        Color::srgba(0.66, 0.56, 0.38, 0.90)
    }
}

