#[allow(clippy::too_many_arguments)]
pub fn handle_native_keyboard_input(
    input: Res<ButtonInput<KeyCode>>,
    bootstrap: Res<NativeWorldBootstrap>,
    mut world: ResMut<AuthoritativeWorldResource>,
    mut projection: ResMut<BevyWorldProjection>,
    mut tactics_character: ResMut<NativeTacticsCharacter>,
    mut gameplay_log: ResMut<NativeGameplayLog>,
    mut first_playable: ResMut<NativeFirstPlayableRuntime>,
    mut commands: Commands,
) {
    let control_action = if let Some(direction) = keyboard_direction(&input) {
        Some(NativeControlAction::Move {
            direction: direction.to_string(),
        })
    } else if input.just_pressed(KeyCode::KeyR) {
        Some(NativeControlAction::Talk)
    } else if input.just_pressed(KeyCode::KeyT) {
        Some(NativeControlAction::Train)
    } else if input.just_pressed(KeyCode::KeyF) || input.just_pressed(KeyCode::Space) {
        Some(NativeControlAction::Fight)
    } else if input.just_pressed(KeyCode::KeyC) {
        Some(NativeControlAction::CompleteTask)
    } else if input.just_pressed(KeyCode::KeyI) {
        Some(NativeControlAction::Equip)
    } else if input.just_pressed(KeyCode::KeyB) {
        Some(NativeControlAction::OpenBag)
    } else if input.just_pressed(KeyCode::KeyL) {
        Some(NativeControlAction::LootDrop)
    } else if input.just_pressed(KeyCode::KeyO) {
        Some(NativeControlAction::EquipItem {
            item_id: "bandit_sash".to_string(),
        })
    } else if input.just_pressed(KeyCode::KeyJ) {
        Some(NativeControlAction::CombatAttack)
    } else if input.just_pressed(KeyCode::KeyK) {
        Some(NativeControlAction::CombatDefend)
    } else if input.just_pressed(KeyCode::KeyU) {
        Some(NativeControlAction::CombatUseItem)
    } else if input.just_pressed(KeyCode::KeyG) {
        Some(NativeControlAction::AllocateStat {
            stat_id: "force".to_string(),
        })
    } else if input.just_pressed(KeyCode::KeyH) {
        Some(NativeControlAction::AllocateStat {
            stat_id: "agility".to_string(),
        })
    } else if input.just_pressed(KeyCode::KeyV) {
        Some(NativeControlAction::AllocateStat {
            stat_id: "craft".to_string(),
        })
    } else if input.just_pressed(KeyCode::KeyM) {
        Some(NativeControlAction::ConfirmStatAllocation)
    } else if input.just_pressed(KeyCode::KeyN) && first_playable.session_character_create_visible {
        Some(NativeControlAction::CycleCharacterName)
    } else if input.just_pressed(KeyCode::KeyY) && first_playable.session_character_create_visible {
        Some(NativeControlAction::CycleCharacterArchetype)
    } else if input.just_pressed(KeyCode::KeyP) || input.just_pressed(KeyCode::Escape) {
        if first_playable.pending_stat_allocation.is_some() {
            Some(NativeControlAction::CancelStatAllocation)
        } else if first_playable.session_character_create_visible {
            Some(NativeControlAction::BackToTitleFromCreate)
        } else {
            Some(NativeControlAction::PauseMenu)
        }
    } else if input.just_pressed(KeyCode::Enter) || input.just_pressed(KeyCode::NumpadEnter) {
        if first_playable.pending_stat_allocation.is_some() {
            Some(NativeControlAction::ConfirmStatAllocation)
        } else if first_playable.session_character_create_visible {
            Some(NativeControlAction::ConfirmCharacterCreate)
        } else if first_playable.session_resume_input_locked
            || first_playable.session_continue_cta_visible
        {
            Some(NativeControlAction::ContinueAfterLoad)
        } else if first_playable.session_pause_menu_visible
            || first_playable.session_pause_input_locked
        {
            Some(NativeControlAction::ResumeFromPause)
        } else if let Some(focus_action) =
            build_branch_title_route_action_focus_control_action(&first_playable)
        {
            Some(focus_action)
        } else if let Some(next_action) =
            native_control_action_from_label(first_minute_onboarding_next_button(&first_playable))
        {
            Some(next_action)
        } else {
            Some(NativeControlAction::ContinueAfterLoad)
        }
    } else {
        None
    };

    if let Some(action) = control_action {
        let response = apply_live_native_action_with_source(
            &mut world.state,
            &mut tactics_character.character,
            &mut gameplay_log,
            &mut first_playable,
            &bootstrap.actor_id,
            "keyboard",
            action,
        );
        *projection = projection_resource(&world.state, &bootstrap.actor_id);
        if let Some(response) = response {
            commands.insert_resource(LastNativeCommandResponse {
                response_json: serde_json::to_string(&response)
                    .expect("native control response serializes"),
            });
        }
    }
}

#[allow(clippy::too_many_arguments, clippy::type_complexity)]
pub fn handle_native_control_buttons(
    mut input_focus: ResMut<InputFocus>,
    mut interactions: Query<
        (
            Entity,
            &Interaction,
            &NativeControlAction,
            &mut BackgroundColor,
            &mut BorderColor,
            &mut Button,
        ),
        (Changed<Interaction>, With<Button>),
    >,
    bootstrap: Res<NativeWorldBootstrap>,
    mut world: ResMut<AuthoritativeWorldResource>,
    mut projection: ResMut<BevyWorldProjection>,
    mut tactics_character: ResMut<NativeTacticsCharacter>,
    mut gameplay_log: ResMut<NativeGameplayLog>,
    mut first_playable: ResMut<NativeFirstPlayableRuntime>,
    mut commands: Commands,
) {
    for (entity, interaction, action, mut color, mut border, mut button) in &mut interactions {
        match *interaction {
            Interaction::Pressed => {
                input_focus.set(entity, FocusCause::Pressed);
                *color = BackgroundColor(Color::srgb(0.34, 0.52, 0.32));
                *border = BorderColor::all(Color::srgb(0.96, 0.86, 0.45));
                button.set_changed();
                let response = apply_live_native_action_with_source(
                    &mut world.state,
                    &mut tactics_character.character,
                    &mut gameplay_log,
                    &mut first_playable,
                    &bootstrap.actor_id,
                    "bevy_button",
                    action.clone(),
                );
                *projection = projection_resource(&world.state, &bootstrap.actor_id);
                if let Some(response) = response {
                    commands.insert_resource(LastNativeCommandResponse {
                        response_json: serde_json::to_string(&response)
                            .expect("native control response serializes"),
                    });
                }
            }
            Interaction::Hovered => {
                input_focus.set(entity, FocusCause::Pressed);
                *color = BackgroundColor(Color::srgb(0.16, 0.26, 0.27));
                *border = BorderColor::all(Color::srgb(0.70, 0.78, 0.72));
                button.set_changed();
            }
            Interaction::None => {
                input_focus.clear();
                *color = BackgroundColor(Color::srgb(0.10, 0.18, 0.19));
                *border = BorderColor::all(Color::srgb(0.45, 0.55, 0.52));
            }
        }
    }
}

pub fn apply_live_native_action(
    world: &mut WorldState,
    character: &mut WorldTrillionniumCharacter,
    gameplay_log: &mut NativeGameplayLog,
    first_playable: &mut NativeFirstPlayableRuntime,
    actor_id: &str,
    action: NativeControlAction,
) -> Option<WorldApiCommandResponse> {
    apply_live_native_action_with_source(
        world,
        character,
        gameplay_log,
        first_playable,
        actor_id,
        "direct",
        action,
    )
}

pub fn apply_live_native_action_with_source(
    world: &mut WorldState,
    character: &mut WorldTrillionniumCharacter,
    gameplay_log: &mut NativeGameplayLog,
    first_playable: &mut NativeFirstPlayableRuntime,
    actor_id: &str,
    input_source: &str,
    action: NativeControlAction,
) -> Option<WorldApiCommandResponse> {
    let availability = native_live_action_availability(first_playable, &action);
    let label = native_control_action_label(&action);
    if !availability.0 {
        gameplay_log.turn += 1;
        gameplay_log.last_action = format!("blocked:{label}");
        gameplay_log.last_result = availability.1.clone();
        gameplay_log.last_rejection = Some(availability.1.clone());
        push_history(
            &mut first_playable.blocked_action_history,
            &format!("{label}:{}", availability.1),
        );
        push_feedback_event(
            first_playable,
            &format!("Input blocked: {label} ({})", availability.1),
        );
        refresh_contextual_action_runtime(first_playable);
        record_input_feedback(first_playable, input_source, &label, false, &availability.1);
        return None;
    }
    let response = apply_native_first_playable_action(
        world,
        character,
        gameplay_log,
        first_playable,
        actor_id,
        action,
    );
    record_input_feedback(first_playable, input_source, &label, true, &availability.1);
    response
}

fn active_build_title_route_accept_availability(
    runtime: &NativeFirstPlayableRuntime,
) -> (bool, String) {
    let Some((_, stat_id, _effect_id)) = active_build_title_parts(runtime) else {
        return (false, "title_route_recommendation_missing".to_string());
    };
    let Some(task_id) = build_branch_title_recommended_task_id_for_runtime_stat(runtime, stat_id)
    else {
        return (false, format!("title_route_complete:{stat_id}"));
    };
    let plan = scene_pack_route_plan_for_task(&runtime.current_room_id, task_id);
    if let Some(blocked_reason) = plan.blocked_reason.as_deref() {
        return (
            false,
            format!("title_route_step_blocked:{task_id}:{blocked_reason}"),
        );
    }
    if runtime.current_room_id != plan.target_room_id
        && build_mastery_room_override(runtime, &plan.target_room_id)
    {
        return if runtime
            .available_room_exits
            .iter()
            .any(|exit| exit == &plan.target_room_id)
        {
            (
                true,
                format!(
                    "enabled_title_route_step:{stat_id}:{task_id}:{}",
                    plan.target_room_id
                ),
            )
        } else {
            (
                false,
                format!(
                    "title_route_step_blocked:{task_id}:room_not_adjacent:{}",
                    plan.target_room_id
                ),
            )
        };
    }
    if runtime.current_room_id == plan.target_room_id {
        let start_action = NativeControlAction::StartTask {
            task_id: task_id.to_string(),
        };
        let (enabled, reason) = native_live_action_availability(runtime, &start_action);
        return if enabled {
            (
                true,
                format!("enabled_title_route_start:{stat_id}:{task_id}"),
            )
        } else {
            (false, format!("title_route_start_blocked:{reason}"))
        };
    }
    let Some(next_room_id) = plan.steps.first().map(|step| step.to_room_id.clone()) else {
        return (false, format!("title_route_waiting:{task_id}"));
    };
    if scene_pack_room(&next_room_id).is_none() {
        return (
            false,
            format!("title_route_step_blocked:{task_id}:unknown_room:{next_room_id}"),
        );
    }
    if runtime
        .available_room_exits
        .iter()
        .any(|exit| exit == &next_room_id)
    {
        (
            true,
            format!("enabled_title_route_step:{stat_id}:{task_id}:{next_room_id}"),
        )
    } else {
        (
            false,
            format!("title_route_step_blocked:{task_id}:room_not_adjacent:{next_room_id}"),
        )
    }
}

pub fn native_live_action_availability(
    runtime: &NativeFirstPlayableRuntime,
    action: &NativeControlAction,
) -> (bool, String) {
    if matches!(action, NativeControlAction::ContinueAfterLoad) {
        return if runtime.session_resume_input_locked || runtime.session_continue_cta_visible {
            (true, "enabled_session_resume_continue".to_string())
        } else {
            (false, "session_resume_not_active".to_string())
        };
    }
    if matches!(
        action,
        NativeControlAction::RegisterAccountFromTitle
            | NativeControlAction::LoginAccountFromTitle
            | NativeControlAction::ContinueAccountFromTitle
    ) {
        let reason = match action {
            NativeControlAction::RegisterAccountFromTitle => "enabled_title_account_register",
            NativeControlAction::LoginAccountFromTitle => "enabled_title_account_login",
            NativeControlAction::ContinueAccountFromTitle => "enabled_title_account_continue",
            _ => unreachable!("matched account title flow action"),
        };
        return (true, reason.to_string());
    }
    if runtime.session_resume_input_locked {
        return (false, "session_resume_continue_required".to_string());
    }
    if matches!(
        action,
        NativeControlAction::CycleCharacterName
            | NativeControlAction::CycleCharacterArchetype
            | NativeControlAction::ConfirmCharacterCreate
            | NativeControlAction::BackToTitleFromCreate
    ) {
        return if runtime.session_character_create_visible
            || runtime.session_character_create_input_locked
        {
            let reason = match action {
                NativeControlAction::CycleCharacterName => "enabled_character_name_cycle",
                NativeControlAction::CycleCharacterArchetype => "enabled_character_archetype_cycle",
                NativeControlAction::ConfirmCharacterCreate => "enabled_character_create_confirm",
                NativeControlAction::BackToTitleFromCreate => "enabled_character_create_back",
                _ => unreachable!("matched character create action"),
            };
            (true, reason.to_string())
        } else {
            (false, "character_create_not_active".to_string())
        };
    }
    if runtime.session_character_create_input_locked && !character_create_allows_action(action) {
        return (false, "character_create_confirm_required".to_string());
    }
    if matches!(action, NativeControlAction::OpenTitleMenu) {
        return if runtime.session_title_menu_visible || runtime.session_title_input_locked {
            (false, "title_menu_already_open".to_string())
        } else {
            (true, "enabled_open_title_menu".to_string())
        };
    }
    if matches!(action, NativeControlAction::NewGameFromTitle) {
        return if runtime.session_title_menu_visible || runtime.session_title_input_locked {
            (true, "enabled_title_new_game".to_string())
        } else {
            (false, "title_menu_not_active".to_string())
        };
    }
    if matches!(action, NativeControlAction::LoadFromTitle) {
        let slot_id = normalize_session_slot_id(&runtime.session_selected_slot_id);
        let slot_path = native_action_session_slot_path(&slot_id);
        return if !(runtime.session_title_menu_visible || runtime.session_title_input_locked) {
            (false, "title_menu_not_active".to_string())
        } else if Path::new(&slot_path).exists() {
            (true, format!("enabled_title_load_slot:{slot_id}"))
        } else {
            (false, format!("title_load_slot_missing:{slot_id}"))
        };
    }
    if matches!(action, NativeControlAction::ContinueFromTitle) {
        let slot_id = normalize_session_slot_id(&runtime.session_selected_slot_id);
        let slot_path = native_action_session_slot_path(&slot_id);
        return if !(runtime.session_title_menu_visible || runtime.session_title_input_locked) {
            (false, "title_menu_not_active".to_string())
        } else if Path::new(&slot_path).exists() {
            (true, format!("enabled_title_continue_slot:{slot_id}"))
        } else {
            (false, format!("title_continue_slot_missing:{slot_id}"))
        };
    }
    if runtime.session_title_input_locked && !title_menu_allows_action(action) {
        return (false, "title_menu_choice_required".to_string());
    }
    if matches!(action, NativeControlAction::PauseMenu) {
        return if runtime.session_pause_menu_visible || runtime.session_pause_input_locked {
            (false, "pause_menu_already_open".to_string())
        } else {
            (true, "enabled_open_pause_menu".to_string())
        };
    }
    if matches!(action, NativeControlAction::ResumeFromPause) {
        return if runtime.session_pause_menu_visible || runtime.session_pause_input_locked {
            (true, "enabled_pause_resume".to_string())
        } else {
            (false, "pause_menu_not_active".to_string())
        };
    }
    if matches!(action, NativeControlAction::OpenSettingsMenu) {
        return if !(runtime.session_pause_menu_visible || runtime.session_pause_input_locked) {
            (false, "pause_menu_required_before_settings".to_string())
        } else if runtime.session_settings_menu_visible {
            (false, "settings_menu_already_open".to_string())
        } else {
            (true, "enabled_open_settings_menu".to_string())
        };
    }
    if matches!(action, NativeControlAction::CloseSettingsMenu) {
        return if runtime.session_settings_menu_visible {
            (true, "enabled_close_settings_menu".to_string())
        } else {
            (false, "settings_menu_not_active".to_string())
        };
    }
    if matches!(
        action,
        NativeControlAction::ToggleLowMotion
            | NativeControlAction::VolumeDown
            | NativeControlAction::VolumeUp
            | NativeControlAction::CycleInputMode
    ) {
        return if runtime.session_settings_menu_visible {
            (true, "enabled_settings_adjustment".to_string())
        } else if runtime.session_pause_menu_visible || runtime.session_pause_input_locked {
            (false, "settings_menu_required".to_string())
        } else {
            (false, "pause_menu_required_before_settings".to_string())
        };
    }
    if runtime.session_pause_input_locked && !pause_menu_allows_action(action) {
        return (false, "pause_menu_resume_required".to_string());
    }
    if runtime.movement_input_locked {
        return (false, "movement_input_locked".to_string());
    }
    match action {
        NativeControlAction::Talk => {
            if runtime
                .completed_steps
                .iter()
                .any(|step| step == "talk_to_mentor")
            {
                (false, "mentor_dialogue_already_opened".to_string())
            } else {
                (true, "enabled_at_mentor_tile".to_string())
            }
        }
        NativeControlAction::Train => {
            if runtime
                .completed_steps
                .iter()
                .any(|step| step == "train_basic_unarmed")
            {
                (false, "training_already_complete".to_string())
            } else if runtime.dialogue_overlay_visible
                || runtime
                    .completed_steps
                    .iter()
                    .any(|step| step == "talk_to_mentor")
            {
                (true, "enabled_after_dialogue_choice".to_string())
            } else {
                (false, "talk_required_before_training".to_string())
            }
        }
        NativeControlAction::Move { direction } => {
            if direction == "wait" {
                (true, "wait_allowed".to_string())
            } else if runtime
                .completed_steps
                .iter()
                .any(|step| step == "arrive_at_first_objective")
            {
                (false, "already_at_arena".to_string())
            } else if runtime
                .completed_steps
                .iter()
                .any(|step| step == "train_basic_unarmed")
            {
                (true, format!("enabled_route_step_{direction}"))
            } else {
                (false, "training_required_before_route_move".to_string())
            }
        }
        NativeControlAction::Fight => {
            if runtime
                .completed_steps
                .iter()
                .any(|step| step == "resolve_first_combat")
            {
                (false, "combat_already_resolved".to_string())
            } else if runtime
                .completed_steps
                .iter()
                .any(|step| step == "arrive_at_first_objective")
            {
                (true, "enabled_enemy_adjacent".to_string())
            } else {
                (false, "arena_required_before_fight".to_string())
            }
        }
        NativeControlAction::CompleteTask => {
            if let Some(task_id) = active_build_branch_mastery_challenge_task_id(runtime) {
                build_branch_mastery_challenge_completion_availability(runtime, task_id)
            } else if let Some(task_id) = active_build_branch_followup_task_id(runtime) {
                build_branch_followup_completion_availability(runtime, task_id)
            } else if let Some(task_id) = active_build_branch_task_id(runtime) {
                build_branch_completion_availability(runtime, task_id)
            } else if runtime
                .completed_steps
                .iter()
                .any(|step| step == "resolve_first_combat")
            {
                (true, "enabled_after_combat".to_string())
            } else {
                (false, "combat_required_before_task_completion".to_string())
            }
        }
        NativeControlAction::Equip => {
            if runtime.equipment_ready {
                (false, "equipment_already_ready".to_string())
            } else if runtime.reward_claimed {
                (true, "enabled_after_reward_claim".to_string())
            } else {
                (false, "reward_required_before_equip".to_string())
            }
        }
        NativeControlAction::EnterRoom { room_id } => {
            if runtime.current_room_id == *room_id {
                (false, "already_in_room".to_string())
            } else if runtime
                .available_room_exits
                .iter()
                .any(|exit| exit == room_id)
            {
                (true, format!("enabled_exit_to_{room_id}"))
            } else {
                (false, format!("room_not_adjacent:{room_id}"))
            }
        }
        NativeControlAction::InteractNpc { npc_id } => {
            if runtime
                .active_room_npc_ids
                .iter()
                .any(|available| available == npc_id)
            {
                (true, format!("enabled_npc_{npc_id}"))
            } else {
                (false, format!("npc_not_in_current_room:{npc_id}"))
            }
        }
        NativeControlAction::StartTask { task_id } => {
            if let Some(required_stat) = build_branch_task_required_stat(task_id) {
                if !runtime_has_equipped_bandit_sash(runtime) {
                    (false, format!("build_branch_requires_sash:{task_id}"))
                } else if !runtime_has_active_sash_stat(runtime, required_stat) {
                    (
                        false,
                        format!("build_branch_requires_{required_stat}:{task_id}"),
                    )
                } else if runtime
                    .completed_task_ids
                    .iter()
                    .any(|completed| completed == task_id)
                {
                    (false, format!("task_already_completed:{task_id}"))
                } else if runtime
                    .active_task_ids
                    .iter()
                    .any(|active| active == task_id)
                {
                    (false, format!("task_already_active:{task_id}"))
                } else if !runtime
                    .unlocked_task_ids
                    .iter()
                    .any(|unlocked| unlocked == task_id)
                {
                    (false, format!("task_locked_by_progression:{task_id}"))
                } else if runtime
                    .available_task_ids
                    .iter()
                    .any(|available| available == task_id)
                {
                    (
                        true,
                        format!("enabled_build_branch_{required_stat}:{task_id}"),
                    )
                } else {
                    (false, format!("task_not_in_current_room:{task_id}"))
                }
            } else if let Some(required_stat) =
                build_branch_mastery_challenge_required_stat(task_id)
            {
                if !runtime_has_build_mastery(runtime, required_stat) {
                    (
                        false,
                        format!("mastery_challenge_requires_{required_stat}:{task_id}"),
                    )
                } else if runtime
                    .completed_task_ids
                    .iter()
                    .any(|completed| completed == task_id)
                {
                    (false, format!("task_already_completed:{task_id}"))
                } else if runtime
                    .active_task_ids
                    .iter()
                    .any(|active| active == task_id)
                {
                    (false, format!("task_already_active:{task_id}"))
                } else if !runtime
                    .unlocked_task_ids
                    .iter()
                    .any(|unlocked| unlocked == task_id)
                {
                    (false, format!("task_locked_by_progression:{task_id}"))
                } else if runtime
                    .available_task_ids
                    .iter()
                    .any(|available| available == task_id)
                {
                    (
                        true,
                        format!("enabled_build_mastery_challenge_{required_stat}:{task_id}"),
                    )
                } else {
                    (false, format!("task_not_in_current_room:{task_id}"))
                }
            } else if runtime
                .completed_task_ids
                .iter()
                .any(|completed| completed == task_id)
            {
                (false, format!("task_already_completed:{task_id}"))
            } else if runtime
                .active_task_ids
                .iter()
                .any(|active| active == task_id)
            {
                (false, format!("task_already_active:{task_id}"))
            } else if runtime
                .available_task_ids
                .iter()
                .any(|available| available == task_id)
                && (!task_requires_progression_unlock(task_id)
                    || runtime
                        .unlocked_task_ids
                        .iter()
                        .any(|unlocked| unlocked == task_id))
            {
                (true, format!("enabled_task_{task_id}"))
            } else if task_requires_progression_unlock(task_id)
                && !runtime
                    .unlocked_task_ids
                    .iter()
                    .any(|unlocked| unlocked == task_id)
            {
                (false, format!("task_locked_by_progression:{task_id}"))
            } else {
                (false, format!("task_not_in_current_room:{task_id}"))
            }
        }
        NativeControlAction::CombatAttack
        | NativeControlAction::CombatDefend
        | NativeControlAction::CombatEscape => {
            if runtime.current_room_id == "league-coliseum"
                && runtime.combat_result_state != "victory"
                && runtime.combat_result_state != "escaped"
            {
                (true, "enabled_turn_combat".to_string())
            } else if runtime.current_room_id != "league-coliseum" {
                (false, "arena_required_before_turn_combat".to_string())
            } else {
                (
                    false,
                    format!("combat_already_{}", runtime.combat_result_state),
                )
            }
        }
        NativeControlAction::CombatUseItem => {
            if runtime.current_room_id != "league-coliseum" {
                (false, "arena_required_before_turn_combat".to_string())
            } else if runtime
                .inventory_items
                .iter()
                .any(|item| item == "small_healing_pill")
                && runtime.combat_result_state != "victory"
                && runtime.combat_result_state != "escaped"
            {
                (true, "enabled_combat_potion".to_string())
            } else {
                (false, "combat_potion_unavailable".to_string())
            }
        }
        NativeControlAction::OpenBag => (true, "bag_available".to_string()),
        NativeControlAction::LootDrop => {
            if runtime.combat_result_state == "victory"
                && runtime
                    .dropped_items
                    .iter()
                    .any(|item| item == "bandit_sash")
            {
                (true, "enabled_after_victory_drop".to_string())
            } else if runtime.combat_result_state != "victory" {
                (false, "victory_required_before_loot".to_string())
            } else {
                (false, "no_unclaimed_drop".to_string())
            }
        }
        NativeControlAction::EquipItem { item_id } => {
            if runtime.inventory_items.iter().any(|item| item == item_id) {
                (true, format!("enabled_inventory_item:{item_id}"))
            } else if runtime.equipped_items.iter().any(|item| item == item_id) {
                (false, format!("item_already_equipped:{item_id}"))
            } else {
                (false, format!("item_not_in_bag:{item_id}"))
            }
        }
        NativeControlAction::EquipBuildTitle { title_id } => {
            let Some(stat_id) = build_branch_mastery_title_stat_for_id(title_id) else {
                return (false, format!("unknown_build_title:{title_id}"));
            };
            if !runtime_has_build_title_id(runtime, title_id) {
                (false, format!("build_title_locked:{title_id}"))
            } else if runtime.active_build_title_id.as_deref() == Some(title_id.as_str()) {
                (false, format!("build_title_already_active:{title_id}"))
            } else {
                (
                    true,
                    format!("enabled_build_title_equip:{stat_id}:{title_id}"),
                )
            }
        }
        NativeControlAction::AcceptTitleRouteRecommendation => {
            active_build_title_route_accept_availability(runtime)
        }
        NativeControlAction::AllocateStat { stat_id } => {
            if !valid_growth_stat_id(stat_id) {
                (false, format!("invalid_stat:{stat_id}"))
            } else if runtime
                .allocated_stat_points
                .iter()
                .any(|allocated| allocated == stat_id)
            {
                (false, format!("stat_already_allocated:{stat_id}"))
            } else if runtime.growth_level < 2 {
                (false, "growth_level_required".to_string())
            } else if runtime.growth_stat_points == 0 {
                (false, "stat_point_required".to_string())
            } else if runtime.pending_stat_allocation.as_deref() == Some(stat_id.as_str()) {
                (false, format!("stat_confirmation_pending:{stat_id}"))
            } else if runtime.pending_stat_allocation.is_some() {
                (true, format!("enabled_stat_preview_switch:{stat_id}"))
            } else {
                (true, format!("enabled_stat_preview:{stat_id}"))
            }
        }
        NativeControlAction::ConfirmStatAllocation => {
            if let Some(stat_id) = runtime.pending_stat_allocation.as_deref() {
                if runtime.growth_stat_points == 0 {
                    (false, "stat_point_required".to_string())
                } else if !valid_growth_stat_id(stat_id) {
                    (false, format!("invalid_stat:{stat_id}"))
                } else if runtime
                    .allocated_stat_points
                    .iter()
                    .any(|allocated| allocated == stat_id)
                {
                    (false, format!("stat_already_allocated:{stat_id}"))
                } else {
                    (true, format!("enabled_stat_confirm:{stat_id}"))
                }
            } else {
                (false, "stat_confirmation_missing".to_string())
            }
        }
        NativeControlAction::CancelStatAllocation => {
            if let Some(stat_id) = runtime.pending_stat_allocation.as_deref() {
                (true, format!("enabled_stat_cancel:{stat_id}"))
            } else {
                (false, "stat_confirmation_missing".to_string())
            }
        }
        NativeControlAction::SaveSlot => {
            if runtime.input_feedback_history.is_empty() {
                (
                    false,
                    "session_checkpoint_requires_input_history".to_string(),
                )
            } else {
                (true, "enabled_session_checkpoint".to_string())
            }
        }
        NativeControlAction::LoadSlot => {
            let slot_path = native_action_session_save_slot_path();
            if Path::new(&slot_path).exists() {
                (true, "enabled_session_slot_found".to_string())
            } else {
                (false, "session_slot_missing".to_string())
            }
        }
        NativeControlAction::SaveSlotNamed { slot_id } => {
            let slot_id = normalize_session_slot_id(slot_id);
            if runtime.input_feedback_history.is_empty() {
                (
                    false,
                    format!("session_checkpoint_requires_input_history:{slot_id}"),
                )
            } else {
                (true, format!("enabled_session_checkpoint:{slot_id}"))
            }
        }
        NativeControlAction::LoadSlotNamed { slot_id } => {
            let slot_id = normalize_session_slot_id(slot_id);
            let slot_path = native_action_session_slot_path(&slot_id);
            if Path::new(&slot_path).exists() {
                (true, format!("enabled_session_slot_found:{slot_id}"))
            } else {
                (false, format!("session_slot_missing:{slot_id}"))
            }
        }
        NativeControlAction::SelectSlot { slot_id } => {
            let slot_id = normalize_session_slot_id(slot_id);
            (true, format!("enabled_select_slot:{slot_id}"))
        }
        NativeControlAction::SaveSelectedSlot => {
            let slot_id = normalize_session_slot_id(&runtime.session_selected_slot_id);
            if runtime.input_feedback_history.is_empty() {
                (
                    false,
                    format!("session_checkpoint_requires_input_history:{slot_id}"),
                )
            } else if runtime.session_overwrite_pending_slot_id.as_deref() == Some(slot_id.as_str())
            {
                (false, format!("overwrite_confirmation_pending:{slot_id}"))
            } else if Path::new(&native_action_session_slot_path(&slot_id)).exists() {
                (true, format!("enabled_overwrite_prompt:{slot_id}"))
            } else {
                (true, format!("enabled_save_selected_slot:{slot_id}"))
            }
        }
        NativeControlAction::LoadSelectedSlot => {
            let slot_id = normalize_session_slot_id(&runtime.session_selected_slot_id);
            let slot_path = native_action_session_slot_path(&slot_id);
            if Path::new(&slot_path).exists() {
                (true, format!("enabled_session_slot_found:{slot_id}"))
            } else {
                (false, format!("session_slot_missing:{slot_id}"))
            }
        }
        NativeControlAction::ConfirmOverwriteSlot => {
            if let Some(slot_id) = runtime.session_overwrite_pending_slot_id.as_deref() {
                (
                    true,
                    format!(
                        "enabled_confirm_overwrite:{}",
                        normalize_session_slot_id(slot_id)
                    ),
                )
            } else {
                (false, "overwrite_confirmation_missing".to_string())
            }
        }
        NativeControlAction::CancelOverwriteSlot => {
            if let Some(slot_id) = runtime.session_overwrite_pending_slot_id.as_deref() {
                (
                    true,
                    format!(
                        "enabled_cancel_overwrite:{}",
                        normalize_session_slot_id(slot_id)
                    ),
                )
            } else {
                (false, "overwrite_confirmation_missing".to_string())
            }
        }
        NativeControlAction::ContinueAfterLoad => {
            unreachable!("handled before general availability")
        }
        NativeControlAction::PauseMenu | NativeControlAction::ResumeFromPause => {
            unreachable!("handled before general availability")
        }
        NativeControlAction::OpenSettingsMenu
        | NativeControlAction::CloseSettingsMenu
        | NativeControlAction::ToggleLowMotion
        | NativeControlAction::VolumeDown
        | NativeControlAction::VolumeUp
        | NativeControlAction::CycleInputMode
        | NativeControlAction::OpenTitleMenu
        | NativeControlAction::NewGameFromTitle
        | NativeControlAction::LoadFromTitle
        | NativeControlAction::ContinueFromTitle
        | NativeControlAction::RegisterAccountFromTitle
        | NativeControlAction::LoginAccountFromTitle
        | NativeControlAction::ContinueAccountFromTitle
        | NativeControlAction::CycleCharacterName
        | NativeControlAction::CycleCharacterArchetype
        | NativeControlAction::ConfirmCharacterCreate
        | NativeControlAction::BackToTitleFromCreate => {
            unreachable!("handled before general availability")
        }
    }
}

