pub fn apply_native_control_action(
    world: &mut WorldState,
    character: &mut WorldTrillionniumCharacter,
    gameplay_log: &mut NativeGameplayLog,
    actor_id: &str,
    action: NativeControlAction,
) -> Option<WorldApiCommandResponse> {
    match action {
        NativeControlAction::Move { direction } => {
            let label = format!("move:{direction}");
            let response = apply_native_intent(
                world,
                WorldCommand::Move {
                    actor_id: actor_id.to_string(),
                    direction,
                },
            );
            update_log_from_world_response(gameplay_log, label, &response);
            Some(response)
        }
        NativeControlAction::Talk => {
            let npc_id = local_npc_for_actor(world, actor_id)
                .map(|npc| npc.id.clone())
                .unwrap_or_else(|| "npc-street-compass-sifu".to_string());
            let response = apply_native_intent(
                world,
                WorldCommand::TalkNpc {
                    actor_id: actor_id.to_string(),
                    npc_id,
                },
            );
            update_log_from_world_response(gameplay_log, "talk:npc".to_string(), &response);
            Some(response)
        }
        NativeControlAction::Train => {
            let npc_id = local_npc_for_actor(world, actor_id)
                .map(|npc| npc.id.clone())
                .unwrap_or_else(|| "npc-street-compass-sifu".to_string());
            let response = apply_native_intent(
                world,
                WorldCommand::TrainSkill {
                    actor_id: actor_id.to_string(),
                    npc_id: npc_id.clone(),
                    skill_id: "basic_unarmed".to_string(),
                },
            );
            update_log_from_world_response(
                gameplay_log,
                "train:basic_unarmed".to_string(),
                &response,
            );
            if response.decision.accepted {
                let outcome = apply_tactics_command(
                    character,
                    WorldTacticsCommandRequest {
                        command: "train_skill".to_string(),
                        skill_id: Some("basic_unarmed".to_string()),
                        npc_id: Some(npc_id),
                        ..default()
                    },
                    native_now_epoch(),
                );
                update_log_from_tactics_outcome(gameplay_log, "train:basic_unarmed", outcome);
            }
            Some(response)
        }
        NativeControlAction::Fight => {
            let outcome = apply_tactics_command(
                character,
                WorldTacticsCommandRequest {
                    command: "attack".to_string(),
                    skill_id: Some("basic_unarmed".to_string()),
                    target_tile: Some("F5".to_string()),
                    ..default()
                },
                native_now_epoch(),
            );
            update_log_from_tactics_outcome(gameplay_log, "fight:F5", outcome);
            None
        }
        NativeControlAction::CompleteTask => {
            let task_id = local_task_for_actor(world, actor_id)
                .map(|task| task.id.clone())
                .or_else(|| world.tasks.first().map(|task| task.id.clone()))
                .unwrap_or_else(|| "task-fixture-first-route".to_string());
            let response = apply_native_intent(
                world,
                WorldCommand::CompleteTask {
                    actor_id: actor_id.to_string(),
                    task_id,
                },
            );
            update_log_from_world_response(gameplay_log, "complete:task".to_string(), &response);
            Some(response)
        }
        NativeControlAction::Equip => {
            let outcome = apply_tactics_command(
                character,
                WorldTacticsCommandRequest {
                    command: "equip_item".to_string(),
                    item_id: Some("route-guard-staff".to_string()),
                    target_slot: Some("weapon".to_string()),
                    ..default()
                },
                native_now_epoch(),
            );
            update_log_from_tactics_outcome(gameplay_log, "equip:route-guard-staff", outcome);
            None
        }
        NativeControlAction::EnterRoom { room_id } => {
            if let Some(direction) = direction_to_room(world, actor_id, &room_id) {
                let label = format!("room:{room_id}");
                let response = apply_native_intent(
                    world,
                    WorldCommand::Move {
                        actor_id: actor_id.to_string(),
                        direction,
                    },
                );
                update_log_from_world_response(gameplay_log, label, &response);
                Some(response)
            } else {
                record_runtime_only_log(
                    gameplay_log,
                    format!("room:{room_id}"),
                    "room_transition_not_adjacent".to_string(),
                    Some("rust_world_edge_required".to_string()),
                );
                None
            }
        }
        NativeControlAction::InteractNpc { npc_id } => {
            let response = apply_native_intent(
                world,
                WorldCommand::TalkNpc {
                    actor_id: actor_id.to_string(),
                    npc_id: npc_id.clone(),
                },
            );
            update_log_from_world_response(gameplay_log, format!("talk:{npc_id}"), &response);
            let outcome = apply_tactics_command(
                character,
                WorldTacticsCommandRequest {
                    command: "talk_npc".to_string(),
                    npc_id: Some(npc_id),
                    ..default()
                },
                native_now_epoch(),
            );
            update_log_from_tactics_outcome(gameplay_log, "talk_npc:room", outcome);
            Some(response)
        }
        NativeControlAction::StartTask { task_id } => {
            let outcome = apply_tactics_command(
                character,
                WorldTacticsCommandRequest {
                    command: "offer_task".to_string(),
                    npc_id: local_npc_for_actor(world, actor_id).map(|npc| npc.id.clone()),
                    item_id: Some(task_id.clone()),
                    ..default()
                },
                native_now_epoch(),
            );
            update_log_from_tactics_outcome(
                gameplay_log,
                &format!("start_task:{task_id}"),
                outcome,
            );
            None
        }
        NativeControlAction::CombatAttack => {
            let outcome = apply_tactics_command(
                character,
                WorldTacticsCommandRequest {
                    command: "attack".to_string(),
                    skill_id: Some("basic_unarmed".to_string()),
                    target_tile: Some("F5".to_string()),
                    ..default()
                },
                native_now_epoch(),
            );
            update_log_from_tactics_outcome(gameplay_log, "combat:attack", outcome);
            None
        }
        NativeControlAction::CombatDefend => {
            record_runtime_only_log(
                gameplay_log,
                "combat:defend".to_string(),
                "guard_stance_reduces_next_hit".to_string(),
                None,
            );
            None
        }
        NativeControlAction::CombatUseItem => {
            record_runtime_only_log(
                gameplay_log,
                "combat:potion".to_string(),
                "small_healing_pill_used".to_string(),
                None,
            );
            None
        }
        NativeControlAction::CombatEscape => {
            record_runtime_only_log(
                gameplay_log,
                "combat:escape".to_string(),
                "escape_path_sampled".to_string(),
                None,
            );
            None
        }
        NativeControlAction::OpenBag => {
            record_runtime_only_log(
                gameplay_log,
                "bag:open".to_string(),
                "bag_opened".to_string(),
                None,
            );
            None
        }
        NativeControlAction::LootDrop => {
            record_runtime_only_log(
                gameplay_log,
                "loot:drop".to_string(),
                "victory_drop_collected".to_string(),
                None,
            );
            None
        }
        NativeControlAction::EquipItem { item_id } => {
            record_runtime_only_log(
                gameplay_log,
                format!("equip_item:{item_id}"),
                "inventory_item_equipped".to_string(),
                None,
            );
            None
        }
        NativeControlAction::EquipBuildTitle { title_id } => {
            record_runtime_only_log(
                gameplay_log,
                format!("equip_title:{title_id}"),
                "build_title_equipped".to_string(),
                None,
            );
            None
        }
        NativeControlAction::AcceptTitleRouteRecommendation => {
            record_runtime_only_log(
                gameplay_log,
                "title:route".to_string(),
                "active_title_route_accepted".to_string(),
                None,
            );
            None
        }
        NativeControlAction::AllocateStat { stat_id } => {
            record_runtime_only_log(
                gameplay_log,
                format!("stat:{stat_id}"),
                "stat_preview_selected".to_string(),
                None,
            );
            None
        }
        NativeControlAction::ConfirmStatAllocation => {
            record_runtime_only_log(
                gameplay_log,
                "stat:confirm".to_string(),
                "stat_point_allocated".to_string(),
                None,
            );
            None
        }
        NativeControlAction::CancelStatAllocation => {
            record_runtime_only_log(
                gameplay_log,
                "stat:cancel".to_string(),
                "stat_preview_cancelled".to_string(),
                None,
            );
            None
        }
        NativeControlAction::SaveSlot
        | NativeControlAction::LoadSlot
        | NativeControlAction::SaveSlotNamed { .. }
        | NativeControlAction::LoadSlotNamed { .. }
        | NativeControlAction::SelectSlot { .. }
        | NativeControlAction::SaveSelectedSlot
        | NativeControlAction::LoadSelectedSlot
        | NativeControlAction::ConfirmOverwriteSlot
        | NativeControlAction::CancelOverwriteSlot
        | NativeControlAction::ContinueAfterLoad
        | NativeControlAction::PauseMenu
        | NativeControlAction::ResumeFromPause
        | NativeControlAction::OpenSettingsMenu
        | NativeControlAction::CloseSettingsMenu
        | NativeControlAction::ToggleLowMotion
        | NativeControlAction::VolumeDown
        | NativeControlAction::VolumeUp
        | NativeControlAction::CycleInputMode
        | NativeControlAction::OpenTitleMenu
        | NativeControlAction::NewGameFromTitle
        | NativeControlAction::LoadFromTitle
        | NativeControlAction::ContinueFromTitle
        | NativeControlAction::RegisterAccountFromTitle
        | NativeControlAction::LoginAccountFromTitle
        | NativeControlAction::ContinueAccountFromTitle
        | NativeControlAction::CycleCharacterName
        | NativeControlAction::CycleCharacterArchetype
        | NativeControlAction::ConfirmCharacterCreate
        | NativeControlAction::BackToTitleFromCreate => None,
    }
}

fn direction_to_room(world: &WorldState, actor_id: &str, room_id: &str) -> Option<String> {
    let current_node_id = player_node_id(world, actor_id)?;
    world
        .edges
        .iter()
        .find(|edge| edge.from == current_node_id && edge.to == room_id)
        .map(|edge| edge.direction.clone())
}

fn record_runtime_only_log(
    gameplay_log: &mut NativeGameplayLog,
    action: String,
    result: String,
    rejection: Option<String>,
) {
    gameplay_log.turn += 1;
    gameplay_log.last_action = action;
    gameplay_log.last_result = result;
    gameplay_log.last_rejection = rejection;
}

fn apply_active_build_title_route_accept(
    world: &mut WorldState,
    character: &mut WorldTrillionniumCharacter,
    gameplay_log: &mut NativeGameplayLog,
    first_playable: &mut NativeFirstPlayableRuntime,
    actor_id: &str,
) -> Option<WorldApiCommandResponse> {
    let Some((_, stat_id, effect_id, task_id)) =
        active_build_title_route_recommendation_parts(first_playable)
    else {
        record_runtime_only_log(
            gameplay_log,
            "title:route".to_string(),
            "title_route_recommendation_missing".to_string(),
            Some("active_title_required".to_string()),
        );
        push_feedback_event(first_playable, "Title route blocked: active title required");
        refresh_contextual_action_runtime(first_playable);
        return None;
    };
    let stat_id = stat_id.to_string();
    let effect_id = effect_id.to_string();
    let task_id = task_id.to_string();
    apply_build_title_route_recommendation(first_playable, &stat_id, &effect_id);
    if first_playable.current_room_id == first_playable.route_director_target_room_id {
        let start_action = NativeControlAction::StartTask {
            task_id: task_id.clone(),
        };
        let response = apply_native_control_action(
            world,
            character,
            gameplay_log,
            actor_id,
            start_action.clone(),
        );
        update_first_playable_runtime(
            first_playable,
            &start_action,
            response.as_ref(),
            character,
            world,
            actor_id,
        );
        push_history(
            &mut first_playable.route_director_history,
            &format!("active_title_route_accept:{stat_id}:{task_id}:start_task"),
        );
        push_feedback_event(
            first_playable,
            &format!(
                "Title route accepted: {} started",
                build_branch_followup_task_label(&task_id)
            ),
        );
        refresh_contextual_action_runtime(first_playable);
        return response;
    }
    let Some(next_room_id) = first_playable.route_director_next_room_id.clone() else {
        record_runtime_only_log(
            gameplay_log,
            "title:route".to_string(),
            "title_route_waiting".to_string(),
            Some(task_id.clone()),
        );
        push_history(
            &mut first_playable.blocked_action_history,
            &format!("TITLE:ROUTE:title_route_waiting:{task_id}"),
        );
        push_feedback_event(
            first_playable,
            &format!("Title route waiting: no next step for {task_id}"),
        );
        refresh_contextual_action_runtime(first_playable);
        return None;
    };
    let enter_action = NativeControlAction::EnterRoom {
        room_id: next_room_id.clone(),
    };
    if build_mastery_room_override(first_playable, &next_room_id)
        && !world
            .edges
            .iter()
            .any(|edge| edge.from == first_playable.current_room_id && edge.to == next_room_id)
    {
        world.edges.push(WorldEdge {
            from: first_playable.current_room_id.clone(),
            to: next_room_id.clone(),
            direction: format!("mastery_shortcut_to_{next_room_id}"),
        });
    }
    let response = apply_native_control_action(
        world,
        character,
        gameplay_log,
        actor_id,
        enter_action.clone(),
    );
    update_first_playable_runtime(
        first_playable,
        &enter_action,
        response.as_ref(),
        character,
        world,
        actor_id,
    );
    push_history(
        &mut first_playable.route_director_history,
        &format!("active_title_route_accept:{stat_id}:{task_id}:move:{next_room_id}"),
    );
    push_feedback_event(
        first_playable,
        &format!(
            "Title route accepted: {} moved to {}",
            build_branch_followup_task_label(&task_id),
            node_scene_label(&next_room_id)
        ),
    );
    refresh_contextual_action_runtime(first_playable);
    response
}

pub fn apply_native_first_playable_action(
    world: &mut WorldState,
    character: &mut WorldTrillionniumCharacter,
    gameplay_log: &mut NativeGameplayLog,
    first_playable: &mut NativeFirstPlayableRuntime,
    actor_id: &str,
    action: NativeControlAction,
) -> Option<WorldApiCommandResponse> {
    match action {
        NativeControlAction::OpenTitleMenu => {
            open_title_menu(first_playable);
            gameplay_log.turn += 1;
            gameplay_log.last_action = "title:open".to_string();
            gameplay_log.last_result = "title_menu_opened".to_string();
            gameplay_log.last_rejection = None;
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::NewGameFromTitle => {
            open_character_create(first_playable);
            gameplay_log.turn += 1;
            gameplay_log.last_action = "title:new_game".to_string();
            gameplay_log.last_result = "character_create_opened".to_string();
            gameplay_log.last_rejection = None;
            push_history(&mut first_playable.session_title_history, "title_new_game");
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::CycleCharacterName => {
            cycle_character_name(first_playable);
            gameplay_log.turn += 1;
            gameplay_log.last_action = "character:create:name".to_string();
            gameplay_log.last_result = format!(
                "character_name:{}",
                first_playable.session_character_create_name
            );
            gameplay_log.last_rejection = None;
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::CycleCharacterArchetype => {
            cycle_character_archetype(first_playable);
            gameplay_log.turn += 1;
            gameplay_log.last_action = "character:create:archetype".to_string();
            gameplay_log.last_result = format!(
                "character_archetype:{}",
                first_playable.session_character_create_archetype
            );
            gameplay_log.last_rejection = None;
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::BackToTitleFromCreate => {
            close_character_create(first_playable, "back_to_title");
            open_title_menu(first_playable);
            gameplay_log.turn += 1;
            gameplay_log.last_action = "character:create:back".to_string();
            gameplay_log.last_result = "title_menu_opened".to_string();
            gameplay_log.last_rejection = None;
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::RegisterAccountFromTitle
        | NativeControlAction::LoginAccountFromTitle
        | NativeControlAction::ContinueAccountFromTitle => {
            let decision = apply_title_account_flow(first_playable, actor_id, &action);
            if decision.accepted {
                character.display_name = decision.profile.display_name.clone();
                character.ensure_defaults(native_now_epoch());
                push_history(
                    &mut first_playable.session_account_history,
                    "account_profile_bound_to_character_identity",
                );
            }
            gameplay_log.turn += 1;
            gameplay_log.last_action = format!("account:{}", decision.action);
            gameplay_log.last_result = decision.reason.clone();
            gameplay_log.last_rejection = (!decision.accepted).then(|| decision.reason.clone());
            push_progression_checkpoint(
                first_playable,
                &format!("account_title_flow:{}", decision.action),
            );
            if decision.accepted {
                push_progression_checkpoint(first_playable, "account_profile_bound_to_character");
            }
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::ConfirmCharacterCreate => {
            let chosen_name = first_playable.session_character_create_name.clone();
            let chosen_archetype = first_playable.session_character_create_archetype.clone();
            let next_turn = gameplay_log.turn + 1;
            *world = native_bevy_playable_fixture();
            *character = character_for_creation(actor_id, &chosen_name, &chosen_archetype);
            *gameplay_log = NativeGameplayLog {
                turn: next_turn,
                last_action: "character:create:confirm".to_string(),
                last_result: format!("new_character:{chosen_name}:{chosen_archetype}"),
                last_rejection: None,
            };
            *first_playable = NativeFirstPlayableRuntime::default();
            first_playable.session_character_create_name = chosen_name.clone();
            first_playable.session_character_create_archetype = chosen_archetype.clone();
            close_character_create(first_playable, "new_game_started");
            first_playable.session_title_boot_state = "new_game_started".to_string();
            push_history(
                &mut first_playable.session_character_create_history,
                &format!("confirmed:{chosen_name}:{chosen_archetype}"),
            );
            push_progression_checkpoint(first_playable, "character_created_from_title");
            push_feedback_event(
                first_playable,
                &format!("New character created: {chosen_name} / {chosen_archetype}"),
            );
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::AcceptTitleRouteRecommendation => {
            return apply_active_build_title_route_accept(
                world,
                character,
                gameplay_log,
                first_playable,
                actor_id,
            );
        }
        NativeControlAction::LoadFromTitle | NativeControlAction::ContinueFromTitle => {
            let selected_slot_id =
                normalize_session_slot_id(&first_playable.session_selected_slot_id);
            let slot_path = native_action_session_slot_path(&selected_slot_id);
            let title_action_is_continue = matches!(action, NativeControlAction::ContinueFromTitle);
            let slot_result = read_native_playable_snapshot_slot(&slot_path);
            match slot_result {
                Ok(snapshot) => {
                    let (
                        restored_world,
                        restored_character,
                        mut restored_log,
                        mut restored_first_playable,
                    ) = native_restore_playable_save_snapshot(snapshot);
                    restored_first_playable.session_selected_slot_id = selected_slot_id.clone();
                    restored_first_playable.session_overwrite_pending_slot_id = None;
                    restored_first_playable.session_title_last_slot_id =
                        Some(selected_slot_id.clone());
                    push_progression_checkpoint(
                        &mut restored_first_playable,
                        "session_snapshot_restored",
                    );
                    push_progression_checkpoint(
                        &mut restored_first_playable,
                        &format!("title_slot_{selected_slot_id}_restored"),
                    );
                    restored_log.turn += 1;
                    restored_log.last_action = if title_action_is_continue {
                        format!("title:continue:{selected_slot_id}")
                    } else {
                        format!("title:load:{selected_slot_id}")
                    };
                    restored_log.last_result = if title_action_is_continue {
                        format!("title_slot_{selected_slot_id}_continued")
                    } else {
                        format!("title_slot_{selected_slot_id}_loaded")
                    };
                    restored_log.last_rejection = None;
                    let title_history_entry = if title_action_is_continue {
                        format!("title_continue_slot:{selected_slot_id}")
                    } else {
                        format!("title_load_slot:{selected_slot_id}")
                    };
                    push_history(
                        &mut restored_first_playable.session_title_history,
                        &title_history_entry,
                    );
                    let title_feedback = if title_action_is_continue {
                        format!("Title continue loaded slot {selected_slot_id}")
                    } else {
                        format!("Title load restored slot {selected_slot_id}")
                    };
                    push_feedback_event(&mut restored_first_playable, &title_feedback);
                    mark_session_resume_overlay(&mut restored_first_playable, &selected_slot_id);
                    refresh_contextual_action_runtime(&mut restored_first_playable);
                    *world = restored_world;
                    *character = restored_character;
                    *gameplay_log = restored_log;
                    *first_playable = restored_first_playable;
                }
                Err(error) => {
                    gameplay_log.turn += 1;
                    gameplay_log.last_action = if title_action_is_continue {
                        format!("title:continue:{selected_slot_id}")
                    } else {
                        format!("title:load:{selected_slot_id}")
                    };
                    gameplay_log.last_result = if title_action_is_continue {
                        format!("title_slot_{selected_slot_id}_continue_failed")
                    } else {
                        format!("title_slot_{selected_slot_id}_load_failed")
                    };
                    gameplay_log.last_rejection = Some(error.to_string());
                    push_feedback_event(
                        first_playable,
                        &format!("Title slot {selected_slot_id} load failed: {error}"),
                    );
                    refresh_contextual_action_runtime(first_playable);
                }
            }
            return None;
        }
        NativeControlAction::PauseMenu => {
            open_pause_menu(first_playable);
            gameplay_log.turn += 1;
            gameplay_log.last_action = "pause:menu".to_string();
            gameplay_log.last_result = "pause_menu_opened".to_string();
            gameplay_log.last_rejection = None;
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::ResumeFromPause => {
            close_pause_menu(first_playable);
            gameplay_log.turn += 1;
            gameplay_log.last_action = "resume:pause_menu".to_string();
            gameplay_log.last_result = "pause_menu_closed".to_string();
            gameplay_log.last_rejection = None;
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::OpenSettingsMenu => {
            open_settings_menu(first_playable);
            gameplay_log.turn += 1;
            gameplay_log.last_action = "settings:open".to_string();
            gameplay_log.last_result = "settings_menu_opened".to_string();
            gameplay_log.last_rejection = None;
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::CloseSettingsMenu => {
            close_settings_menu(first_playable);
            gameplay_log.turn += 1;
            gameplay_log.last_action = "settings:back".to_string();
            gameplay_log.last_result = "settings_menu_closed".to_string();
            gameplay_log.last_rejection = None;
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::ToggleLowMotion => {
            toggle_low_motion(first_playable);
            gameplay_log.turn += 1;
            gameplay_log.last_action = "settings:low_motion".to_string();
            gameplay_log.last_result = format!(
                "low_motion:{}",
                if first_playable.session_settings_low_motion_enabled {
                    "on"
                } else {
                    "off"
                }
            );
            gameplay_log.last_rejection = None;
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::VolumeDown => {
            adjust_volume(first_playable, -1);
            gameplay_log.turn += 1;
            gameplay_log.last_action = "settings:volume_down".to_string();
            gameplay_log.last_result =
                format!("volume:{}", first_playable.session_settings_volume_level);
            gameplay_log.last_rejection = None;
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::VolumeUp => {
            adjust_volume(first_playable, 1);
            gameplay_log.turn += 1;
            gameplay_log.last_action = "settings:volume_up".to_string();
            gameplay_log.last_result =
                format!("volume:{}", first_playable.session_settings_volume_level);
            gameplay_log.last_rejection = None;
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::CycleInputMode => {
            cycle_input_mode(first_playable);
            gameplay_log.turn += 1;
            gameplay_log.last_action = "settings:input_mode".to_string();
            gameplay_log.last_result =
                format!("input_mode:{}", first_playable.session_settings_input_mode);
            gameplay_log.last_rejection = None;
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::ContinueAfterLoad => {
            let slot_id = first_playable
                .session_resume_source_slot_id
                .clone()
                .unwrap_or_else(|| "unknown".to_string());
            clear_session_resume_overlay(first_playable);
            gameplay_log.turn += 1;
            gameplay_log.last_action = format!("continue:session:{slot_id}");
            gameplay_log.last_result = "session_resume_continued".to_string();
            gameplay_log.last_rejection = None;
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::SaveSlot => {
            let slot_path = native_action_session_save_slot_path();
            let snapshot = native_playable_save_snapshot(
                world,
                character,
                gameplay_log,
                first_playable,
                actor_id,
            );
            let slot_result = write_native_playable_snapshot_slot(&slot_path, &snapshot);
            gameplay_log.turn += 1;
            gameplay_log.last_action = "save:slot".to_string();
            gameplay_log.last_rejection = None;
            match slot_result {
                Ok(bytes) => {
                    gameplay_log.last_result = format!("session_slot_saved:{bytes}");
                    push_progression_checkpoint(first_playable, "session_slot_saved");
                    push_feedback_event(first_playable, &format!("Session saved: {bytes} bytes"));
                }
                Err(error) => {
                    gameplay_log.last_result = "session_slot_save_failed".to_string();
                    gameplay_log.last_rejection = Some(error.to_string());
                    push_feedback_event(first_playable, &format!("Session save failed: {error}"));
                }
            }
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::LoadSlot => {
            let slot_path = native_action_session_save_slot_path();
            let slot_result = read_native_playable_snapshot_slot(&slot_path);
            match slot_result {
                Ok(snapshot) => {
                    let (
                        restored_world,
                        restored_character,
                        mut restored_log,
                        mut restored_first_playable,
                    ) = native_restore_playable_save_snapshot(snapshot);
                    push_progression_checkpoint(
                        &mut restored_first_playable,
                        "session_snapshot_restored",
                    );
                    restored_log.turn += 1;
                    restored_log.last_action = "load:slot".to_string();
                    restored_log.last_result = "session_slot_loaded".to_string();
                    restored_log.last_rejection = None;
                    push_feedback_event(
                        &mut restored_first_playable,
                        "Session loaded: slot restored",
                    );
                    mark_session_resume_overlay(&mut restored_first_playable, "SLOT");
                    refresh_contextual_action_runtime(&mut restored_first_playable);
                    *world = restored_world;
                    *character = restored_character;
                    *gameplay_log = restored_log;
                    *first_playable = restored_first_playable;
                }
                Err(error) => {
                    gameplay_log.turn += 1;
                    gameplay_log.last_action = "load:slot".to_string();
                    gameplay_log.last_result = "session_slot_load_failed".to_string();
                    gameplay_log.last_rejection = Some(error.to_string());
                    push_feedback_event(first_playable, &format!("Session load failed: {error}"));
                    refresh_contextual_action_runtime(first_playable);
                }
            }
            return None;
        }
        NativeControlAction::SaveSlotNamed { slot_id } => {
            let slot_id = normalize_session_slot_id(&slot_id);
            let slot_path = native_action_session_slot_path(&slot_id);
            let snapshot = native_playable_save_snapshot(
                world,
                character,
                gameplay_log,
                first_playable,
                actor_id,
            );
            let slot_result = write_native_playable_snapshot_slot(&slot_path, &snapshot);
            gameplay_log.turn += 1;
            gameplay_log.last_action = format!("save:slot:{slot_id}");
            gameplay_log.last_rejection = None;
            match slot_result {
                Ok(bytes) => {
                    gameplay_log.last_result = format!("session_slot_{slot_id}_saved:{bytes}");
                    push_progression_checkpoint(
                        first_playable,
                        &format!("session_slot_{slot_id}_saved"),
                    );
                    push_feedback_event(
                        first_playable,
                        &format!("Session slot {slot_id} saved: {bytes} bytes"),
                    );
                }
                Err(error) => {
                    gameplay_log.last_result = format!("session_slot_{slot_id}_save_failed");
                    gameplay_log.last_rejection = Some(error.to_string());
                    push_feedback_event(
                        first_playable,
                        &format!("Session slot {slot_id} save failed: {error}"),
                    );
                }
            }
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::LoadSlotNamed { slot_id } => {
            let slot_id = normalize_session_slot_id(&slot_id);
            let slot_path = native_action_session_slot_path(&slot_id);
            let slot_result = read_native_playable_snapshot_slot(&slot_path);
            match slot_result {
                Ok(snapshot) => {
                    let (
                        restored_world,
                        restored_character,
                        mut restored_log,
                        mut restored_first_playable,
                    ) = native_restore_playable_save_snapshot(snapshot);
                    push_progression_checkpoint(
                        &mut restored_first_playable,
                        "session_snapshot_restored",
                    );
                    push_progression_checkpoint(
                        &mut restored_first_playable,
                        &format!("session_slot_{slot_id}_restored"),
                    );
                    restored_log.turn += 1;
                    restored_log.last_action = format!("load:slot:{slot_id}");
                    restored_log.last_result = format!("session_slot_{slot_id}_loaded");
                    restored_log.last_rejection = None;
                    push_feedback_event(
                        &mut restored_first_playable,
                        &format!("Session slot {slot_id} loaded: restored"),
                    );
                    mark_session_resume_overlay(&mut restored_first_playable, &slot_id);
                    refresh_contextual_action_runtime(&mut restored_first_playable);
                    *world = restored_world;
                    *character = restored_character;
                    *gameplay_log = restored_log;
                    *first_playable = restored_first_playable;
                }
                Err(error) => {
                    gameplay_log.turn += 1;
                    gameplay_log.last_action = format!("load:slot:{slot_id}");
                    gameplay_log.last_result = format!("session_slot_{slot_id}_load_failed");
                    gameplay_log.last_rejection = Some(error.to_string());
                    push_feedback_event(
                        first_playable,
                        &format!("Session slot {slot_id} load failed: {error}"),
                    );
                    refresh_contextual_action_runtime(first_playable);
                }
            }
            return None;
        }
        NativeControlAction::SelectSlot { slot_id } => {
            let slot_id = normalize_session_slot_id(&slot_id);
            first_playable.session_selected_slot_id = slot_id.clone();
            first_playable.session_overwrite_pending_slot_id = None;
            gameplay_log.turn += 1;
            gameplay_log.last_action = format!("select:slot:{slot_id}");
            gameplay_log.last_result = format!("session_slot_{slot_id}_selected");
            gameplay_log.last_rejection = None;
            push_feedback_event(first_playable, &format!("Session slot {slot_id} selected"));
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::SaveSelectedSlot => {
            let slot_id = normalize_session_slot_id(&first_playable.session_selected_slot_id);
            let slot_path = native_action_session_slot_path(&slot_id);
            gameplay_log.turn += 1;
            gameplay_log.last_action = format!("save:selected:{slot_id}");
            gameplay_log.last_rejection = None;
            if Path::new(&slot_path).exists() {
                first_playable.session_overwrite_pending_slot_id = Some(slot_id.clone());
                gameplay_log.last_result = format!("session_slot_{slot_id}_overwrite_pending");
                push_feedback_event(
                    first_playable,
                    &format!("Confirm overwrite slot {slot_id} before saving"),
                );
                refresh_contextual_action_runtime(first_playable);
                return None;
            }
            first_playable.session_overwrite_pending_slot_id = None;
            let snapshot = native_playable_save_snapshot(
                world,
                character,
                gameplay_log,
                first_playable,
                actor_id,
            );
            match write_native_playable_snapshot_slot(&slot_path, &snapshot) {
                Ok(bytes) => {
                    gameplay_log.last_result =
                        format!("session_slot_{slot_id}_selected_saved:{bytes}");
                    push_progression_checkpoint(
                        first_playable,
                        &format!("session_slot_{slot_id}_selected_saved"),
                    );
                    push_feedback_event(
                        first_playable,
                        &format!("Selected slot {slot_id} saved: {bytes} bytes"),
                    );
                }
                Err(error) => {
                    gameplay_log.last_result =
                        format!("session_slot_{slot_id}_selected_save_failed");
                    gameplay_log.last_rejection = Some(error.to_string());
                    push_feedback_event(
                        first_playable,
                        &format!("Selected slot {slot_id} save failed: {error}"),
                    );
                }
            }
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::ConfirmOverwriteSlot => {
            let slot_id = first_playable
                .session_overwrite_pending_slot_id
                .as_deref()
                .map(normalize_session_slot_id)
                .unwrap_or_else(|| {
                    normalize_session_slot_id(&first_playable.session_selected_slot_id)
                });
            let slot_path = native_action_session_slot_path(&slot_id);
            first_playable.session_selected_slot_id = slot_id.clone();
            first_playable.session_overwrite_pending_slot_id = None;
            gameplay_log.turn += 1;
            gameplay_log.last_action = format!("confirm-overwrite:slot:{slot_id}");
            gameplay_log.last_rejection = None;
            let snapshot = native_playable_save_snapshot(
                world,
                character,
                gameplay_log,
                first_playable,
                actor_id,
            );
            match write_native_playable_snapshot_slot(&slot_path, &snapshot) {
                Ok(bytes) => {
                    gameplay_log.last_result =
                        format!("session_slot_{slot_id}_overwritten:{bytes}");
                    push_progression_checkpoint(
                        first_playable,
                        &format!("session_slot_{slot_id}_overwritten"),
                    );
                    push_feedback_event(
                        first_playable,
                        &format!("Slot {slot_id} overwrite confirmed: {bytes} bytes"),
                    );
                }
                Err(error) => {
                    gameplay_log.last_result = format!("session_slot_{slot_id}_overwrite_failed");
                    gameplay_log.last_rejection = Some(error.to_string());
                    push_feedback_event(
                        first_playable,
                        &format!("Slot {slot_id} overwrite failed: {error}"),
                    );
                }
            }
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::CancelOverwriteSlot => {
            let slot_id = first_playable
                .session_overwrite_pending_slot_id
                .as_deref()
                .map(normalize_session_slot_id)
                .unwrap_or_else(|| {
                    normalize_session_slot_id(&first_playable.session_selected_slot_id)
                });
            first_playable.session_overwrite_pending_slot_id = None;
            gameplay_log.turn += 1;
            gameplay_log.last_action = format!("cancel-overwrite:slot:{slot_id}");
            gameplay_log.last_result = format!("session_slot_{slot_id}_overwrite_cancelled");
            gameplay_log.last_rejection = None;
            push_feedback_event(
                first_playable,
                &format!("Slot {slot_id} overwrite cancelled"),
            );
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::LoadSelectedSlot => {
            let slot_id = normalize_session_slot_id(&first_playable.session_selected_slot_id);
            let slot_path = native_action_session_slot_path(&slot_id);
            let slot_result = read_native_playable_snapshot_slot(&slot_path);
            match slot_result {
                Ok(snapshot) => {
                    let (
                        restored_world,
                        restored_character,
                        mut restored_log,
                        mut restored_first_playable,
                    ) = native_restore_playable_save_snapshot(snapshot);
                    restored_first_playable.session_selected_slot_id = slot_id.clone();
                    restored_first_playable.session_overwrite_pending_slot_id = None;
                    push_progression_checkpoint(
                        &mut restored_first_playable,
                        "session_snapshot_restored",
                    );
                    push_progression_checkpoint(
                        &mut restored_first_playable,
                        &format!("session_selected_slot_{slot_id}_restored"),
                    );
                    restored_log.turn += 1;
                    restored_log.last_action = format!("load:selected:{slot_id}");
                    restored_log.last_result = format!("session_selected_slot_{slot_id}_loaded");
                    restored_log.last_rejection = None;
                    push_feedback_event(
                        &mut restored_first_playable,
                        &format!("Selected slot {slot_id} loaded: restored"),
                    );
                    mark_session_resume_overlay(&mut restored_first_playable, &slot_id);
                    refresh_contextual_action_runtime(&mut restored_first_playable);
                    *world = restored_world;
                    *character = restored_character;
                    *gameplay_log = restored_log;
                    *first_playable = restored_first_playable;
                }
                Err(error) => {
                    gameplay_log.turn += 1;
                    gameplay_log.last_action = format!("load:selected:{slot_id}");
                    gameplay_log.last_result =
                        format!("session_selected_slot_{slot_id}_load_failed");
                    gameplay_log.last_rejection = Some(error.to_string());
                    push_feedback_event(
                        first_playable,
                        &format!("Selected slot {slot_id} load failed: {error}"),
                    );
                    refresh_contextual_action_runtime(first_playable);
                }
            }
            return None;
        }
        _ => {}
    }
    let action_for_runtime = action.clone();
    let response = apply_native_control_action(world, character, gameplay_log, actor_id, action);
    update_first_playable_runtime(
        first_playable,
        &action_for_runtime,
        response.as_ref(),
        character,
        world,
        actor_id,
    );
    response
}

fn update_first_playable_runtime(
    first_playable: &mut NativeFirstPlayableRuntime,
    action: &NativeControlAction,
    response: Option<&WorldApiCommandResponse>,
    character: &mut WorldTrillionniumCharacter,
    world: &WorldState,
    actor_id: &str,
) {
    match action {
        NativeControlAction::Talk => {
            push_completed_step(first_playable, "talk_to_mentor");
            push_completed_step(first_playable, "npc_dialogue_opened");
            first_playable.tutorial_step = "train_with_mentor".to_string();
            first_playable.npc_dialogue_state = "mentor_dialogue_open".to_string();
            first_playable.scene_transition = "dialogue_overlay_opened".to_string();
            first_playable.dialogue_overlay_visible = true;
            first_playable.active_scene_layer = "town_square_outdoor_tilemap".to_string();
            first_playable.tilemap_variant = "outdoor_town".to_string();
            first_playable.npc_behavior_state = "mentor_dialogue_choice_open".to_string();
            first_playable.npc_bubble_text = "Choose TRAIN to enter the practice room".to_string();
            push_history(&mut first_playable.scene_history, "dialogue_overlay_opened");
            push_history(
                &mut first_playable.npc_behavior_history,
                "dialogue_choice_opened",
            );
            push_feedback_event(
                first_playable,
                "Mentor dialogue opened: training route visible",
            );
        }
        NativeControlAction::Train => {
            if character
                .skill_ids
                .iter()
                .any(|skill| skill == "basic_unarmed")
            {
                push_completed_step(first_playable, "train_basic_unarmed");
                push_completed_step(first_playable, "enter_training_room");
                first_playable.xp = first_playable.xp.max(10);
                first_playable.tutorial_step = "travel_to_league_coliseum".to_string();
                first_playable.map_scene = "mentor_training_room_indoor".to_string();
                first_playable.scene_transition = "entered_indoor_training_room".to_string();
                first_playable.npc_dialogue_state = "mentor_training_complete".to_string();
                first_playable.dialogue_overlay_visible = false;
                first_playable.indoor_tilemap_visible = true;
                first_playable.active_scene_layer =
                    "mentor_training_room_indoor_tilemap".to_string();
                first_playable.tilemap_variant = "indoor_training_room".to_string();
                first_playable.npc_behavior_state = "mentor_training_feedback_visible".to_string();
                first_playable.npc_bubble_text =
                    "basic_unarmed learned; take the north road".to_string();
                push_history(
                    &mut first_playable.scene_history,
                    "mentor_training_room_indoor_tilemap",
                );
                push_history(
                    &mut first_playable.npc_behavior_history,
                    "training_feedback_visible",
                );
                push_feedback_event(
                    first_playable,
                    "Training room entered: basic_unarmed +10 XP",
                );
            }
        }
        NativeControlAction::Move { direction } => {
            push_completed_step(first_playable, "walk_grid_step_recorded");
            first_playable.walk_cycle_frame = (first_playable.walk_cycle_frame + 1) % 4;
            first_playable.last_tile_step = format!("step_{direction}");
            first_playable.movement_input_locked = true;
            first_playable.movement_lock_observed = true;
            first_playable.movement_from_tile = if first_playable.indoor_tilemap_visible {
                "mentor_room_exit_tile".to_string()
            } else {
                "town_square_current_tile".to_string()
            };
            first_playable.movement_to_tile = "arena_gate_tile".to_string();
            first_playable.tile_step_progress_percent = 100;
            first_playable.facing_direction = direction.clone();
            first_playable.player_sprite_pose = format!(
                "walk_{}_frame_{}",
                direction, first_playable.walk_cycle_frame
            );
            first_playable.tile_interpolation_samples = vec![
                format!("0:{}", first_playable.movement_from_tile),
                "50:town_road_midpoint".to_string(),
                format!("100:{}", first_playable.movement_to_tile),
            ];
            first_playable.movement_input_locked = false;
            push_history(
                &mut first_playable.scene_history,
                "tile_to_tile_interpolation",
            );
            if player_node_id(world, actor_id).as_deref() == Some("league-coliseum") {
                push_completed_step(first_playable, "arrive_at_first_objective");
                push_completed_step(first_playable, "exit_training_room_to_arena_route");
                update_runtime_room_context(first_playable, "league-coliseum");
                first_playable.tutorial_step = "resolve_first_combat".to_string();
                first_playable.objective_status = "arrived_at_objective".to_string();
                first_playable.map_scene = "arena_outdoor".to_string();
                first_playable.scene_transition = "outdoor_town_to_arena_gate".to_string();
                first_playable.indoor_tilemap_visible = false;
                first_playable.active_scene_layer = "arena_outdoor_tilemap".to_string();
                first_playable.tilemap_variant = "arena_outdoor".to_string();
                first_playable.enemy_behavior_state = "enemy_visible_at_arena".to_string();
                first_playable.enemy_damage_feedback = "waiting_for_first_hit".to_string();
                push_history(&mut first_playable.scene_history, "arena_outdoor_tilemap");
                push_history(
                    &mut first_playable.enemy_behavior_history,
                    "enemy_visible_at_arena",
                );
                push_feedback_event(first_playable, "Grid step complete: arena reached");
            }
        }
        NativeControlAction::Fight => {
            if !character.combat_numerics_state.recent_exchanges.is_empty() {
                push_completed_step(first_playable, "resolve_first_combat");
                push_completed_step(first_playable, "combat_scene_entered");
                push_completed_step(first_playable, "combat_scene_returned");
                first_playable.enemy_hp = character
                    .combat_numerics_state
                    .recent_exchanges
                    .last()
                    .map(|exchange| exchange.defender_hp_after as i32)
                    .unwrap_or(10);
                first_playable.player_hp = character.combat_numerics_state.hp_current as i32;
                first_playable.xp = first_playable.xp.max(25);
                first_playable.tutorial_step = "complete_first_task".to_string();
                first_playable.objective_status = "combat_resolved".to_string();
                first_playable.combat_overlay_visible = true;
                first_playable.combat_overlay_was_visible = true;
                push_history(
                    &mut first_playable.scene_history,
                    "combat_encounter_overlay",
                );
                first_playable.combat_scene_state = "combat_returned_to_map".to_string();
                first_playable.scene_transition = "combat_overlay_return_to_map".to_string();
                first_playable.enemy_behavior_state = "enemy_hit_recovering".to_string();
                first_playable.enemy_damage_feedback =
                    format!("-{} HP", 40 - first_playable.enemy_hp);
                push_history(&mut first_playable.scene_history, "combat_returned_to_map");
                push_history(
                    &mut first_playable.enemy_behavior_history,
                    "enemy_damage_feedback_visible",
                );
                push_history(
                    &mut first_playable.enemy_behavior_history,
                    "enemy_hp_changed",
                );
                push_feedback_event(
                    first_playable,
                    &format!(
                        "Combat hit: enemy HP {}, player HP {}",
                        first_playable.enemy_hp, first_playable.player_hp
                    ),
                );
            }
        }
        NativeControlAction::CompleteTask => {
            if let Some(task_id) =
                active_build_branch_mastery_challenge_task_id(first_playable).map(str::to_string)
            {
                complete_build_branch_mastery_challenge_task(first_playable, &task_id);
            } else if let Some(task_id) =
                active_build_branch_followup_task_id(first_playable).map(str::to_string)
            {
                complete_build_branch_followup_task(first_playable, &task_id);
            } else if let Some(task_id) =
                active_build_branch_task_id(first_playable).map(str::to_string)
            {
                complete_build_branch_task(first_playable, &task_id);
            } else {
                let task_resolution_recorded = response
                    .map(|response| {
                        response.decision.accepted
                            || response.decision.reason
                                == "task_completion_requires_ledger_settlement"
                    })
                    .unwrap_or(false);
                if task_resolution_recorded {
                    push_completed_step(first_playable, "complete_first_task");
                    push_unique_string(
                        &mut first_playable.completed_task_ids,
                        "task-fixture-first-route",
                    );
                    push_progression_checkpoint(
                        first_playable,
                        "complete_task:task-fixture-first-route",
                    );
                    first_playable.reward_claimed = true;
                    let reward_coins = task_completion_coin_reward(first_playable);
                    let reward_xp = task_completion_xp_reward(first_playable);
                    first_playable.coins = first_playable.coins.max(reward_coins);
                    first_playable.xp = first_playable.xp.max(reward_xp);
                    first_playable.reward_settlement_text =
                        reward_settlement_text(first_playable, reward_coins, reward_xp);
                    first_playable.stat_effect_floating_text =
                        first_playable.reward_settlement_text.clone();
                    first_playable.tutorial_step = "equip_reward_and_continue".to_string();
                    first_playable.objective_status = "first_task_reward_ready".to_string();
                    if runtime_has_allocated_stat(first_playable, "craft") {
                        push_history(
                            &mut first_playable.growth_history,
                            "stat_effect:craft:task_reward_bonus",
                        );
                        push_progression_checkpoint(
                            first_playable,
                            "stat_effect:craft:reward_bonus",
                        );
                    }
                    push_feedback_event(
                        first_playable,
                        &format!(
                            "Task cleared: +{reward_coins} coins +{reward_xp} XP and reward ready"
                        ),
                    );
                }
            }
        }
        NativeControlAction::Equip => {
            if !character.equipment_slots.is_empty() {
                push_completed_step(first_playable, "equip_route_guard_staff");
                first_playable.equipment_ready = true;
                first_playable.tutorial_step = "first_playable_loop_complete".to_string();
                first_playable.objective_status = "first_playable_loop_complete".to_string();
                push_feedback_event(first_playable, "Reward equipped: Route Guard Staff ready");
            }
        }
        NativeControlAction::EnterRoom { room_id } => {
            let target_room = if build_mastery_room_override(first_playable, room_id) {
                room_id.clone()
            } else {
                player_node_id(world, actor_id).unwrap_or_else(|| room_id.clone())
            };
            update_runtime_room_context(first_playable, &target_room);
            first_playable.tutorial_step = "explore_multi_room_world".to_string();
            first_playable.objective_status = format!("exploring:{target_room}");
            first_playable.scene_transition = format!("room_transition:{target_room}");
            first_playable.map_scene = room_map_scene(&target_room);
            first_playable.tilemap_variant = room_tilemap_variant(&target_room);
            first_playable.active_scene_layer =
                format!("{}_tilemap", first_playable.tilemap_variant);
            first_playable.indoor_tilemap_visible = scene_pack_room(&target_room)
                .map(|room| room.indoor)
                .unwrap_or(false);
            first_playable.dialogue_overlay_visible = false;
            first_playable.combat_overlay_visible = false;
            push_completed_step(first_playable, "multi_room_transition");
            push_history(
                &mut first_playable.scene_history,
                &format!("room_tilemap:{target_room}"),
            );
            push_history(
                &mut first_playable.multi_room_history,
                &format!("enter_room:{target_room}"),
            );
            push_feedback_event(
                first_playable,
                &format!("Room loaded: {}", node_scene_label(&target_room)),
            );
        }
        NativeControlAction::InteractNpc { npc_id } => {
            push_completed_step(first_playable, "visible_npc_interaction");
            first_playable.npc_dialogue_state = format!("npc_dialogue:{npc_id}");
            first_playable.npc_behavior_state = format!("npc_{npc_id}_talking");
            first_playable.npc_bubble_text = runtime_npc_bubble(npc_id);
            push_history(
                &mut first_playable.npc_behavior_history,
                &format!("npc_dialogue_visible:{npc_id}"),
            );
            push_history(
                &mut first_playable.multi_room_history,
                &format!("interact_npc:{npc_id}"),
            );
            push_feedback_event(
                first_playable,
                &format!("NPC interaction visible: {npc_id}"),
            );
        }
        NativeControlAction::StartTask { task_id } => {
            push_completed_step(first_playable, "multi_room_task_started");
            push_unique_string(&mut first_playable.active_task_ids, task_id);
            push_progression_checkpoint(first_playable, &format!("start_task:{task_id}"));
            first_playable.objective_status = format!("task_active:{task_id}");
            update_route_director_runtime(first_playable, task_id);
            push_history(
                &mut first_playable.multi_room_history,
                &format!("start_task:{task_id}"),
            );
            push_feedback_event(first_playable, &format!("Task accepted: {task_id}"));
            if task_id == "task-arena-rematch-route" {
                first_playable.combat_turn = 0;
                first_playable.enemy_hp = 52;
                first_playable.player_hp = first_playable.player_hp.max(100);
                first_playable.combat_result_state = "in_progress".to_string();
                first_playable.combat_scene_state = "turn_combat_rematch_ready".to_string();
                first_playable.combat_overlay_visible = true;
                first_playable.combat_overlay_was_visible = true;
                first_playable.scene_transition = "turn_combat_rematch_loaded".to_string();
                first_playable.map_scene = "combat_arena_turn_room".to_string();
                first_playable.tilemap_variant = "arena_combat_room".to_string();
                first_playable.active_scene_layer = "arena_combat_room_tilemap".to_string();
                first_playable.combat_actions_available = runtime_combat_actions(
                    true,
                    first_playable
                        .inventory_items
                        .iter()
                        .any(|item| item == "small_healing_pill"),
                );
                push_history(
                    &mut first_playable.combat_round_log,
                    "rematch:start:enemy_hp:52",
                );
                push_history(
                    &mut first_playable.visible_behavior_history,
                    "arena_rematch_enemy_spawned",
                );
                push_progression_checkpoint(first_playable, "rematch_started");
                push_feedback_event(first_playable, "Arena rematch started: stat effects active");
            }
            if let Some(required_stat) = build_branch_task_required_stat(task_id) {
                first_playable.objective_status =
                    format!("build_branch_active:{required_stat}:{task_id}");
                push_completed_step(
                    first_playable,
                    &format!("build_branch_started_{required_stat}"),
                );
                push_progression_checkpoint(
                    first_playable,
                    &format!("build_branch_started:{task_id}"),
                );
                push_history(
                    &mut first_playable.growth_history,
                    &format!("build_branch_active:{required_stat}:{task_id}"),
                );
                match required_stat {
                    "force" => {
                        first_playable.combat_turn = 0;
                        first_playable.enemy_hp = 56;
                        first_playable.player_hp = first_playable.player_hp.max(100);
                        first_playable.combat_result_state = "in_progress".to_string();
                        first_playable.combat_scene_state =
                            "force_commission_duelist_ready".to_string();
                        first_playable.combat_overlay_visible = true;
                        first_playable.combat_overlay_was_visible = true;
                        first_playable.scene_transition = "force_commission_loaded".to_string();
                        first_playable.map_scene = "force_commission_arena".to_string();
                        first_playable.tilemap_variant = "arena_combat_room".to_string();
                        first_playable.active_scene_layer =
                            "force_commission_arena_tilemap".to_string();
                        first_playable.combat_actions_available = runtime_combat_actions(
                            true,
                            first_playable
                                .inventory_items
                                .iter()
                                .any(|item| item == "small_healing_pill"),
                        );
                        push_history(
                            &mut first_playable.visible_behavior_history,
                            "build_branch_force_enemy_spawned",
                        );
                    }
                    "agility" => {
                        first_playable.scene_transition =
                            "agility_scout_route_directed".to_string();
                        first_playable.map_scene = "delivery_dock_scout_route".to_string();
                        push_history(
                            &mut first_playable.visible_behavior_history,
                            "build_branch_agility_scout_marker_visible",
                        );
                    }
                    "craft" => {
                        first_playable.scene_transition =
                            "craft_delivery_order_directed".to_string();
                        first_playable.map_scene = "forge_delivery_order_route".to_string();
                        push_history(
                            &mut first_playable.visible_behavior_history,
                            "build_branch_craft_order_marker_visible",
                        );
                    }
                    _ => {}
                }
                push_feedback_event(
                    first_playable,
                    &format!(
                        "Build route started: {} via {required_stat}",
                        build_branch_task_label(task_id)
                    ),
                );
            }
            if let Some(required_stat) = build_branch_followup_required_stat(task_id) {
                first_playable.objective_status =
                    format!("build_branch_followup_active:{required_stat}:{task_id}");
                first_playable.scene_transition =
                    format!("build_branch_followup_{required_stat}_loaded");
                push_completed_step(
                    first_playable,
                    &format!("build_branch_followup_started_{required_stat}"),
                );
                push_progression_checkpoint(
                    first_playable,
                    &format!("build_branch_followup_started:{task_id}"),
                );
                push_history(
                    &mut first_playable.growth_history,
                    &format!("build_branch_followup_active:{required_stat}:{task_id}"),
                );
                match required_stat {
                    "force" => {
                        first_playable.map_scene = "force_guard_post_open".to_string();
                        first_playable.npc_dialogue_state =
                            "branch_followup_force_guard_dialogue".to_string();
                        first_playable.npc_behavior_state = "force_guard_duty_briefing".to_string();
                        first_playable.npc_bubble_text =
                            "Guard duty unlocked; hold the arena gate".to_string();
                        first_playable.enemy_behavior_state =
                            "force_gate_rival_respects_badge".to_string();
                        first_playable.enemy_damage_feedback =
                            "follow-up force: rival stands down".to_string();
                        push_history(
                            &mut first_playable.visible_behavior_history,
                            "branch_followup_force_guard_started",
                        );
                        push_history(
                            &mut first_playable.npc_behavior_history,
                            "force_guard_duty_briefing_bubble",
                        );
                        push_history(
                            &mut first_playable.enemy_behavior_history,
                            "force_gate_rival_stands_down",
                        );
                    }
                    "agility" => {
                        first_playable.map_scene = "agility_relay_lane_open".to_string();
                        first_playable.npc_dialogue_state =
                            "branch_followup_agility_relay_dialogue".to_string();
                        first_playable.npc_behavior_state =
                            "courier_relay_timer_started".to_string();
                        first_playable.npc_bubble_text =
                            "Courier relay unlocked; run the dock markers".to_string();
                        first_playable.enemy_behavior_state =
                            "enemy_routes_bypassed_by_relay".to_string();
                        first_playable.enemy_damage_feedback =
                            "follow-up agility: no combat, route bypassed".to_string();
                        push_history(
                            &mut first_playable.visible_behavior_history,
                            "branch_followup_agility_relay_started",
                        );
                        push_history(
                            &mut first_playable.npc_behavior_history,
                            "agility_relay_timer_bubble",
                        );
                        push_history(
                            &mut first_playable.enemy_behavior_history,
                            "agility_relay_enemy_bypassed",
                        );
                    }
                    "craft" => {
                        first_playable.map_scene = "craft_batch_forge_open".to_string();
                        first_playable.npc_dialogue_state =
                            "branch_followup_craft_batch_dialogue".to_string();
                        first_playable.npc_behavior_state =
                            "forge_batch_order_board_open".to_string();
                        first_playable.npc_bubble_text =
                            "Forge batch unlocked; stamp three client orders".to_string();
                        first_playable.enemy_behavior_state =
                            "enemy_absent_for_forge_batch".to_string();
                        first_playable.enemy_damage_feedback =
                            "follow-up craft: workshop safe".to_string();
                        push_history(
                            &mut first_playable.visible_behavior_history,
                            "branch_followup_craft_batch_started",
                        );
                        push_history(
                            &mut first_playable.npc_behavior_history,
                            "craft_batch_order_board_bubble",
                        );
                        push_history(
                            &mut first_playable.enemy_behavior_history,
                            "craft_batch_no_enemy",
                        );
                    }
                    _ => {}
                }
                push_feedback_event(
                    first_playable,
                    &format!(
                        "Build follow-up started: {}",
                        build_branch_followup_task_label(task_id)
                    ),
                );
            }
            if let Some(required_stat) = build_branch_mastery_challenge_required_stat(task_id) {
                first_playable.objective_status =
                    format!("build_mastery_challenge_active:{required_stat}:{task_id}");
                first_playable.scene_transition =
                    format!("build_mastery_challenge_{required_stat}_loaded");
                push_completed_step(
                    first_playable,
                    &format!("build_mastery_challenge_started_{required_stat}"),
                );
                push_progression_checkpoint(
                    first_playable,
                    &format!("build_mastery_challenge_started:{task_id}"),
                );
                push_history(
                    &mut first_playable.growth_history,
                    &format!("build_mastery_challenge_active:{required_stat}:{task_id}"),
                );
                match required_stat {
                    "force" => {
                        first_playable.combat_turn = 0;
                        first_playable.enemy_hp = 48;
                        first_playable.player_hp = first_playable.player_hp.max(100);
                        first_playable.combat_result_state = "in_progress".to_string();
                        first_playable.combat_scene_state =
                            "force_mastery_guard_trial_ready".to_string();
                        first_playable.combat_overlay_visible = true;
                        first_playable.combat_overlay_was_visible = true;
                        first_playable.map_scene = "force_mastery_guard_trial_open".to_string();
                        first_playable.tilemap_variant = "arena_combat_room".to_string();
                        first_playable.active_scene_layer =
                            "force_mastery_guard_trial_tilemap".to_string();
                        first_playable.npc_dialogue_state =
                            "build_mastery_force_trial_dialogue".to_string();
                        first_playable.npc_behavior_state =
                            "force_mastery_guard_trial_briefing".to_string();
                        first_playable.npc_bubble_text =
                            "Guard trial started; hold the gate with mastery stance".to_string();
                        first_playable.enemy_behavior_state =
                            "force_mastery_rival_attacks_gate".to_string();
                        first_playable.enemy_damage_feedback =
                            "mastery force trial: incoming damage reduced".to_string();
                        first_playable.combat_actions_available = runtime_combat_actions(
                            true,
                            first_playable
                                .inventory_items
                                .iter()
                                .any(|item| item == "small_healing_pill"),
                        );
                        push_history(
                            &mut first_playable.visible_behavior_history,
                            "build_mastery_challenge_force_guard_started",
                        );
                        push_history(
                            &mut first_playable.enemy_behavior_history,
                            "force_mastery_rival_trial_ready",
                        );
                    }
                    "agility" => {
                        first_playable.map_scene = "agility_mastery_shortcut_run_open".to_string();
                        first_playable.npc_dialogue_state =
                            "build_mastery_agility_shortcut_dialogue".to_string();
                        first_playable.npc_behavior_state =
                            "agility_mastery_shortcut_timer_started".to_string();
                        first_playable.npc_bubble_text =
                            "Shortcut run started; take delivery dock straight to the square"
                                .to_string();
                        first_playable.enemy_behavior_state =
                            "enemy_routes_bypassed_by_mastery_run".to_string();
                        first_playable.enemy_damage_feedback =
                            "mastery agility trial: direct shortcut open".to_string();
                        refresh_build_mastery_room_effects(first_playable);
                        push_history(
                            &mut first_playable.visible_behavior_history,
                            "build_mastery_challenge_agility_shortcut_started",
                        );
                        push_history(
                            &mut first_playable.route_director_history,
                            "build_mastery_challenge_route:agility:delivery-dock->mirror-city-square",
                        );
                    }
                    "craft" => {
                        first_playable.map_scene = "craft_mastery_client_order_open".to_string();
                        first_playable.npc_dialogue_state =
                            "build_mastery_craft_order_dialogue".to_string();
                        first_playable.npc_behavior_state =
                            "craft_mastery_client_order_board_open".to_string();
                        first_playable.npc_bubble_text =
                            "Master client order started; stamp the premium forge batch"
                                .to_string();
                        first_playable.enemy_behavior_state =
                            "enemy_absent_for_master_order".to_string();
                        first_playable.enemy_damage_feedback =
                            "mastery craft trial: workshop safe".to_string();
                        push_history(
                            &mut first_playable.visible_behavior_history,
                            "build_mastery_challenge_craft_order_started",
                        );
                        push_history(
                            &mut first_playable.npc_behavior_history,
                            "craft_mastery_client_order_board_bubble",
                        );
                    }
                    _ => {}
                }
                push_feedback_event(
                    first_playable,
                    &format!(
                        "Mastery challenge started: {}",
                        build_branch_mastery_challenge_task_label(task_id)
                    ),
                );
            }
        }
        NativeControlAction::CombatAttack
        | NativeControlAction::CombatDefend
        | NativeControlAction::CombatUseItem
        | NativeControlAction::CombatEscape => {
            update_turn_combat_runtime(first_playable, action);
        }
        NativeControlAction::OpenBag => {
            first_playable.bag_open = true;
            push_completed_step(first_playable, "bag_opened");
            push_progression_checkpoint(first_playable, "bag_opened");
            push_history(
                &mut first_playable.visible_behavior_history,
                "bag_overlay_visible",
            );
            push_feedback_event(
                first_playable,
                "Bag opened: inventory and equipment visible",
            );
        }
        NativeControlAction::LootDrop => {
            if let Some(drop_index) = first_playable
                .dropped_items
                .iter()
                .position(|item| item == "bandit_sash")
            {
                first_playable.dropped_items.remove(drop_index);
                push_unique_string(&mut first_playable.inventory_items, "bandit_sash");
                push_completed_step(first_playable, "loot_drop_collected");
                push_history(&mut first_playable.loot_history, "loot:bandit_sash");
                push_progression_checkpoint(first_playable, "loot:bandit_sash");
                push_history(
                    &mut first_playable.visible_behavior_history,
                    "item_drop_collected",
                );
                push_feedback_event(first_playable, "Loot collected: bandit_sash added to bag");
            }
        }
        NativeControlAction::EquipItem { item_id } => {
            if first_playable
                .inventory_items
                .iter()
                .any(|item| item == item_id)
            {
                first_playable
                    .inventory_items
                    .retain(|item| item != item_id);
                push_unique_string(&mut first_playable.equipped_items, item_id);
                first_playable.equipment_ready = true;
                push_completed_step(first_playable, "dropped_equipment_equipped");
                push_progression_checkpoint(first_playable, &format!("equip:{item_id}"));
                if item_id == "bandit_sash" {
                    first_playable.growth_level = first_playable.growth_level.max(2);
                    first_playable.growth_stat_points = first_playable.growth_stat_points.max(1);
                    push_history(
                        &mut first_playable.growth_history,
                        "level2:bandit_sash_equipped",
                    );
                    push_progression_checkpoint(first_playable, "growth_checkpoint:level2");
                    push_unique_string(
                        &mut first_playable.unlocked_task_ids,
                        "task-arena-rematch-route",
                    );
                    push_progression_checkpoint(
                        first_playable,
                        "unlock_next_task:task-arena-rematch-route",
                    );
                    first_playable.progression_loop_count =
                        first_playable.progression_loop_count.saturating_add(1);
                    update_route_director_runtime(first_playable, "task-arena-rematch-route");
                }
                push_history(
                    &mut first_playable.visible_behavior_history,
                    "equipment_icon_visible",
                );
                push_feedback_event(
                    first_playable,
                    &format!("Equipment changed: {item_id} equipped"),
                );
            }
        }
        NativeControlAction::EquipBuildTitle { title_id } => {
            if !apply_build_branch_title_equip(first_playable, title_id) {
                push_history(
                    &mut first_playable.blocked_action_history,
                    &format!("TITLE:EQUIP:{title_id}:build_title_unavailable"),
                );
                push_feedback_event(
                    first_playable,
                    &format!("Build title unavailable: {title_id}"),
                );
            }
        }
        NativeControlAction::AcceptTitleRouteRecommendation => {}
        NativeControlAction::AllocateStat { stat_id } => {
            if first_playable.growth_stat_points > 0
                && valid_growth_stat_id(stat_id)
                && !first_playable
                    .allocated_stat_points
                    .iter()
                    .any(|allocated| allocated == stat_id)
            {
                first_playable.pending_stat_allocation = Some(stat_id.clone());
                push_history(
                    &mut first_playable.stat_confirmation_history,
                    &format!("preview:{stat_id}"),
                );
                push_progression_checkpoint(
                    first_playable,
                    &format!("stat_preview_pending:{stat_id}"),
                );
                push_feedback_event(
                    first_playable,
                    &format!("Stat preview selected: {stat_id}; confirm to spend 1 point"),
                );
            }
        }
        NativeControlAction::ConfirmStatAllocation => {
            if let Some(stat_id) = first_playable.pending_stat_allocation.clone() {
                if first_playable.growth_stat_points > 0
                    && valid_growth_stat_id(&stat_id)
                    && !first_playable
                        .allocated_stat_points
                        .iter()
                        .any(|allocated| allocated == &stat_id)
                    && apply_character_stat_allocation(character, &stat_id)
                {
                    first_playable.growth_stat_points =
                        first_playable.growth_stat_points.saturating_sub(1);
                    first_playable.pending_stat_allocation = None;
                    push_unique_string(&mut first_playable.allocated_stat_points, &stat_id);
                    push_completed_step(first_playable, &format!("allocate_stat_{stat_id}"));
                    push_progression_checkpoint(
                        first_playable,
                        &format!("stat_allocated:{stat_id}"),
                    );
                    push_history(
                        &mut first_playable.growth_history,
                        &format!("stat:{stat_id}:+1"),
                    );
                    push_history(
                        &mut first_playable.stat_confirmation_history,
                        &format!("confirmed:{stat_id}"),
                    );
                    if let Some(branch_task_id) = build_branch_task_id_for_stat(&stat_id) {
                        push_unique_string(&mut first_playable.unlocked_task_ids, branch_task_id);
                        if !first_playable
                            .available_task_ids
                            .iter()
                            .any(|task_id| task_id == branch_task_id)
                        {
                            first_playable
                                .available_task_ids
                                .push(branch_task_id.to_string());
                        }
                        push_progression_checkpoint(
                            first_playable,
                            &format!("unlock_build_branch:{branch_task_id}"),
                        );
                        push_history(
                            &mut first_playable.growth_history,
                            &format!("build_branch_unlocked:{stat_id}:{branch_task_id}"),
                        );
                        update_route_director_runtime(first_playable, branch_task_id);
                    }
                    push_feedback_event(first_playable, &format!("Stat allocated: {stat_id} +1"));
                }
            }
        }
        NativeControlAction::CancelStatAllocation => {
            if let Some(stat_id) = first_playable.pending_stat_allocation.take() {
                push_history(
                    &mut first_playable.stat_confirmation_history,
                    &format!("cancelled:{stat_id}"),
                );
                push_progression_checkpoint(
                    first_playable,
                    &format!("stat_preview_cancelled:{stat_id}"),
                );
                push_feedback_event(
                    first_playable,
                    &format!("Stat preview cancelled: {stat_id}; point preserved"),
                );
            }
        }
        NativeControlAction::SaveSlot
        | NativeControlAction::LoadSlot
        | NativeControlAction::SaveSlotNamed { .. }
        | NativeControlAction::LoadSlotNamed { .. }
        | NativeControlAction::SelectSlot { .. }
        | NativeControlAction::SaveSelectedSlot
        | NativeControlAction::LoadSelectedSlot
        | NativeControlAction::ConfirmOverwriteSlot
        | NativeControlAction::CancelOverwriteSlot
        | NativeControlAction::ContinueAfterLoad
        | NativeControlAction::PauseMenu
        | NativeControlAction::ResumeFromPause
        | NativeControlAction::OpenSettingsMenu
        | NativeControlAction::CloseSettingsMenu
        | NativeControlAction::ToggleLowMotion
        | NativeControlAction::VolumeDown
        | NativeControlAction::VolumeUp
        | NativeControlAction::CycleInputMode
        | NativeControlAction::OpenTitleMenu
        | NativeControlAction::NewGameFromTitle
        | NativeControlAction::LoadFromTitle
        | NativeControlAction::ContinueFromTitle
        | NativeControlAction::RegisterAccountFromTitle
        | NativeControlAction::LoginAccountFromTitle
        | NativeControlAction::ContinueAccountFromTitle
        | NativeControlAction::CycleCharacterName
        | NativeControlAction::CycleCharacterArchetype
        | NativeControlAction::ConfirmCharacterCreate
        | NativeControlAction::BackToTitleFromCreate => {}
    }
    refresh_contextual_action_runtime(first_playable);
}

fn update_runtime_room_context(runtime: &mut NativeFirstPlayableRuntime, room_id: &str) {
    runtime.current_room_id = room_id.to_string();
    push_unique_string(&mut runtime.visited_rooms, room_id);
    runtime.available_room_exits = runtime_room_exits(room_id);
    runtime.room_interaction_points = runtime_room_interactions(room_id);
    runtime.active_room_npc_ids = runtime_room_npcs(room_id);
    runtime.available_task_ids = runtime_room_tasks(room_id);
    refresh_build_mastery_room_effects(runtime);
    runtime.npc_patrol_frame = runtime.npc_patrol_frame.wrapping_add(1) % 4;
    runtime.npc_patrol_route = runtime
        .active_room_npc_ids
        .iter()
        .map(|npc_id| format!("{npc_id}:patrol_frame_{}", runtime.npc_patrol_frame))
        .collect();
    push_history(
        &mut runtime.visible_behavior_history,
        &format!("room_actor_patrol:{room_id}:{}", runtime.npc_patrol_frame),
    );
    let task_id = runtime.route_director_task_id.clone();
    update_route_director_runtime(runtime, &task_id);
}

fn refresh_build_mastery_room_effects(runtime: &mut NativeFirstPlayableRuntime) {
    if runtime.current_room_id == "delivery-dock" && runtime_has_build_mastery(runtime, "agility") {
        push_unique_string(&mut runtime.available_room_exits, "mirror-city-square");
    }
    refresh_build_title_room_effects(runtime);
}

fn refresh_build_title_room_effects(runtime: &mut NativeFirstPlayableRuntime) {
    if runtime.current_room_id == "delivery-dock"
        && runtime_has_active_build_title(runtime, "agility")
    {
        push_unique_string(&mut runtime.available_room_exits, "mirror-city-square");
        push_history(
            &mut runtime.route_director_history,
            "active_title_route_effect:agility:delivery_priority_shortcut",
        );
    }
}

fn build_mastery_room_override(runtime: &NativeFirstPlayableRuntime, room_id: &str) -> bool {
    runtime.current_room_id == "delivery-dock"
        && room_id == "mirror-city-square"
        && runtime_has_build_mastery(runtime, "agility")
}

fn update_route_director_runtime(runtime: &mut NativeFirstPlayableRuntime, task_id: &str) {
    let plan = scene_pack_route_plan_for_task(&runtime.current_room_id, task_id);
    let path_room_ids = if build_mastery_room_override(runtime, &plan.target_room_id) {
        vec![runtime.current_room_id.clone(), plan.target_room_id.clone()]
    } else {
        plan.path_room_ids.clone()
    };
    runtime.route_director_task_id = task_id.to_string();
    runtime.route_director_target_room_id = plan.target_room_id.clone();
    runtime.route_director_path = path_room_ids.clone();
    runtime.route_director_next_room_id = path_room_ids
        .iter()
        .position(|room_id| room_id == &runtime.current_room_id)
        .and_then(|index| path_room_ids.get(index + 1).cloned());
    let route_status = if plan.blocked_reason.is_some() {
        plan.blocked_reason
            .clone()
            .unwrap_or_else(|| "blocked".to_string())
    } else if runtime.current_room_id == plan.target_room_id {
        format!("arrived:{}", plan.target_room_id)
    } else if let Some(next_room_id) = &runtime.route_director_next_room_id {
        format!("next:{next_room_id}")
    } else {
        "route_waiting".to_string()
    };
    push_history(
        &mut runtime.route_director_history,
        &format!(
            "route_director:{task_id}:{}:{}",
            runtime.current_room_id, route_status
        ),
    );
}

fn apply_build_title_route_recommendation(
    runtime: &mut NativeFirstPlayableRuntime,
    stat_id: &str,
    effect_id: &str,
) {
    let Some(task_id) = build_branch_title_recommended_task_id_for_runtime_stat(runtime, stat_id)
    else {
        return;
    };
    update_route_director_runtime(runtime, task_id);
    push_progression_checkpoint(
        runtime,
        &format!("active_title_route_recommended:{stat_id}:{task_id}"),
    );
    push_history(
        &mut runtime.route_director_history,
        &format!("active_title_route_recommendation:{stat_id}:{task_id}:{effect_id}"),
    );
}

fn room_map_scene(room_id: &str) -> String {
    scene_pack_room(room_id)
        .map(|room| room.map_scene)
        .unwrap_or_else(|| "town_square_outdoor".to_string())
}

fn room_tilemap_variant(room_id: &str) -> String {
    scene_pack_room(room_id)
        .map(|room| room.tilemap_variant)
        .unwrap_or_else(|| "outdoor_town".to_string())
}

fn runtime_npc_bubble(npc_id: &str) -> String {
    scene_pack_actor(npc_id)
        .map(|actor| actor.bubble_text)
        .unwrap_or_else(|| "Training route stays open".to_string())
}

fn update_turn_combat_runtime(
    runtime: &mut NativeFirstPlayableRuntime,
    action: &NativeControlAction,
) {
    if runtime.combat_result_state == "victory" || runtime.combat_result_state == "escaped" {
        return;
    }
    runtime.combat_overlay_visible = true;
    runtime.combat_overlay_was_visible = true;
    runtime.combat_scene_state = "turn_combat_active".to_string();
    runtime.scene_transition = "turn_combat_scene_loaded".to_string();
    runtime.map_scene = "combat_arena_turn_room".to_string();
    runtime.tilemap_variant = "arena_combat_room".to_string();
    runtime.active_scene_layer = "arena_combat_room_tilemap".to_string();
    push_completed_step(runtime, "turn_combat_scene_entered");
    push_history(&mut runtime.scene_history, "turn_combat_scene_loaded");

    match action {
        NativeControlAction::CombatAttack => {
            runtime.combat_turn = runtime.combat_turn.saturating_add(1);
            let damage = turn_combat_attack_damage(runtime);
            let incoming_damage = turn_combat_incoming_damage(runtime);
            runtime.enemy_hp = (runtime.enemy_hp - damage).max(0);
            let enemy_alive_after_hit = runtime.enemy_hp > 0;
            if runtime.enemy_hp > 0 {
                runtime.player_hp = (runtime.player_hp - incoming_damage).max(1);
            }
            runtime.stat_effect_floating_text = combat_stat_effect_floating_text(
                runtime,
                damage,
                incoming_damage,
                enemy_alive_after_hit,
            );
            runtime.enemy_damage_feedback = format!(
                "turn {} attack -{} HP | {}",
                runtime.combat_turn, damage, runtime.stat_effect_floating_text
            );
            push_history(
                &mut runtime.combat_round_log,
                &format!(
                    "turn{}:attack:damage:{}:incoming:{}:enemy_hp:{}:player_hp:{}",
                    runtime.combat_turn,
                    damage,
                    incoming_damage,
                    runtime.enemy_hp,
                    runtime.player_hp
                ),
            );
            if runtime_has_allocated_stat(runtime, "force") {
                push_history(
                    &mut runtime.growth_history,
                    "stat_effect:force:attack_damage_bonus",
                );
                push_progression_checkpoint(runtime, "stat_effect:force:attack_damage_bonus");
            }
            if runtime_has_allocated_stat(runtime, "agility") && runtime.enemy_hp > 0 {
                push_history(
                    &mut runtime.growth_history,
                    "stat_effect:agility:incoming_damage_reduced",
                );
                push_progression_checkpoint(runtime, "stat_effect:agility:incoming_damage_reduced");
            }
            push_history(
                &mut runtime.enemy_behavior_history,
                "turn_combat_enemy_hit_feedback",
            );
            if runtime.enemy_hp == 0 {
                let force_branch_victory = active_build_branch_task_id(runtime)
                    .and_then(build_branch_task_required_stat)
                    == Some("force");
                runtime.combat_result_state = "victory".to_string();
                runtime.combat_scene_state = if force_branch_victory {
                    "force_commission_victory_ready_to_complete".to_string()
                } else {
                    "turn_combat_victory_return_to_map".to_string()
                };
                runtime.scene_transition = if force_branch_victory {
                    "force_commission_return_to_map".to_string()
                } else {
                    "turn_combat_return_to_map".to_string()
                };
                runtime.combat_overlay_visible = false;
                runtime.map_scene = if force_branch_victory {
                    "force_commission_arena".to_string()
                } else {
                    "arena_outdoor".to_string()
                };
                runtime.tilemap_variant = "arena_outdoor".to_string();
                runtime.active_scene_layer = "arena_outdoor_tilemap".to_string();
                if force_branch_victory {
                    push_completed_step(runtime, "build_branch_force_victory");
                    push_progression_checkpoint(runtime, "build_branch_force_victory");
                    push_history(
                        &mut runtime.visible_behavior_history,
                        "build_branch_force_enemy_defeated",
                    );
                } else {
                    runtime.xp = runtime.xp.max(35);
                    runtime.growth_level = runtime.growth_level.max(2);
                    runtime.growth_stat_points = runtime.growth_stat_points.max(1);
                    push_history(&mut runtime.growth_history, "level2:arena_victory");
                    push_progression_checkpoint(runtime, "combat_victory");
                    push_progression_checkpoint(runtime, "growth_checkpoint:level2");
                    push_unique_string(&mut runtime.dropped_items, "bandit_sash");
                    push_history(&mut runtime.loot_history, "drop_visible:bandit_sash");
                    push_completed_step(runtime, "turn_combat_victory");
                    push_completed_step(runtime, "resolve_first_combat");
                }
                push_history(&mut runtime.scene_history, "turn_combat_returned_to_map");
                push_history(&mut runtime.enemy_behavior_history, "enemy_hp_changed");
                if !force_branch_victory {
                    push_history(&mut runtime.visible_behavior_history, "item_drop_visible");
                    push_history(
                        &mut runtime.visible_behavior_history,
                        "growth_level_up_visible",
                    );
                }
            } else {
                runtime.combat_result_state = "in_progress".to_string();
            }
        }
        NativeControlAction::CombatDefend => {
            runtime.combat_turn = runtime.combat_turn.saturating_add(1);
            let heal = turn_combat_defend_heal(runtime);
            runtime.player_hp = (runtime.player_hp + heal).min(100);
            runtime.stat_effect_floating_text = defend_stat_effect_floating_text(runtime, heal);
            runtime.enemy_damage_feedback =
                format!("guarded: {}", runtime.stat_effect_floating_text);
            push_history(
                &mut runtime.combat_round_log,
                &format!(
                    "turn{}:defend:heal:{}:enemy_hp:{}:player_hp:{}",
                    runtime.combat_turn, heal, runtime.enemy_hp, runtime.player_hp
                ),
            );
            if runtime_has_allocated_stat(runtime, "agility") {
                push_history(
                    &mut runtime.growth_history,
                    "stat_effect:agility:defend_recovery_bonus",
                );
            }
            runtime.combat_result_state = "in_progress".to_string();
        }
        NativeControlAction::CombatUseItem => {
            runtime.combat_turn = runtime.combat_turn.saturating_add(1);
            runtime
                .inventory_items
                .retain(|item| item != "small_healing_pill");
            runtime.player_hp = (runtime.player_hp + 18).min(100);
            runtime.enemy_damage_feedback = "small_healing_pill used".to_string();
            push_history(
                &mut runtime.combat_round_log,
                &format!(
                    "turn{}:potion:enemy_hp:{}:player_hp:{}",
                    runtime.combat_turn, runtime.enemy_hp, runtime.player_hp
                ),
            );
            runtime.combat_result_state = "in_progress".to_string();
        }
        NativeControlAction::CombatEscape => {
            runtime.combat_turn = runtime.combat_turn.saturating_add(1);
            runtime.combat_result_state = "escaped".to_string();
            runtime.combat_scene_state = "turn_combat_escape_return_to_map".to_string();
            runtime.scene_transition = "turn_combat_escape_return_to_map".to_string();
            runtime.combat_overlay_visible = false;
            push_history(
                &mut runtime.combat_round_log,
                &format!("turn{}:escape", runtime.combat_turn),
            );
        }
        _ => {}
    }
    runtime.combat_actions_available = runtime_combat_actions(
        runtime.combat_result_state != "victory" && runtime.combat_result_state != "escaped",
        runtime
            .inventory_items
            .iter()
            .any(|item| item == "small_healing_pill"),
    );
    runtime.enemy_patrol_frame = runtime.enemy_patrol_frame.wrapping_add(1) % 4;
    runtime.enemy_patrol_route = vec![format!(
        "enemy-market-bandit:combat_frame_{}",
        runtime.enemy_patrol_frame
    )];
    push_history(
        &mut runtime.visible_behavior_history,
        &format!("enemy_combat_frame:{}", runtime.enemy_patrol_frame),
    );
    push_feedback_event(
        runtime,
        &format!(
            "Turn combat: {} enemy HP {} player HP {}",
            native_control_action_label(action),
            runtime.enemy_hp,
            runtime.player_hp
        ),
    );
}

fn push_completed_step(first_playable: &mut NativeFirstPlayableRuntime, step: &str) {
    if !first_playable
        .completed_steps
        .iter()
        .any(|value| value == step)
    {
        first_playable.completed_steps.push(step.to_string());
    }
}

fn push_feedback_event(first_playable: &mut NativeFirstPlayableRuntime, message: &str) {
    first_playable.last_feedback = message.to_string();
    if !first_playable
        .feedback_events
        .iter()
        .any(|existing| existing == message)
    {
        first_playable.feedback_events.push(message.to_string());
    }
    if first_playable.feedback_events.len() > 8 {
        let overflow = first_playable.feedback_events.len() - 8;
        first_playable.feedback_events.drain(0..overflow);
    }
}

fn record_input_feedback(
    first_playable: &mut NativeFirstPlayableRuntime,
    input_source: &str,
    action_label: &str,
    accepted: bool,
    reason: &str,
) {
    first_playable
        .input_feedback_history
        .push(NativeInputFeedbackEvent {
            input_source: input_source.to_string(),
            action_label: action_label.to_string(),
            accepted,
            reason: reason.to_string(),
            room_id: first_playable.current_room_id.clone(),
            feedback_text: first_playable.last_feedback.clone(),
        });
    if first_playable.input_feedback_history.len() > 12 {
        let overflow = first_playable.input_feedback_history.len() - 12;
        first_playable.input_feedback_history.drain(0..overflow);
    }
}

fn push_history(history: &mut Vec<String>, value: &str) {
    if !history.iter().any(|existing| existing == value) {
        history.push(value.to_string());
    }
}

fn push_progression_checkpoint(runtime: &mut NativeFirstPlayableRuntime, value: &str) {
    push_history(&mut runtime.progression_checkpoint_history, value);
}

fn push_unique_string(values: &mut Vec<String>, value: &str) {
    if !values.iter().any(|existing| existing == value) {
        values.push(value.to_string());
    }
}

fn native_growth_stat_button_ids() -> [&'static str; 3] {
    ["force", "agility", "craft"]
}

fn valid_growth_stat_id(stat_id: &str) -> bool {
    matches!(
        stat_id,
        "physique" | "force" | "agility" | "insight" | "resolve" | "craft" | "commerce"
    )
}

fn runtime_has_allocated_stat(runtime: &NativeFirstPlayableRuntime, stat_id: &str) -> bool {
    runtime
        .allocated_stat_points
        .iter()
        .any(|allocated| allocated == stat_id)
}

fn runtime_has_equipped_bandit_sash(runtime: &NativeFirstPlayableRuntime) -> bool {
    runtime
        .equipped_items
        .iter()
        .any(|item| item == "bandit_sash")
}

fn runtime_has_active_sash_stat(runtime: &NativeFirstPlayableRuntime, stat_id: &str) -> bool {
    runtime_has_equipped_bandit_sash(runtime) && runtime_has_allocated_stat(runtime, stat_id)
}

fn build_branch_completion_availability(
    runtime: &NativeFirstPlayableRuntime,
    task_id: &str,
) -> (bool, String) {
    let Some(required_stat) = build_branch_task_required_stat(task_id) else {
        return (false, format!("not_build_branch_task:{task_id}"));
    };
    if !runtime
        .active_task_ids
        .iter()
        .any(|active_task_id| active_task_id == task_id)
    {
        return (false, format!("build_branch_not_active:{task_id}"));
    }
    if required_stat == "force" {
        if runtime.combat_result_state == "victory" {
            return (true, format!("enabled_build_branch_outcome:{task_id}"));
        }
        return (
            false,
            format!("build_branch_force_victory_required:{task_id}"),
        );
    }
    let target_room_id = build_branch_task_target_room_id(task_id);
    if runtime.current_room_id == target_room_id {
        (true, format!("enabled_build_branch_outcome:{task_id}"))
    } else {
        (
            false,
            format!("build_branch_target_room_required:{target_room_id}:{task_id}"),
        )
    }
}

fn build_branch_followup_completion_availability(
    runtime: &NativeFirstPlayableRuntime,
    task_id: &str,
) -> (bool, String) {
    if build_branch_followup_required_stat(task_id).is_none() {
        return (false, format!("not_build_branch_followup_task:{task_id}"));
    }
    if !runtime
        .active_task_ids
        .iter()
        .any(|active_task_id| active_task_id == task_id)
    {
        return (false, format!("build_branch_followup_not_active:{task_id}"));
    }
    let target_room_id = build_branch_followup_task_target_room_id(task_id);
    if runtime.current_room_id == target_room_id {
        (
            true,
            format!("enabled_build_branch_followup_completion:{task_id}"),
        )
    } else {
        (
            false,
            format!("build_branch_followup_target_room_required:{target_room_id}:{task_id}"),
        )
    }
}

