fn apply_build_branch_mastery_title(
    runtime: &mut NativeFirstPlayableRuntime,
    stat_id: &str,
    challenge_task_id: &str,
) {
    let Some(title_id) = build_branch_mastery_title_id_for_stat(stat_id) else {
        return;
    };
    let effect_id = build_branch_mastery_title_effect_for_stat(stat_id).unwrap_or("custom_effect");
    push_unique_string(&mut runtime.build_title_unlocked_ids, title_id);
    push_unique_string(&mut runtime.build_title_effects, effect_id);
    push_completed_step(runtime, &format!("build_mastery_title_unlocked_{stat_id}"));
    push_progression_checkpoint(runtime, &format!("build_mastery_title_unlocked:{title_id}"));
    push_history(
        &mut runtime.growth_history,
        &format!("build_mastery_title:{stat_id}:{title_id}:{effect_id}"),
    );
    push_history(
        &mut runtime.visible_behavior_history,
        &format!("build_mastery_title_{stat_id}_visible"),
    );
    push_history(
        &mut runtime.loot_history,
        &format!("build_mastery_title_from_challenge:{challenge_task_id}:{title_id}"),
    );
    runtime.reward_settlement_text.push_str(&format!(
        " | TITLE {}",
        build_branch_mastery_title_label(stat_id)
    ));
    runtime.stat_effect_floating_text = runtime.reward_settlement_text.clone();
    match stat_id {
        "force" => {
            runtime
                .npc_bubble_text
                .push_str(" | TITLE Gate Warden recognized");
            runtime
                .enemy_damage_feedback
                .push_str(" | TITLE rival patrol respects gate");
            push_history(
                &mut runtime.npc_behavior_history,
                "build_mastery_title_force_gate_warden_bubble",
            );
            push_history(
                &mut runtime.enemy_behavior_history,
                "build_mastery_title_force_rival_respects_gate",
            );
        }
        "agility" => {
            runtime
                .npc_bubble_text
                .push_str(" | TITLE Relay Runner recognized");
            runtime
                .enemy_damage_feedback
                .push_str(" | TITLE route watchers clear shortcut");
            push_history(
                &mut runtime.npc_behavior_history,
                "build_mastery_title_agility_relay_runner_bubble",
            );
            push_history(
                &mut runtime.route_director_history,
                "build_mastery_title_route_effect:agility:relay_priority_open",
            );
        }
        "craft" => {
            runtime
                .npc_bubble_text
                .push_str(" | TITLE Forge Master recognized");
            runtime
                .enemy_damage_feedback
                .push_str(" | TITLE clients trust batch orders");
            push_history(
                &mut runtime.npc_behavior_history,
                "build_mastery_title_craft_forge_master_bubble",
            );
            push_history(
                &mut runtime.loot_history,
                "build_mastery_title_craft_client_trust_anchor",
            );
        }
        _ => {}
    }
}

fn build_branch_world_reaction_text(runtime: &NativeFirstPlayableRuntime) -> String {
    let mut reactions = Vec::new();
    if runtime
        .completed_task_ids
        .iter()
        .any(|task_id| task_id == "task-force-combat-commission")
    {
        reactions
            .push("force:arena_duelist_defeated npc:force_commission_cleared enemy:duelist_yields");
    }
    if runtime
        .completed_task_ids
        .iter()
        .any(|task_id| task_id == "task-agility-scout-route")
    {
        reactions.push(
            "agility:dock_route_marked npc:courier_updates_route enemy:no_combat_route_clear",
        );
    }
    if runtime
        .completed_task_ids
        .iter()
        .any(|task_id| task_id == "task-craft-delivery-order")
    {
        reactions.push(
            "craft:forge_order_stamped npc:workbench_receipt_visible enemy:no_combat_order_clear",
        );
    }
    if reactions.is_empty() {
        "BUILD REACTION | none".to_string()
    } else {
        format!("BUILD REACTION | {}", reactions.join(" | "))
    }
}

