fn build_branch_followup_status(runtime: &NativeFirstPlayableRuntime, task_id: &str) -> String {
    if runtime
        .completed_task_ids
        .iter()
        .any(|completed| completed == task_id)
    {
        "completed".to_string()
    } else if runtime
        .active_task_ids
        .iter()
        .any(|active| active == task_id)
    {
        "active".to_string()
    } else if runtime
        .unlocked_task_ids
        .iter()
        .any(|unlocked| unlocked == task_id)
    {
        "unlocked_after_restore".to_string()
    } else {
        let required_stat = build_branch_followup_required_stat(task_id).unwrap_or("custom");
        format!("locked_requires_{required_stat}_branch_complete")
    }
}

fn build_branch_followup_unlock_text(runtime: &NativeFirstPlayableRuntime) -> String {
    let followups = build_branch_followup_task_ids()
        .into_iter()
        .map(|task_id| {
            let required_stat = build_branch_followup_required_stat(task_id).unwrap_or("custom");
            let target_room = build_branch_followup_task_target_room_id(task_id);
            format!(
                "{required_stat}:{task_id}:{} -> {} at {target_room}",
                build_branch_followup_status(runtime, task_id),
                build_branch_followup_task_label(task_id)
            )
        })
        .collect::<Vec<_>>()
        .join(" | ");
    format!("BRANCH FOLLOWUP | {followups}")
}

