fn build_branch_mastery_title_status(
    runtime: &NativeFirstPlayableRuntime,
    stat_id: &str,
) -> String {
    if build_branch_mastery_title_id_for_stat(stat_id)
        .is_some_and(|title_id| runtime.active_build_title_id.as_deref() == Some(title_id))
    {
        "active".to_string()
    } else if build_branch_mastery_title_id_for_stat(stat_id)
        .is_some_and(|title_id| runtime_has_build_title_id(runtime, title_id))
    {
        "unlocked".to_string()
    } else {
        format!("locked_requires_{stat_id}_mastery_challenge")
    }
}

fn active_build_title_text(runtime: &NativeFirstPlayableRuntime) -> String {
    if let Some(title_id) = runtime.active_build_title_id.as_deref() {
        let stat_id = build_branch_mastery_title_stat_for_id(title_id).unwrap_or("custom");
        let effect = runtime
            .active_build_title_effect
            .as_deref()
            .unwrap_or("custom_effect");
        format!(
            "ACTIVE TITLE | {stat_id}:{title_id} -> {} effect {effect}",
            build_branch_mastery_title_label(stat_id)
        )
    } else {
        "ACTIVE TITLE | none".to_string()
    }
}

fn build_branch_mastery_title_text(runtime: &NativeFirstPlayableRuntime) -> String {
    let titles = ["force", "agility", "craft"]
        .into_iter()
        .map(|stat_id| {
            let title_id =
                build_branch_mastery_title_id_for_stat(stat_id).unwrap_or("custom-title");
            let effect =
                build_branch_mastery_title_effect_for_stat(stat_id).unwrap_or("custom_effect");
            format!(
                "{stat_id}:{title_id}:{} -> {} effect {effect}",
                build_branch_mastery_title_status(runtime, stat_id),
                build_branch_mastery_title_label(stat_id)
            )
        })
        .collect::<Vec<_>>()
        .join(" | ");
    format!(
        "MASTERY TITLE | {titles}\n{}",
        active_build_title_text(runtime)
    )
}

fn apply_build_branch_title_equip(
    runtime: &mut NativeFirstPlayableRuntime,
    title_id: &str,
) -> bool {
    let Some(stat_id) = build_branch_mastery_title_stat_for_id(title_id) else {
        return false;
    };
    if !runtime_has_build_title_id(runtime, title_id) {
        return false;
    }
    let effect_id = build_branch_mastery_title_effect_for_stat(stat_id).unwrap_or("custom_effect");
    runtime.active_build_title_id = Some(title_id.to_string());
    runtime.active_build_title_effect = Some(effect_id.to_string());
    push_completed_step(runtime, &format!("build_title_equipped_{stat_id}"));
    push_progression_checkpoint(runtime, &format!("build_title_equipped:{title_id}"));
    push_history(
        &mut runtime.build_title_equip_history,
        &format!("equipped:{stat_id}:{title_id}:{effect_id}"),
    );
    push_history(
        &mut runtime.growth_history,
        &format!("build_title_equipped:{stat_id}:{title_id}:{effect_id}"),
    );
    push_history(
        &mut runtime.visible_behavior_history,
        &format!("active_build_title_{stat_id}_visible"),
    );
    runtime.stat_effect_floating_text = format!(
        "ACTIVE TITLE {} | {effect_id}",
        build_branch_mastery_title_label(stat_id)
    );
    runtime.reward_settlement_text.push_str(&format!(
        " | ACTIVE TITLE {}",
        build_branch_mastery_title_label(stat_id)
    ));
    match stat_id {
        "force" => {
            runtime
                .enemy_damage_feedback
                .push_str(" | ACTIVE TITLE Gate Warden -1 incoming");
            push_history(
                &mut runtime.enemy_behavior_history,
                "active_title_force_gate_warden_threat",
            );
        }
        "agility" => {
            runtime
                .npc_bubble_text
                .push_str(" | ACTIVE TITLE Relay Runner priority");
            push_history(
                &mut runtime.route_director_history,
                "active_title_route_effect:agility:relay_priority_anchor",
            );
            refresh_build_title_room_effects(runtime);
        }
        "craft" => {
            runtime.reward_settlement_text.push_str(" client +2");
            runtime
                .npc_bubble_text
                .push_str(" | ACTIVE TITLE Forge Master client trust");
            push_history(
                &mut runtime.loot_history,
                "active_title_craft_client_trust_anchor",
            );
        }
        _ => {}
    }
    apply_build_title_route_recommendation(runtime, stat_id, effect_id);
    push_feedback_event(
        runtime,
        &format!(
            "Build title equipped: {} ({title_id})",
            build_branch_mastery_title_label(stat_id)
        ),
    );
    true
}

fn apply_build_branch_mastery(runtime: &mut NativeFirstPlayableRuntime, stat_id: &str) {
    let Some(mastery_id) = build_branch_mastery_id_for_stat(stat_id) else {
        return;
    };
    let effect_id = build_branch_mastery_effect_for_stat(stat_id).unwrap_or("custom_effect");
    push_unique_string(&mut runtime.build_mastery_unlocked_ids, mastery_id);
    push_unique_string(&mut runtime.build_mastery_effects, effect_id);
    push_completed_step(runtime, &format!("build_mastery_unlocked_{stat_id}"));
    push_progression_checkpoint(runtime, &format!("build_mastery_unlocked:{mastery_id}"));
    push_history(
        &mut runtime.growth_history,
        &format!("build_mastery:{stat_id}:{mastery_id}:{effect_id}"),
    );
    if let Some(challenge_task_id) = build_branch_mastery_challenge_task_id_for_stat(stat_id) {
        push_unique_string(&mut runtime.unlocked_task_ids, challenge_task_id);
        if runtime_room_tasks(&runtime.current_room_id)
            .iter()
            .any(|task_id| task_id == challenge_task_id)
        {
            push_unique_string(&mut runtime.available_task_ids, challenge_task_id);
        }
        push_progression_checkpoint(
            runtime,
            &format!("unlock_build_mastery_challenge:{challenge_task_id}"),
        );
        push_history(
            &mut runtime.growth_history,
            &format!("build_mastery_challenge_unlocked:{stat_id}:{challenge_task_id}"),
        );
        push_history(
            &mut runtime.visible_behavior_history,
            &format!("build_mastery_challenge_{stat_id}_marker_visible"),
        );
        push_history(
            &mut runtime.npc_behavior_history,
            &format!("build_mastery_challenge_{stat_id}_briefing_ready"),
        );
    }
    match stat_id {
        "force" => {
            runtime
                .npc_bubble_text
                .push_str(" | MASTERY guard stance ready");
            runtime
                .enemy_damage_feedback
                .push_str(" | MASTERY incoming -2");
            push_history(
                &mut runtime.visible_behavior_history,
                "build_mastery_force_guard_stance_visible",
            );
            push_history(
                &mut runtime.enemy_behavior_history,
                "build_mastery_force_incoming_damage_reduction",
            );
            push_history(
                &mut runtime.route_director_history,
                "build_mastery_route_effect:force:arena_gate_patrol_cleared",
            );
        }
        "agility" => {
            runtime
                .npc_bubble_text
                .push_str(" | MASTERY shortcut route open");
            runtime
                .enemy_damage_feedback
                .push_str(" | MASTERY route bypass stable");
            push_unique_string(&mut runtime.available_room_exits, "mirror-city-square");
            push_history(
                &mut runtime.visible_behavior_history,
                "build_mastery_agility_shortcut_visible",
            );
            push_history(
                &mut runtime.route_director_history,
                "build_mastery_route_effect:agility:shortcut_route_opened:delivery-dock->mirror-city-square",
            );
        }
        "craft" => {
            runtime.coins = runtime.coins.saturating_add(3);
            runtime
                .reward_settlement_text
                .push_str(" | CRAFT MASTERY +3 coins");
            runtime.stat_effect_floating_text = runtime.reward_settlement_text.clone();
            runtime
                .npc_bubble_text
                .push_str(" | MASTERY client orders pay +3 coins");
            runtime
                .enemy_damage_feedback
                .push_str(" | MASTERY workshop economy secured");
            push_history(
                &mut runtime.visible_behavior_history,
                "build_mastery_craft_bonus_visible",
            );
            push_history(
                &mut runtime.loot_history,
                "build_mastery_craft_client_order_coin_bonus_3",
            );
            push_history(
                &mut runtime.route_director_history,
                "build_mastery_route_effect:craft:forge_orders_bonus_active",
            );
        }
        _ => {}
    }
    refresh_build_mastery_room_effects(runtime);
}

fn complete_build_branch_task(runtime: &mut NativeFirstPlayableRuntime, task_id: &str) {
    let Some(required_stat) = build_branch_task_required_stat(task_id) else {
        return;
    };
    let (reward_coins, reward_xp, reward_item_id, _) = build_branch_outcome_reward(task_id);
    runtime
        .active_task_ids
        .retain(|active_task_id| active_task_id != task_id);
    push_unique_string(&mut runtime.completed_task_ids, task_id);
    push_unique_string(&mut runtime.inventory_items, reward_item_id);
    runtime.coins = runtime.coins.saturating_add(reward_coins);
    runtime.xp = runtime.xp.saturating_add(reward_xp);
    runtime.reward_claimed = true;
    runtime.reward_settlement_text =
        build_branch_outcome_settlement_text(task_id, reward_coins, reward_xp);
    runtime.stat_effect_floating_text = runtime.reward_settlement_text.clone();
    runtime.tutorial_step = "build_branch_route_complete".to_string();
    runtime.objective_status = format!("build_branch_completed:{required_stat}:{task_id}");
    runtime.scene_transition = format!("build_branch_{required_stat}_outcome_settled");
    runtime.combat_overlay_visible = false;
    runtime.combat_actions_available = runtime_combat_actions(
        false,
        runtime
            .inventory_items
            .iter()
            .any(|item| item == "small_healing_pill"),
    );
    match required_stat {
        "force" => {
            runtime.map_scene = "force_commission_arena_cleared".to_string();
            runtime.npc_behavior_state = "branch_force_commission_cleared".to_string();
            runtime.npc_bubble_text =
                "Force commission cleared; duelist yields the lane".to_string();
            runtime.enemy_behavior_state = "force_commission_duelist_defeated".to_string();
            runtime.enemy_damage_feedback = "force route clear: duelist yields".to_string();
            push_history(
                &mut runtime.visible_behavior_history,
                "branch_world_force_duelist_defeated",
            );
            push_history(
                &mut runtime.enemy_behavior_history,
                "force_commission_duelist_defeated",
            );
            push_history(
                &mut runtime.npc_behavior_history,
                "force_commission_cleared_bubble",
            );
        }
        "agility" => {
            runtime.map_scene = "delivery_dock_scout_route_cleared".to_string();
            runtime.npc_behavior_state = "dock_courier_route_chart_updated".to_string();
            runtime.npc_bubble_text = "Scout markers pinned from dock to arena bridge".to_string();
            runtime.enemy_behavior_state = "enemy_not_engaged_after_scout_route".to_string();
            runtime.enemy_damage_feedback = "no combat: scout route mapped".to_string();
            push_history(
                &mut runtime.visible_behavior_history,
                "branch_world_agility_courier_updated",
            );
            push_history(
                &mut runtime.npc_behavior_history,
                "agility_scout_route_chart_bubble",
            );
            push_history(
                &mut runtime.enemy_behavior_history,
                "agility_scout_route_no_combat",
            );
        }
        "craft" => {
            runtime.map_scene = "forge_delivery_order_cleared".to_string();
            runtime.npc_behavior_state = "forge_workbench_order_stamped".to_string();
            runtime.npc_bubble_text = "Delivery order stamped; forge queue updated".to_string();
            runtime.enemy_behavior_state = "enemy_ignored_craft_delivery".to_string();
            runtime.enemy_damage_feedback = "no combat: order delivered".to_string();
            push_history(
                &mut runtime.visible_behavior_history,
                "branch_world_craft_order_stamped",
            );
            push_history(
                &mut runtime.npc_behavior_history,
                "craft_delivery_order_receipt_bubble",
            );
            push_history(
                &mut runtime.enemy_behavior_history,
                "craft_delivery_order_no_combat",
            );
        }
        _ => {}
    }
    let followup_task_id = build_branch_followup_task_id_for_stat(required_stat);
    if let Some(followup_task_id) = followup_task_id {
        push_unique_string(&mut runtime.unlocked_task_ids, followup_task_id);
        if runtime_room_tasks(&runtime.current_room_id)
            .iter()
            .any(|task_id| task_id == followup_task_id)
        {
            push_unique_string(&mut runtime.available_task_ids, followup_task_id);
        }
        push_progression_checkpoint(
            runtime,
            &format!("unlock_build_branch_followup:{followup_task_id}"),
        );
        push_history(
            &mut runtime.growth_history,
            &format!("build_branch_followup_unlocked:{required_stat}:{followup_task_id}"),
        );
        push_history(
            &mut runtime.visible_behavior_history,
            &format!("branch_followup_{required_stat}_marker_visible"),
        );
        push_history(
            &mut runtime.npc_behavior_history,
            &format!("branch_followup_{required_stat}_briefing_ready"),
        );
    }
    push_completed_step(runtime, "complete_build_branch_task");
    push_completed_step(runtime, &format!("build_branch_completed_{required_stat}"));
    push_progression_checkpoint(runtime, &format!("build_branch_completed:{task_id}"));
    push_history(
        &mut runtime.growth_history,
        &format!("build_branch_completed:{required_stat}:{task_id}"),
    );
    push_history(
        &mut runtime.loot_history,
        &format!("build_branch_reward:{task_id}:{reward_item_id}"),
    );
    push_history(
        &mut runtime.visible_behavior_history,
        &format!("build_branch_{required_stat}_reward_visible"),
    );
    update_route_director_runtime(runtime, followup_task_id.unwrap_or(task_id));
    push_feedback_event(
        runtime,
        &format!(
            "Build branch complete: {} +{reward_coins} coins +{reward_xp} XP",
            build_branch_task_label(task_id)
        ),
    );
}

