fn native_command_label(command: &WorldCommand) -> String {
    match command {
        WorldCommand::Move { direction, .. } => format!("move:{direction}"),
        WorldCommand::TalkNpc { npc_id, .. } => format!("talk:{npc_id}"),
        WorldCommand::TrainSkill { skill_id, .. } => format!("train:{skill_id}"),
        WorldCommand::CompleteTask { task_id, .. } => format!("complete:{task_id}"),
    }
}

fn player_node_id(world: &WorldState, actor_id: &str) -> Option<String> {
    world
        .positions
        .iter()
        .find(|position| position.actor_id == actor_id)
        .map(|position| position.node_id.clone())
}

fn exits_for_node(world: &WorldState, node_id: &str) -> Vec<String> {
    world
        .edges
        .iter()
        .filter(|edge| edge.from == node_id)
        .map(|edge| edge.direction.clone())
        .collect()
}

fn playable_exits_for_actor(world: &WorldState, actor_id: &str) -> Vec<NativePlayableExit> {
    let Some(node_id) = player_node_id(world, actor_id) else {
        return Vec::new();
    };
    world
        .edges
        .iter()
        .filter(|edge| edge.from == node_id)
        .map(|edge| NativePlayableExit {
            direction: edge.direction.clone(),
            to_node_id: edge.to.clone(),
            to_room_name: world
                .node(&edge.to)
                .map(|node| node.name.clone())
                .unwrap_or_else(|| edge.to.clone()),
        })
        .collect()
}

fn playable_objective_for_actor(
    world: &WorldState,
    actor_id: &str,
) -> Option<NativePlayableObjective> {
    let task = world.tasks.first()?;
    let target_room_name = world
        .node(&task.node_id)
        .map(|node| node.name.clone())
        .unwrap_or_else(|| task.node_id.clone());
    Some(NativePlayableObjective {
        task_id: task.id.clone(),
        title: task.title.clone(),
        target_node_id: task.node_id.clone(),
        target_room_name,
        reward_units: task.reward_units,
        ledger_settlement_required: task.ledger_settlement_required,
        route_hint: objective_route_hint(world, actor_id, &task.node_id),
    })
}

fn objective_route_hint(world: &WorldState, actor_id: &str, target_node_id: &str) -> String {
    let Some(current_node_id) = player_node_id(world, actor_id) else {
        return "player_position_missing".to_string();
    };
    if current_node_id == target_node_id {
        return "arrived".to_string();
    }
    if let Some(edge) = world
        .edges
        .iter()
        .find(|edge| edge.from == current_node_id && edge.to == target_node_id)
    {
        return format!("{} -> {}", edge.direction, target_node_id);
    }
    world
        .edges
        .iter()
        .find(|edge| edge.from == current_node_id)
        .map(|edge| format!("{} -> {} then continue route", edge.direction, edge.to))
        .unwrap_or_else(|| "no_open_exit".to_string())
}

fn current_room_json(world: &WorldState, actor_id: &str) -> serde_json::Value {
    let node_id = player_node_id(world, actor_id).unwrap_or_else(|| "unknown".to_string());
    if let Some(node) = world.node(&node_id) {
        json!({
            "node_id": node.id.clone(),
            "name": node.name.clone(),
            "location_id": node.location_id.clone(),
            "kind": node.node_kind.clone(),
            "description": node.description.clone(),
        })
    } else {
        json!({ "node_id": node_id, "name": "unknown" })
    }
}

fn local_npc_for_actor<'a>(world: &'a WorldState, actor_id: &str) -> Option<&'a WorldNpc> {
    let node_id = player_node_id(world, actor_id)?;
    world.npcs.iter().find(|npc| npc.node_id == node_id)
}

fn local_npc_names_for_actor(world: &WorldState, actor_id: &str) -> Vec<String> {
    let Some(node_id) = player_node_id(world, actor_id) else {
        return Vec::new();
    };
    world
        .npcs
        .iter()
        .filter(|npc| npc.node_id == node_id)
        .map(|npc| format!("{} ({})", npc.name, npc.id))
        .collect()
}

fn local_task_for_actor<'a>(world: &'a WorldState, actor_id: &str) -> Option<&'a WorldTask> {
    let node_id = player_node_id(world, actor_id)?;
    world.tasks.iter().find(|task| task.node_id == node_id)
}

fn world_node_screen_positions(world: &WorldState) -> HashMap<String, Vec3> {
    let min_x = world
        .nodes
        .iter()
        .map(|node| node.lng_e7)
        .min()
        .unwrap_or(0) as f32;
    let max_x = world
        .nodes
        .iter()
        .map(|node| node.lng_e7)
        .max()
        .unwrap_or(1) as f32;
    let min_y = world
        .nodes
        .iter()
        .map(|node| node.lat_e7)
        .min()
        .unwrap_or(0) as f32;
    let max_y = world
        .nodes
        .iter()
        .map(|node| node.lat_e7)
        .max()
        .unwrap_or(1) as f32;
    let span_x = (max_x - min_x).abs().max(1.0);
    let span_y = (max_y - min_y).abs().max(1.0);
    world
        .nodes
        .iter()
        .enumerate()
        .map(|(index, node)| {
            let normalized_x = (node.lng_e7 as f32 - min_x) / span_x;
            let normalized_y = (node.lat_e7 as f32 - min_y) / span_y;
            let jitter = ((index % 3) as f32 - 1.0) * 8.0;
            (
                node.id.clone(),
                Vec3::new(
                    -320.0 + normalized_x * 640.0 + jitter,
                    180.0 - normalized_y * 360.0 - jitter,
                    0.0,
                ),
            )
        })
        .collect()
}

fn native_now_epoch() -> i64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_secs() as i64)
        .unwrap_or_default()
}

