    #[test]
    fn rendering_bevy_app_installs_window_and_visual_evidence_anchor() {
        let world = WorldState::trillionnium_default_map_fixture();
        let mut app = App::new();
        app.add_plugins(MinimalPlugins)
            .add_plugins(TrillionniumWorldBevyPlugin::new(world, "local-player"))
            .add_systems(Startup, spawn_native_render_scene);
        app.update();
        let world = app.world_mut();
        let mut anchors = world.query::<&BevyWorldRenderEvidenceAnchor>();
        assert!(anchors.iter(world).any(|anchor| {
            anchor.contract_version == TRILLIONNIUM_WORLD_BEVY_NATIVE_CLIENT_CONTRACT
                && anchor.package_name == TRILLIONNIUM_WORLD_BEVY_ANDROID_PACKAGE
                && anchor.node_count == 24
        }));
    }

    #[test]
    fn bevy_update_applies_queued_intent_through_rust_command_layer() {
        let world = WorldState::fixture();
        let (mut app, _report) = build_native_bevy_app(world, "local-player");
        queue_native_move_east(&mut app, "local-player");
        app.update();

        let response = app
            .world()
            .get_resource::<LastNativeCommandResponse>()
            .expect("native response");
        assert!(response.response_json.contains(WORLD_API_CONTRACT));
        let world = app.world().resource::<AuthoritativeWorldResource>();
        assert_eq!(
            world
                .state
                .positions
                .iter()
                .find(|position| position.actor_id == "local-player")
                .map(|position| position.node_id.as_str()),
            Some("league-coliseum")
        );
    }

    #[test]
    fn playable_bevy_input_system_queues_movement_and_applies_tactics() {
        let world = WorldState::fixture();
        let (mut app, _report) = build_native_bevy_app(world, "local-player");
        app.insert_resource(ButtonInput::<KeyCode>::default());
        {
            let mut input = app.world_mut().resource_mut::<ButtonInput<KeyCode>>();
            input.press(KeyCode::KeyR);
        }
        app.add_systems(Update, handle_native_keyboard_input);
        app.update();
        {
            let mut input = app.world_mut().resource_mut::<ButtonInput<KeyCode>>();
            input.clear();
            input.press(KeyCode::KeyT);
        }
        app.update();
        let character = app.world().resource::<NativeTacticsCharacter>();
        assert!(character
            .character
            .skill_ids
            .iter()
            .any(|skill| skill == "basic_unarmed"));
        let log = app.world().resource::<NativeGameplayLog>();
        assert_eq!(log.last_result, "skill_training_recorded");
    }

