    #[test]
    fn native_control_actions_drive_rust_state_tactics_and_snapshot_restore() {
        let actor_id = "local-player";
        let mut world = native_bevy_playable_fixture();
        let mut character = WorldTrillionniumCharacter::default_for(actor_id);
        let mut log = NativeGameplayLog::default();
        let mut first_playable = NativeFirstPlayableRuntime::default();

        apply_native_first_playable_action(
            &mut world,
            &mut character,
            &mut log,
            &mut first_playable,
            actor_id,
            NativeControlAction::Train,
        );
        assert!(character
            .skill_ids
            .iter()
            .any(|skill| skill == "basic_unarmed"));

        apply_native_first_playable_action(
            &mut world,
            &mut character,
            &mut log,
            &mut first_playable,
            actor_id,
            NativeControlAction::Move {
                direction: "north".to_string(),
            },
        );
        assert_eq!(
            player_node_id(&world, actor_id).as_deref(),
            Some("league-coliseum")
        );

        let snapshot =
            native_playable_save_snapshot(&world, &character, &log, &first_playable, actor_id);
        let (restored_world, restored_character, restored_log, restored_first_playable) =
            native_restore_playable_save_snapshot(snapshot);
        assert_eq!(
            player_node_id(&restored_world, actor_id).as_deref(),
            Some("league-coliseum")
        );
        assert!(restored_character
            .skill_ids
            .iter()
            .any(|skill| skill == "basic_unarmed"));
        assert!(restored_log.turn >= 2);
        assert!(restored_first_playable
            .completed_steps
            .iter()
            .any(|step| step == "arrive_at_first_objective"));
    }

    #[test]
    fn first_playable_evidence_completes_core_loop() {
        let evidence = native_first_playable_evidence_for_fixture("local-player");
        assert_eq!(
            evidence.contract_version,
            TRILLIONNIUM_WORLD_BEVY_FIRST_PLAYABLE_CONTRACT
        );
        assert_eq!(
            evidence
                .acceptance
                .get("status")
                .and_then(|value| value.as_str()),
            Some("host_first_playable_loop_green")
        );
        assert_eq!(
            evidence
                .current_room
                .get("node_id")
                .and_then(|value| value.as_str()),
            Some("league-coliseum")
        );
        assert!(evidence.runtime.reward_claimed);
        assert!(evidence.runtime.equipment_ready);
        assert_eq!(
            evidence.runtime.last_feedback,
            "Reward equipped: Route Guard Staff ready"
        );
        assert!(evidence.runtime.feedback_events.len() >= 6);
        assert_eq!(
            evidence
                .acceptance
                .get("game_feedback_contract")
                .and_then(|value| value.as_str()),
            Some(TRILLIONNIUM_WORLD_BEVY_GAME_FEEDBACK_CONTRACT)
        );
        assert_eq!(
            evidence
                .acceptance
                .get("tile_rpg_ui_contract")
                .and_then(|value| value.as_str()),
            Some(TRILLIONNIUM_WORLD_BEVY_TILE_RPG_UI_CONTRACT)
        );
        assert_eq!(
            evidence
                .acceptance
                .get("tile_rpg_ui_green")
                .and_then(|value| value.as_bool()),
            Some(true)
        );
        assert_eq!(
            evidence
                .acceptance
                .get("tile_rpg_interaction_contract")
                .and_then(|value| value.as_str()),
            Some(TRILLIONNIUM_WORLD_BEVY_TILE_RPG_INTERACTION_CONTRACT)
        );
        assert_eq!(
            evidence
                .acceptance
                .get("tile_rpg_interaction_green")
                .and_then(|value| value.as_bool()),
            Some(true)
        );
        assert_eq!(evidence.runtime.map_scene, "arena_outdoor");
        assert_eq!(
            evidence.runtime.npc_dialogue_state,
            "mentor_training_complete"
        );
        assert_eq!(
            evidence.runtime.combat_scene_state,
            "combat_returned_to_map"
        );
        assert_eq!(evidence.runtime.last_tile_step, "step_north");
        assert!(evidence.runtime.walk_cycle_frame >= 1);
        assert_eq!(evidence.runtime.active_scene_layer, "arena_outdoor_tilemap");
        assert_eq!(evidence.runtime.tilemap_variant, "arena_outdoor");
        assert!(evidence.runtime.movement_lock_observed);
        assert!(!evidence.runtime.movement_input_locked);
        assert_eq!(evidence.runtime.tile_step_progress_percent, 100);
        assert_eq!(evidence.runtime.movement_from_tile, "mentor_room_exit_tile");
        assert_eq!(evidence.runtime.movement_to_tile, "arena_gate_tile");
        assert!(evidence.runtime.tile_interpolation_samples.len() >= 3);
        assert!(evidence
            .runtime
            .scene_history
            .iter()
            .any(|scene| scene == "combat_encounter_overlay"));
        assert!(evidence
            .runtime
            .npc_behavior_history
            .iter()
            .any(|state| state == "training_feedback_visible"));
        assert!(evidence
            .runtime
            .enemy_behavior_history
            .iter()
            .any(|state| state == "enemy_damage_feedback_visible"));
        assert_eq!(
            evidence
                .acceptance
                .get("scene_transition_playability_contract")
                .and_then(|value| value.as_str()),
            Some(TRILLIONNIUM_WORLD_BEVY_SCENE_TRANSITION_PLAYABILITY_CONTRACT)
        );
        assert_eq!(
            evidence
                .acceptance
                .get("scene_transition_playability_green")
                .and_then(|value| value.as_bool()),
            Some(true)
        );
        assert!(evidence.runtime.xp >= 40);
        assert!(evidence.runtime.coins >= 10);
        assert!(evidence
            .completed_loop
            .iter()
            .any(|step| step == "resolve_first_combat"));
    }

